def huella_cita(cita):
    """AC90, según la spec: el sha256 de la cita normalizada (NFKD sin marcas, sin caja, espacios colapsados)."""
    plegada = ''.join(c for c in unicodedata.normalize('NFKD', cita) if unicodedata.category(c) != 'Mn').lower()
    return hashlib.sha256(' '.join(plegada.split()).encode('utf-8')).hexdigest()


def entrada_spec(cita, seudonimo, docs, motivo='coaparición judicial revisada; no identifica'):
    """Una entrada de `citas:` según la spec (AC90(b), corrección de la enmienda 27): la huella de la cita normalizada,
    que admite ese texto exacto; sin prefijos."""
    return {'seudonimo': seudonimo, 'sha256': huella_cita(cita), 'docs': sorted(docs), 'origen': 'estado-2026-10-07',
            'motivo': motivo}


def prefijos_spec(cita):
    """Los `prefijos` del esquema anterior de una entrada (enmienda 25, retirados en la corrección de la enmienda
    27): los 16 hex del sha256 de cada prefijo normalizado de 40 caracteres o más. Solo para probar que ya no admiten
    nada."""
    plegada = ''.join(c for c in unicodedata.normalize('NFKD', cita) if unicodedata.category(c) != 'Mn').lower()
    normalizada = ' '.join(plegada.split())
    return sorted({hashlib.sha256(normalizada[:k].rstrip().encode('utf-8')).hexdigest()[:16]
                   for k in range(40, len(normalizada)) if len(normalizada[:k].rstrip()) >= 40})


def cita_permitida(cita, docs, seudonimo=SEUDO, huella=None):
    """Una entrada de `citas:` (AC90) para la cita dada (o con otra `huella`)."""
    return {'seudonimo': seudonimo, 'sha256': huella or huella_cita(cita), 'docs': list(docs), 'origen': ORIGEN,
            'motivo': MOTIVO_CITA}

