def permitidos(*aristas, alias=()):
    """Cada arista es (seudónimo, otro, tipo) o (seudónimo, otro, tipo, docs)."""
    def fila(s, o, t, docs=None):
        return {'seudonimo': s, 'otro': o, 'tipo': t, 'kinds': ['judicial'],
                **({'docs': list(docs)} if docs is not None else {}), 'origen': ORIGEN, 'motivo': MOTIVO}
    return {'aristas': [fila(*a) for a in aristas],
            'alias': [{'id': i, 'permitidos': list(p)} for i, p in alias]}


def ev(doc, kind='judicial', unidad='u'):
    """Una evidencia de una tripleta: capa y documento."""
    return {'kind': kind, 'doc': doc, 'unidad': unidad}


CHECK = REAL_REPO / 'pipeline' / 'scripts' / 'seudonimos_check.py'


def repo_sintetico(tmp, files=None, lista=None):
    """Un árbol mínimo con la forma del repo (seudónimos, overlay, lista y registro), en un repo git con todo añadido: el
    árbol público son los documentos de `data/` que sigue git (AC30)."""
    repo = Path(tmp)
    base = {S.PSEUDONYMS_REL: PSEUDONYMS,
            S.PERMITIDOS_REL: S.volcar_permitidos(lista or permitidos((SEUDO, SOC, 'PAID'))),
            f'{S.RELATIONS_REL}/relations.yaml': 'deny: []\n',
            S.REGISTRO_REL: 'rectificaciones: []\n'}
    for rel, text in {**base, **(files or {})}.items():
        path = repo / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(textwrap.dedent(text), encoding='utf-8')
    for args in (['init', '-q'], ['add', '-A']):
        subprocess.run(['git', '-C', str(repo), *args], check=True, capture_output=True, timeout=120)
    return repo


def cargar_check():
    """`seudonimos_check.py` como módulo, para llamarlo en el proceso del test."""
    spec = importlib.util.spec_from_file_location('seudonimos_check', CHECK)
    check = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(check)
    return check


_CORRER_CON_REFS_LEGIBLES = ("import runpy, sys\n"
                             "pipeline, literal, script, *resto = sys.argv[1:]\n"
                             "sys.path.insert(0, pipeline)\n"
                             "from src import seudonimos\n"
                             "seudonimos._ALFABETO_REFERENCIAS = frozenset(literal)\n"
                             "sys.argv = [script, *resto]\n"
                             "runpy.run_path(script, run_name='__main__')\n")


def ejecutar_check(repo, *argv, refs_legibles=True):
    """(código, stdout + stderr) de `seudonimos_check.py` en un proceso aparte, como en el CI. Spec 072 (AC11, AC16): un proceso aparte no hereda ningún parche de estas
    pruebas: con `refs_legibles` fija el literal ancho de las referencias (`LITERAL_ANCHO_DE_REFERENCIAS`) antes de correr el script, dentro del proceso hijo; sin ello, el de producción."""
    antes = ['-c', _CORRER_CON_REFS_LEGIBLES, str(REAL_REPO / 'pipeline'), ''.join(sorted(LITERAL_ANCHO_DE_REFERENCIAS))] if refs_legibles else []
    proc = subprocess.run([sys.executable, *antes, str(CHECK), '--repo', str(repo), *map(str, argv)],
                          capture_output=True, text=True, timeout=600)
    return proc.returncode, proc.stdout + proc.stderr


def alarma(segundos):
    """AC112 (enmienda 29): corta el bloque a los `segundos` con TimeoutError: el código anterior no acababa. AC252
    (enmienda 57): la comparte con el plazo del arranque de `en_hijo` (`_con_temporizador`), que restaura el manejador y
    lo que quedaba de la alarma exterior: una `alarma` anidada ya no desarma la de fuera."""
    def cortar(*_):
        raise TimeoutError(f'el bloque no terminó en {segundos:g} s')
    return _con_temporizador(cortar, segundos=segundos)


FACTOR_DE_CPU_MAXIMO = 4.0   # AC334: un factor mayor aflojaría las cotas hasta no rechazar nada; el CI usa 2


def factor_de_cpu() -> float:
    """AC334 (enmienda 90): el factor de las cotas ABSOLUTAS de tiempo, de la variable de entorno `SM_FACTOR_DE_CPU`; sin ella
    es 1 y todo queda como antes. Un número en [1, `FACTOR_DE_CPU_MAXIMO`]: otra cosa (la cadena vacía, «abc», «nan», «inf»,
    «0.5», «1e400», «4.0001», «10») es un error que lo dice, nunca un 1 en silencio ni un valor recortado. Se lee en cada uso y
    no al importar: un valor malo hace fallar los tests de coste (y `test_el_factor_de_cpu_del_entorno_es_valido`) y no rompe
    la carga de los dos módulos de pruebas ni la precarga del servidor de `en_hijo`."""
    crudo = os.environ.get('SM_FACTOR_DE_CPU', '1')
    try:
        factor = float(crudo)
    except ValueError:
        factor = float('nan')
    if not 1 <= factor <= FACTOR_DE_CPU_MAXIMO:
        raise AssertionError(f'SM_FACTOR_DE_CPU={crudo!r}: tiene que ser un número entre 1 y {FACTOR_DE_CPU_MAXIMO:g} '
                             f'(sin la variable, 1)')
    return factor


def escalada(segundos):
    """AC335 (enmienda 90): `segundos` a factor 1 (el valor que se lee en el código y en la spec) multiplicados por el
    factor: la cota con la que se compara un tiempo, o el sobrecoste de un control (`quemar`). Los dos van por aquí
    para que un control siga siendo rechazado con el factor del CI (cota y coste crecen juntos). Las razones ×4/×1 y los
    presupuestos de trabajo (`_TOPE_EXENCION`, `TOPE_DE_LA_RAZON`) no son tiempos absolutos y no se escalan."""
    return segundos * factor_de_cpu()


@contextlib.contextmanager
def presupuesto(test, segundos):
    """AC112 (enmienda 29): el bloque termina en menos de `segundos`. Una alarma lo corta a las diez veces. AC335
    (enmienda 90): `segundos` (la cota y su alarma) llevan el factor de `SM_FACTOR_DE_CPU`."""
    segundos = escalada(segundos)
    inicio = time.perf_counter()
    with alarma(10 * segundos):
        yield
    test.assertLess(time.perf_counter() - inicio, segundos)


class _Cuenta:
    """AC233 (enmienda 50): lo que ha medido un bloque de coste: el tiempo que suman sus `medida()` y cuántas fueron.
    AC234 (enmienda 51): y el de cada consulta con nombre (`medida('nombres_en')`), por separado."""

    def __init__(self, reloj):
        self.reloj, self.tiempo, self.veces = reloj, 0.0, 0
        self.por_consulta = collections.defaultdict(float)


_cuentas = []


@contextlib.contextmanager
def medida(consulta=None):
    """AC233 (enmienda 50): lo ÚNICO que cronometran `mediana`, `crece_lineal` y `razon_de_crecimiento` de un bloque: la
    consulta. El bloque prepara FUERA las entradas y las cachés (`vaciar_caches`); aquí se recoge la basura antes de
    arrancar el reloj y el recolector queda parado mientras dura la consulta (el coste del algoritmo, no el del
    recolector, que crece con lo que hay vivo) y se restaura al salir, falle o no. Un coste fijo o lineal dentro de la
    medida comprime la razón ×4/×1 y esconde un cuadrático (40c: 1,22 a 1,85 medidos frente a 4,1 reales, por
    cronometrar `vaciar_caches()` y `gc.collect()` de cada consulta). Un bloque que no la usa no mide nada: falla.
    Fuera de una medición (el mismo código llamado a secas), no hace nada. AC234 (enmienda 51): con `consulta`, el
    tiempo se anota además bajo ese nombre (`razones_por_consulta`): cada consulta tiene su razón, y una regresión en
    una no se diluye entre las demás."""
    if not _cuentas:
        yield
        return
    cuenta = _cuentas[-1]
    gc.collect()
    activo = gc.isenabled()
    gc.disable()
    inicio = cuenta.reloj()
    try:
        yield
    finally:
        transcurrido = cuenta.reloj() - inicio
        cuenta.tiempo += transcurrido
        cuenta.veces += 1
        if consulta is not None:
            cuenta.por_consulta[consulta] += transcurrido
        if activo:
            gc.enable()


PLAZO_DEL_HIJO = 120.0
MODULOS_DE_PRUEBAS = ('test_seudonimos.py', 'test_qa_esc_apply.py')
_CONTROLES = []   # los controles que aplica cada hijo antes de ejecutar su destino (`controlando`)
_SERVIDOR = []   # el contexto de bifurcación, creado al primer uso (`_servidor`)


@contextlib.contextmanager
def controlando(*controles):
    """AC243 (enmienda 55): registra `controles` para que TODO hijo bifurcado mientras dure el bloque los aplique antes
    de ejecutar su destino. Cada control es una función de módulo (o un `functools.partial` de una) que devuelve un
    gestor de contexto, p. ej. `functools.partial(con_control_cuadratico, '_nombres_en', 1, 3)`: los hijos NO heredan
    los parches del proceso de la prueba (nacen de un proceso base limpio), así que un control se pasa por nombre y con
    argumentos serializables."""
    antes = len(_CONTROLES)
    _CONTROLES.extend(controles)
    try:
        yield
    finally:
        del _CONTROLES[antes:]


def _servidor():
    """AC243 (enmienda 55): el contexto `forkserver` de `multiprocessing`: su servidor es un intérprete NUEVO (no una
    copia del proceso de las pruebas, que puede estar tan caliente como quiera: fixtures, `setUp`, comprobaciones
    funcionales, memoria en RAM, cachés auxiliares), que solo importa los módulos de pruebas, sin ejecutar nada de lo
    que se mide ni se prepara. TODO hijo se bifurca desde él; ninguno hereda nada del proceso que lo pide."""
    if not _SERVIDOR:
        contexto = multiprocessing.get_context('forkserver')
        contexto.set_forkserver_preload([
            nombre for nombre, modulo in list(sys.modules.items())
            if os.path.basename(getattr(modulo, '__file__', None) or '') in MODULOS_DE_PRUEBAS])
        _SERVIDOR.append(contexto)
    return _SERVIDOR[0]


# AC253 (enmienda 58): las funciones de supervisión de `en_hijo`. `_ahora` es una `EXENCION` de la guarda (lee el reloj
# en el proceso de las pruebas) y comprueba en ejecución, por nombre cualificado, que la llama una de ellas: una prueba,
# o un método homónimo de una supervisora, que la llame no obtiene un reloj.
SUPERVISORES = frozenset({'en_hijo', '_esperar_el_eof', '_con_temporizador'})


def _ahora():
    llamador = sys._getframe(1).f_code
    if llamador.co_filename != sys._getframe(0).f_code.co_filename or llamador.co_qualname not in SUPERVISORES:
        raise AssertionError(f'`_ahora` leído desde `{llamador.co_qualname}`: solo lo lee la supervisión de `en_hijo`')
    return time.monotonic()


class _PlazoVencido(BaseException):
    """El plazo del padre venció durante el arranque. `BaseException`: ningún `except Exception` de `multiprocessing` la
    traga."""


def _plazo_del_arranque(fin):
    """AC245 (enmienda 56): acota hasta `fin` lo que `Process.start()` hace SIN plazo (escribir la preparación al
    servidor y esperar su PID: con el servidor detenido o la tubería saturada, la suite esperaba para siempre). Un
    `SIGALRM` cancelable en el hilo principal levanta `_PlazoVencido`."""
    def vencido(*_):
        raise _PlazoVencido
    return _con_temporizador(vencido, fin=fin)


@contextlib.contextmanager
def _con_temporizador(manejador, segundos=None, fin=None):
    """AC245 (enmienda 56), AC252 (enmienda 57): `manejador` para `SIGALRM` y la alarma real a `segundos` (o hasta
    `fin`, en `_ahora`) o, si la de fuera vence antes, a la de fuera. Lo anterior (manejador y lo que quedaba de la
    alarma exterior) se lee SIN efectos antes del `try` y se sustituye DENTRO de él: una señal en cualquier llamada de
    la instalación o de la restauración (un `SIGINT` real se atiende al volver de una llamada) deja el manejador y el
    temporizador como estaban. Cada paso de la restauración es idempotente: una señal que la interrumpe (el `SIGINT` de
    un usuario, un `SIGALRM` que venció entre dos pasos) la repite entera y se re-lanza al terminar, nunca queda a
    medias; no hay ninguna llamada entre el `finally` y el `try` del bucle, donde una señal la saltaría."""
    anterior, antes, inicio = signal.getsignal(signal.SIGALRM), signal.getitimer(signal.ITIMER_REAL), _ahora()
    try:
        signal.signal(signal.SIGALRM, manejador)
        plazo = segundos if segundos is not None else max(fin - _ahora(), 0.001)
        signal.setitimer(signal.ITIMER_REAL, min(plazo, antes[0]) if antes[0] else plazo)
        yield
    finally:
        pendiente, intentos = None, 0
        while True:
            try:
                signal.setitimer(signal.ITIMER_REAL, 0)
                signal.signal(signal.SIGALRM, anterior)
                if antes[0]:
                    signal.setitimer(signal.ITIMER_REAL, max(antes[0] - (_ahora() - inicio), 0.001), antes[1])
                break
            except BaseException as fallo:
                pendiente, intentos = fallo, intentos + 1
                if intentos == 10:
                    raise
        if pendiente is not None:
            raise pendiente


def _escribir(fd, datos):
    escrito = 0
    while escrito < len(datos):
        escrito += os.write(fd, datos[escrito:])


def _vigilar_la_cuerda(vida):
    """AC246 (enmienda 56): la «cuerda de vida» del hijo: el extremo de lectura de una tubería cuyo extremo de escritura
    solo tiene el padre. Un hilo la lee; nadie escribe nunca, así que lo único que puede llegar es el EOF (el padre la
    cerró en su `finally`, murió, o lo interrumpieron en cualquier punto del arranque) y entonces el hijo hace
    `os._exit` en el acto: ni una interrupción, ni un padre muerto, ni la pérdida del forkserver dejan un hijo vivo más
    de unos milisegundos. Límite declarado (AC246, enmienda 57): un hijo detenido a mano con `SIGSTOP` y cuyo padre
    muere por `SIGKILL` queda detenido, porque este hilo también lo está (ver `en_hijo`)."""
    def vigila():
        with contextlib.suppress(OSError):
            while os.read(vida.fileno(), 1):
                pass
        os._exit(77)
    threading.Thread(target=vigila, daemon=True).start()


def _entregar(fd, paquete, simulacion):
    """Lo último que hace el hijo: escribe el paquete entero y, solo para los metatests de la supervisión (AC240), falla
    de una de las formas que el padre debe rechazar: lo trunca, muere por SIGKILL, sale con código 3 o cierra la tubería
    y sigue vivo, después de escribirlo."""
    if simulacion == 'truncar':
        paquete = paquete[:len(paquete) // 2]
    _escribir(fd, paquete)
    if simulacion == 'matar_tras_escribir':
        os.kill(os.getpid(), signal.SIGKILL)
    elif simulacion == 'salir_con_3':
        os._exit(3)
    elif simulacion == 'cerrar_y_seguir':
        os.close(fd)
        time.sleep(60)


def _trabajo_hijo(conexion, vida, destino, argumentos, controles, simulacion):
    """AC243 (enmienda 55): lo que ejecuta CADA hijo, nacido del servidor de bifurcación: vigila su cuerda de vida
    (AC246), anuncia su PID real en el primer mensaje (`PID n\\n`), arranca en frío (`empezar_en_frio`: las 22 cachés
    vacías, comprobado), aplica los controles registrados (`controlando`), ejecuta `destino(*argumentos)` y escribe su
    resultado, o la traza de su fallo, en la tubería."""
    _vigilar_la_cuerda(vida)
    _escribir(conexion.fileno(), f'PID {os.getpid()}\n'.encode())
    try:
        empezar_en_frio()
        with contextlib.ExitStack() as pila:
            for control in controles:
                pila.enter_context(control())
            paquete = pickle.dumps(('ok', destino(*argumentos)))
    except BaseException:
        paquete = pickle.dumps(('error', traceback.format_exc()))
    _entregar(conexion.fileno(), paquete, simulacion)
    conexion.close()


def en_hijo(destino, *argumentos, plazo=PLAZO_DEL_HIJO, simulacion=None):
    """AC238 (enmienda 53), AC243 (enmienda 55): `destino(*argumentos)` en un proceso hijo bifurcado del servidor limpio
    (`_servidor`) y su resultado, que debe poder serializarse. `destino` es una función de módulo o un
    `functools.partial` de una (las clausuras locales no viajan: nada de lo del proceso de la prueba llega al hijo salvo
    por sus argumentos y por los controles de `controlando`). Es lo único que arranca una medida en frío DE VERDAD: una
    memoria por texto, por pareja, por id, en RAM o en una caché auxiliar sobrevive a cualquier reconstrucción dentro
    del mismo proceso (43a/43b: 1,5 a 2,1 s solo la primera vez; 45: precalentada en un `setUp`, en un hijo intermedio,
    en el padre) y no puede estar en un hijo que nace de un intérprete que nunca la ejecutó. El `pickle` viaja por una
    tubería privada entre el padre y su propio hijo: no es un dato de fuera.

    AC240 (enmienda 54): el PADRE supervisa al hijo, y su plazo no depende de nada que corra dentro de él. Acepta el
    resultado solo si el hijo salió con normalidad (código 0: un paquete completo de un hijo que murió por una señal, o
    que salió con otro código, no vale) y el paquete se lee entero.

    AC245 (enmienda 56): el plazo corre desde ANTES de pedir el hijo y cubre todo el ciclo: `start()` (la preparación al
    servidor y su PID, bajo `_plazo_del_arranque`), la tubería con `select` y la terminación. Vencido, se cancela, se
    mata y se falla con un `AssertionError` claro.

    AC246 (enmienda 56): el hijo no depende de lo que el padre sepa o pueda de él. Lleva una cuerda de vida (si el padre
    la cierra, muere o lo interrumpen, el hijo se mata solo en milisegundos) y anuncia su PID real en el primer mensaje:
    el padre lo mata por `os.kill(pid, SIGKILL)` y comprueba su muerte (el EOF de la tubería de resultado), sin fiarse
    de `is_alive()` ni de `exitcode` (con el forkserver perdido, `multiprocessing` da 255 con el hijo vivo).

    AC242 (enmienda 55): todo se declara inexistente antes del `try` y cada recurso se limpia por separado: ni un fallo
    del `fork` (EAGAIN), ni una excepción o un Ctrl-C en cualquier punto dejan hijo vivo ni descriptor. Todo fallo es un
    `AssertionError` con su causa.

    Límites declarados: solo POSIX (`forkserver`, el del CI); un control con memoria que sobreviva a un proceso nuevo
    (un fichero, una variable de entorno, un servicio externo) no está cubierto; cada hijo paga lo que paga un
    intérprete que nunca ejecutó lo que mide (las expresiones regulares perezosas se compilan en su primera llamada); y
    un hijo detenido a mano con `SIGSTOP` (una acción externa que ningún test ni el CI ejecutan) cuyo padre muere por
    `SIGKILL` queda detenido, porque su hilo vigilante también lo está y solo un proceso independiente por hijo (≈20 ms
    × ~860 hijos del metatest cuadrático) podría matarlo; mientras el padre vive, el plazo sí lo mata."""
    fin = _ahora() + plazo
    lectura = escritura = vida_r = vida_w = proceso = pid = None
    paquete, muerto, sin_morir = bytearray(), False, False
    try:
        lectura, escritura = _servidor().Pipe(duplex=False)
        vida_r, vida_w = _servidor().Pipe(duplex=False)
        proceso = _servidor().Process(target=_trabajo_hijo, args=(escritura, vida_r, destino, argumentos,
                                                                  tuple(_CONTROLES), simulacion))
        for intento in range(6):
            try:
                with _plazo_del_arranque(fin):
                    proceso.start()
                break
            except _PlazoVencido:
                raise AssertionError(f'el proceso hijo no arrancó en {plazo:g} s: se le mata') from None
            except (ConnectionRefusedError, FileNotFoundError):
                # el servidor acaba de caer (un cliente anterior que abortó el apretón de descriptores lo tumba: así lo
                # hace `multiprocessing`) y la siguiente petición lo relanza; si sigue sin responder, falla de verdad
                if intento == 5 or fin - _ahora() <= 0.3:
                    raise
                select.select([], [], [], 0.2)
        escritura.close()
        escritura = None
        vida_r.close()
        vida_r = None
        while True:
            resta = fin - _ahora()
            if resta <= 0 or not select.select([lectura.fileno()], [], [], resta)[0]:
                raise AssertionError(f'el proceso hijo no respondió en {plazo:g} s: se le mata')
            trozo = os.read(lectura.fileno(), 1 << 16)
            if not trozo:
                break
            paquete += trozo
            if pid is None and b'\n' in paquete:
                cabecera, _, resto = bytes(paquete).partition(b'\n')
                if not cabecera.startswith(b'PID '):
                    raise AssertionError('el proceso hijo no anunció su PID')
                pid, paquete = int(cabecera[4:]), bytearray(resto)
        resta = max(fin - _ahora(), 0)
        proceso.join(resta)
        if proceso.exitcode is None:
            raise AssertionError(f'el proceso hijo cerró la tubería y no terminó en {plazo:g} s: se le mata')
        codigo = proceso.exitcode
        muerto = codigo != 255   # 255 es el EOF del canal del servidor: no prueba que el hijo haya muerto
    finally:
        if pid is not None and not muerto:
            with contextlib.suppress(ProcessLookupError, PermissionError):
                os.kill(pid, signal.SIGKILL)
        for tubo in (vida_w, vida_r, escritura):   # la cuerda primero: el hijo que no se anunció se mata solo
            if tubo is not None:
                with contextlib.suppress(OSError):
                    tubo.close()
        if pid is not None and not muerto and lectura is not None:
            sin_morir = not _esperar_el_eof(lectura, _ahora() + 10)
        if proceso is not None:
            with contextlib.suppress(Exception):
                proceso.close()
        if lectura is not None:
            with contextlib.suppress(OSError):
                lectura.close()
        if sin_morir:
            raise AssertionError(f'el proceso hijo {pid} no murió tras SIGKILL en 10 s')
    if codigo != 0:
        raise AssertionError(f'el proceso hijo no salió con normalidad (código {codigo}; negativo, la señal que lo '
                             f'mató)')
    try:
        tipo, resultado = pickle.loads(bytes(paquete))
    except Exception as fallo:
        raise AssertionError(f'el proceso hijo dejó un paquete ilegible o truncado ({type(fallo).__name__})') from None
    if tipo == 'error':
        raise AssertionError(f'falló el proceso hijo:\n{resultado}')
    return resultado


def _esperar_el_eof(lectura, hasta) -> bool:
    """AC246 (enmienda 56): lee y descarta hasta el EOF de la tubería de resultado, que solo llega cuando el hijo ha
    muerto (la única copia viva del extremo de escritura es la suya); False si no llega antes de `hasta`."""
    while True:
        resta = hasta - _ahora()
        if resta <= 0 or not select.select([lectura.fileno()], [], [], resta)[0]:
            return False
        try:
            if not os.read(lectura.fileno(), 1 << 16):
                return True
        except OSError:
            return True


def _ejecutar_en_frio(bloque, argumentos, reloj, segundos):
    """AC233 (enmienda 50), AC238 (enmienda 53): lo que mide `bloque(*argumentos)` (el tiempo que suman sus `medida()`,
    cuántas fueron y el tiempo de cada consulta con nombre), bajo una alarma de `segundos` que cuenta también su
    preparación. Se ejecuta en el hijo de `_correr`, que arranca en frío (`_trabajo_hijo`)."""
    cuenta = _Cuenta(time.__dict__[reloj])   # el reloj va por NOMBRE: el proceso de la prueba no lo referencia (AC247)
    _cuentas.append(cuenta)
    with alarma(segundos):
        bloque(*argumentos)
    if not cuenta.veces:
        raise AssertionError('el bloque no mide nada: la consulta va dentro de `with medida():`')
    return cuenta.tiempo, cuenta.veces, dict(cuenta.por_consulta)


def _correr(bloque, argumentos, reloj, segundos) -> _Cuenta:
    """AC233 (enmienda 50): los `medida()` de una ejecución de `bloque(*argumentos)`, bajo una alarma de `segundos` (que
    cuenta también su preparación). AC235 (enmienda 52), AC238 (enmienda 53), AC243 (enmienda 55): cada ejecución es un
    PROCESO HIJO NUEVO (`en_hijo`) del servidor limpio, que empieza con las cachés vacías: el uso real mide la primera
    llamada de cada entrada, y repetir en el mismo proceso esconde un sobrecoste que solo paga la primera vez (42c:
    500 * L**2 iteraciones en la primera llamada; 43a/43b: lo mismo con una memoria por texto, por pareja o por
    `derivado`; 45: lo mismo con un proceso de la prueba o un `setUp` caliente). El mínimo de `rondas` es, así, entre
    ejecuciones con las mismas condiciones iniciales y la MISMA entrada. `bloque` es una función de módulo o un
    `functools.partial` de una. AC240: el plazo del padre es la alarma del hijo más 30 s (la del hijo salta antes y dice
    por qué)."""
    cuenta = _Cuenta(reloj)
    cuenta.tiempo, cuenta.veces, por_consulta = en_hijo(_ejecutar_en_frio, bloque, argumentos, reloj, segundos,
                                                        plazo=segundos + 30)
    cuenta.por_consulta.update(por_consulta)
    return cuenta


def _medido(bloque, argumentos, reloj, segundos) -> float:
    """AC233 (enmienda 50): el tiempo que suman los `medida()` de una ejecución de `bloque(*argumentos)`."""
    return _correr(bloque, argumentos, reloj, segundos).tiempo


def mediana(test, segundos, bloque, veces=3):
    """AC194 (enmienda 39): el tope absoluto de un presupuesto adversario, sobre la mediana de `veces` ejecuciones de
    `bloque` (una suelta con la máquina cargada no lo tumba: el CI va ~1,48× más lento que el Mac y el tope de 0,5 s ya
    se superó así una vez, con 0,589 s); cada una, bajo la alarma de diez veces el tope. AC233 (enmienda 50): solo
    cuenta lo que el bloque pone dentro de `with medida():`, el tiempo de reloj de la consulta. AC335 (enmienda 90):
    `segundos` (el tope y su alarma) llevan el factor de `SM_FACTOR_DE_CPU`."""
    segundos = escalada(segundos)
    tiempos = [_medido(bloque, (), 'perf_counter', 10 * segundos) for _ in range(veces)]
    test.assertLess(statistics.median(tiempos), segundos)


def razon_de_crecimiento(bloque, rondas=5) -> float:
    """AC194 (enmienda 39): la razón del tiempo de `bloque(4)` al de `bloque(1)` (la entrada ×4 frente a ×1): el
    criterio de un presupuesto adversario independiente de la máquina. El tiempo de CPU del proceso
    (`time.process_time`), no el de reloj: con la máquina cargada, el reloj cuenta lo que el sistema lo aparta, y más
    en la ejecución ×4, la más larga (con el de reloj, 4,65 con catorce procesos ocupados). De cada una, la mejor de
    `rondas` ejecuciones, intercaladas (×1, ×4, ×1…); cada una, bajo la alarma de diez segundos. AC233 (enmienda 50):
    solo cuenta lo que el bloque pone dentro de `with medida():`."""
    mejor = {1: None, 4: None}
    for _ in range(rondas):
        for k in mejor:
            mejor[k] = min(mejor[k] or 1e9, _medido(bloque, (k,), 'process_time', 10))
    return mejor[4] / mejor[1]


def mejor_razon(bloque, rondas, intentos, limite=4.5) -> float:
    """AC238 (enmienda 53): la menor razón (`razon_de_crecimiento`) de hasta `intentos` mediciones completas, que se
    repiten solo si la mejor pasa de `limite`. Con cada medida en un proceso hijo (`en_hijo`), una consulta lineal
    (razón de mediana 4,2, a 0,3 del límite) lo pasa de vez en cuando bajo carga ajena: AC227, con cuatro procesos
    consumiendo CPU, 2 de 20 ejecuciones (4,62 y 4,91) y 3 de 45 mediciones sueltas (hasta 4,62), frente a 4,17 a 4,33
    en 15 de 15 en el mismo proceso; una regresión cuadrática (16) lo pasa en todas."""
    mejor = None
    for _ in range(intentos):
        razon = razon_de_crecimiento(bloque, rondas)
        mejor = razon if mejor is None else min(mejor, razon)
        if mejor <= limite:
            break
    return mejor


def crece_lineal(test, bloque, rondas=5, razon=4.5, intentos=3):
    """AC194 (enmienda 39): con la entrada ×1 y ×4 (`bloque(k)`), el tiempo crece como ella, no como su cuadrado (16):
    su razón (`razon_de_crecimiento`), como mucho `razon`. El criterio principal de un presupuesto adversario.
    AC238 (enmienda 53): la mejor de hasta `intentos` mediciones (`mejor_razon`)."""
    test.assertLessEqual(mejor_razon(bloque, rondas, intentos, razon), razon)


def por_debajo_de_su_limite(bloque, limites, rondas=5, segundos=60) -> dict:
    """AC234 (enmienda 51): {consulta: mejor tiempo de CPU} de las consultas que `bloque()` mide con nombre, ejecutando
    hasta `rondas` (≥ 5; un control de coste constante, menos) veces y parando en cuanto todas bajan de su límite
    (`limites`: {consulta: segundos}): «el mejor de `rondas` está por debajo» es lo mismo que «alguna de ellas lo está»,
    y cuesta una sola cuando pasa. AC235 (enmienda 52), AC238 (enmienda 53): cada ejecución es un proceso hijo en frío
    (`_correr`) de la MISMA entrada, así que el mejor es entre ejecuciones equivalentes y una que solo cuesta la primera
    vez no se salva con las demás. La cota la exige quien llama a CADA entrada distinta, nunca al mejor de varias."""
    mejor = {}
    for _ in range(rondas):
        for consulta, tiempo in _correr(bloque, (), 'process_time', segundos).por_consulta.items():
            mejor[consulta] = min(mejor.get(consulta, tiempo), tiempo)
        if all(mejor[consulta] < limite for consulta, limite in limites.items()):
            break
    return mejor


def razones_por_consulta(bloque, rondas=7) -> dict:
    """AC234 (enmienda 51): {consulta: razón ×4/×1} de cada consulta que `bloque(k)` mide con nombre, cada una con su
    mejor tiempo de `rondas` (≥ 5) ejecuciones intercaladas (×1, ×4, ×1…): la misma razón que `razon_de_crecimiento`,
    pero sin sumar unas consultas con otras (una regresión cuadrática en una se diluía entre las demás: 41a y 41c)."""
    mejor = {1: {}, 4: {}}
    for _ in range(rondas):
        for k, tiempos in mejor.items():
            for consulta, tiempo in _correr(bloque, (k,), 'process_time', 60).por_consulta.items():
                tiempos[consulta] = min(tiempos.get(consulta, tiempo), tiempo)
    return {consulta: mejor[4][consulta] / mejor[1][consulta] for consulta in mejor[1]}


def piezas_distintas(semilla, cuantas, largo):
    """AC226 (enmienda 48): `cuantas` palabras distintas de `largo` letras, al azar con `semilla`."""
    azar, out = random.Random(semilla), set()
    while len(out) < cuantas:
        out.add(''.join(azar.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(largo)))
    return sorted(out)


def vaciar_caches():
    """AC226 (enmienda 48): vacía cada caché de funciones de `seudonimos` (`functools.lru_cache`)."""
    for funcion in vars(S).values():
        if hasattr(funcion, 'cache_clear'):
            funcion.cache_clear()


# AC232 (enmienda 50): las 22 `functools.lru_cache` de `seudonimos`, clasificadas por lo que su expulsión puede
# cambiar (ver `test_cada_cache_del_modulo_esta_clasificada`). AC241 (enmienda 54): y las que cada hijo debe encontrar
# vacías.
CLASES_DE_CACHE = {
    '_bigrama_nombre': 'valor', '_es_comilla': 'valor', '_es_identificador': 'valor', '_fichas_alias': 'valor',
    '_fichas_de': 'valor', '_listas': 'valor', '_nombre_cuenta': 'valor', '_patrones': 'valor',
    '_pilas_compuestas': 'valor', '_plegable': 'valor', '_plegada': 'valor', '_plegado_de_fecha': 'valor',
    '_sin_nombre': 'valor', '_tabla_bits': 'valor', 'nucleo_distintivo': 'valor',
    '_hash_esqueleto': 'contenido', '_mascaras': 'contenido', '_sin_restricciones': 'contenido',
    '_candidato': 'objeto', '_detector': 'objeto', '_indice_formulas': 'objeto', '_indice_pilas': 'objeto'}


# las cachés reales, antes de cualquier parche
_CACHES_REALES = {n: f for n, f in vars(S).items() if hasattr(f, 'cache_clear')}


def empezar_en_frio():
    """AC241 (enmienda 54): lo primero que hace CADA hijo antes de preparar y medir: vaciar las cachés y afirmar que las
    22 clasificadas (`CLASES_DE_CACHE`) son las que existen y están vacías (`currsize == 0`, mirando las reales y no el
    parche que las envuelva). Un control que no reenviara `cache_clear`, o un hijo que heredara un padre caliente por
    sus cachés, no arranca. El `derivado` de cada índice se construye de nuevo (`consultas_de_nombre_largo`) y
    `construyendo` afirma que se calcula dentro de la medida."""
    vaciar_caches()
    llenas = {n: f.cache_info().currsize for n, f in _CACHES_REALES.items() if f.cache_info().currsize}
    if set(_CACHES_REALES) != set(CLASES_DE_CACHE) or llenas:
        raise AssertionError(f'el hijo no arranca en frío: cachés que no son las clasificadas '
                             f'{sorted(set(_CACHES_REALES) ^ set(CLASES_DE_CACHE))} o no vacías {llenas}')


def sin_caches():
    """AC232 (enmienda 50): un parche que quita TODA caché de funciones de `seudonimos` (cada `functools.lru_cache`,
    también las apiladas, por su función sin envolver): cada llamada recalcula y cada objeto que devolvía la caché (los
    candidatos de `_candidato`) es otro con el mismo contenido, como si la caché expulsara cada entrada en cuanto se
    usa: el caso límite de la expulsión."""
    def desenvuelta(f):
        while hasattr(f, '__wrapped__'):
            f = f.__wrapped__
        return f
    return mock.patch.dict(vars(S), {n: desenvuelta(f) for n, f in vars(S).items() if hasattr(f, 'cache_clear')})


@contextlib.contextmanager
def disposicion(k, precalienta=None):
    """AC226 (enmienda 48): la `k`-ésima disposición en memoria de los candidatos (`_Candidato` se compara y se tabula
    por identidad: el orden de sus conjuntos depende de dónde caen). 0: en frío (cachés vacías); 1 a 4: con `_candidato`
    precalentada con las mismas filas barajadas con la semilla `k` (`precalienta(azar)`); 5 y más: en frío y con otro
    `hash` por identidad (la misma tabla con otras direcciones: la disposición que el sistema no controla; sus cachés,
    vacías al entrar y al salir, que guardan tablas por candidato)."""
    vaciar_caches()
    if 1 <= k <= 4 and precalienta:
        precalienta(random.Random(k))
    try:
        with contextlib.ExitStack() as pila:
            if k >= 5:
                pila.enter_context(mock.patch.object(
                    S._Candidato, '__hash__', lambda c, semilla=k: (id(c) * 0x9E3779B1 ^ semilla) & 0xFFFFFFFF))
            yield
    finally:
        vaciar_caches()


def _bigrama_en_referencia(texto, nombre) -> bool:
    """AC230 (enmienda 49): `S._bigrama_en` por su definición, sin optimizar: todas las palabras del texto y del nombre
    (piezas unidas por puntos de partición), y dos palabras seguidas del texto (solo palabras sin contenido entre
    ellas, `S._saltos`) que casan, en alguna lectura (`S._comunes`, `S._con_contenido`), con dos del nombre seguidas
    (saltando también las sin contenido)."""
    nombre_f, texto_f = S._fichas(nombre), S._fichas(texto)

    def palabras(fichas):
        return [(inicio, fin, palabra) for inicio in range(len(fichas.piezas))
                for fin, palabra in S._palabras_desde(fichas, inicio, 10 ** 9)]

    def alcance(fichas):
        saltos, out = S._saltos(fichas), {}
        for pieza in range(len(fichas.piezas), -1, -1):
            out[pieza] = {pieza}.union(*(out[fin] for fin in saltos.get(pieza, ())))
        return out
    del_nombre, del_texto = palabras(nombre_f), palabras(texto_f)
    alcance_n, alcance_t = alcance(nombre_f), alcance(texto_f)

    def casan(a, b):
        return len(a) == len(b) and S._con_contenido(S._comunes(a, b))
    for _, fin_a, palabra_a in del_texto:
        for inicio_b, _, palabra_b in del_texto:
            if inicio_b not in alcance_t[fin_a]:
                continue
            for _, fin_n, nombre_a in del_nombre:
                if casan(nombre_a, palabra_a) and any(
                        inicio_n in alcance_n[fin_n] and casan(nombre_b, palabra_b)
                        for inicio_n, _, nombre_b in del_nombre):
                    return True
    return False


