def filas_de_relleno(n, sociedades=False) -> list:
    """AC232 (enmienda 50): `n` filas de nombres de dos palabras que ningún texto de las pruebas nombra (cada una es una
    entrada más en la caché de `_candidato`)."""
    return [(f'{"Company" if sociedades else "Person"}:zz-relleno{k}', f'Relleno{k} Uno{k}') for k in range(n)]


def _caso_de_determinismo(propios, ajenos, texto):
    """AC229 (enmienda 49): (filas de personas, filas de sociedades, texto) de un propio de varios nombres y de unos
    ajenos."""
    propio, ajeno = 'Person:zz-propio', 'Person:zz-ajeno'
    personas = [(propio, n) for n in propios] + [(f'{ajeno}{k}', n) for k, n in enumerate(ajenos)]
    return (personas, [('Company:zz-propio' if e == propio else f'Company:zz-ajeno{e[len(ajeno):]}', n)
                       for e, n in personas], texto)


def _casos_de_determinismo() -> dict:
    """AC226 (enmienda 48): {caso: (filas de personas, filas de sociedades, texto)} de las reproducciones de Codex 38:
    a) propio de dos nombres que dejan a la ajena «Cirro-Estrato» en dos lecturas de la misma cita, con un tope de
    110 unidades; b) un propio de 200 piezas distintas de tres letras, sus prefijos de 2 a 199 piezas como ajenos y el
    propio entero como cita (799 caracteres), con el tope real."""
    propio, ajeno = 'Person:zz-propio', 'Person:zz-ajeno'
    soc = ('Company:zz-propio', 'Company:zz-ajeno')
    a = [(propio, 'Cirro-Estrato-Alto Bajo'), (propio, 'Cirro-Estrato-Alto-Bajo'), (ajeno, 'Cirro-Estrato')]
    piezas = piezas_distintas(3, 200, 3)
    b = [(propio, '-'.join(piezas)), *((f'{ajeno}{k}', '-'.join(piezas[:k])) for k in range(2, 200))]
    comillas = 'Cirro-Estr«ato»-Al«to»-Bajo'
    return {'a': (a, [(soc[0] if e == propio else soc[1], n) for e, n in a], 'Cirro-Estrato-Alto-Bajo'),
            'a con comillas': (a, [(soc[0] if e == propio else soc[1], n) for e, n in a], comillas),
            'b': (b, [(soc[0] if e == propio else f'{soc[1]}{e[len(ajeno):]}', n) for e, n in b], '-'.join(piezas)),
            **{caso: _caso_de_determinismo(*datos) for caso, datos in
               {**_LECTURAS_DEL_MISMO_NOMBRE, **_HOMONIMOS}.items()}}


def _resultados_de_determinismo(caso, topes, sociedades=False, relleno=0, orden=None) -> list:
    """Los resultados de un caso de `_casos_de_determinismo` (los nombres que `_nombres_en` denuncia; en `sociedades`,
    los motivos de `problemas_dato_civil`) con cada tope del presupuesto de `topes`; el índice, construido aquí (una
    vez): bajo la disposición que esté en curso. AC232: con las filas del caso barajadas con la semilla `orden`
    (ninguna: en su orden) y `relleno` filas de relleno (`filas_de_relleno`) metidas entre la primera mitad y la
    segunda, que expulsan de la caché de `_candidato` los candidatos de las primeras."""
    personas, sociedades_filas, texto = _casos_de_determinismo()[caso]
    filas = list(sociedades_filas if sociedades else personas)
    if orden is not None:
        random.Random(orden).shuffle(filas)
    medio = len(filas) // 2
    filas[medio:medio] = filas_de_relleno(relleno, sociedades)
    if sociedades:
        propio, agrupadas = 'Company:zz-propio', {}
        for e, n in filas:
            agrupadas.setdefault(e, set()).add(n)
        indice = S.indice_sociedades(agrupadas)
    else:
        indice = S.indice_civiles(filas, frozenset())
    out = []
    for tope in topes:
        with mock.patch.object(S, '_TOPE_EXENCION', tope):
            out.append(S.problemas_dato_civil(texto, 'contenido', ({}, {}), indice, frozenset({propio}))
                       if sociedades else sorted(S._nombres_en(texto, indice, frozenset({'Person:zz-propio'}))))
    return out


def _resultado_de_determinismo(caso, tope, sociedades=False, relleno=0, orden=None) -> list:
    """El resultado de `_resultados_de_determinismo` con un solo tope."""
    return _resultados_de_determinismo(caso, [tope], sociedades, relleno, orden)[0]


def familia_del_bigrama(n, alternativas=('a-b', 'a-8'), pieza='ab', separador='-'):
    """AC230 (enmienda 49): (el nombre de n piezas «ab» y una «zz» final, el texto de 2(n-1) elecciones de UN solo
    `Random(17)`) de la reproducción de Codex 39b-2."""
    azar = random.Random(17)
    return (separador.join([pieza] * (n - 1) + ['zz']),
            '-'.join(azar.choice(alternativas) for _ in range(2 * (n - 1))))


def consulta_del_bigrama(que, nombre, texto):
    """AC233 (enmienda 50): `que` (el nombre de `_nombra_extremo` o de `_menciona_extremo` en `seudonimos`) del extremo
    `Company:propio-x` con ese `nombre` sobre ese `texto`, en frío: lo que prepara (el texto normalizado, las cachés
    vacías) va antes; solo la consulta se mide (`medida`). AC243 (enmienda 55): `que` va por nombre, para que el hijo la
    resuelva en su `seudonimos` (con los controles registrados)."""
    propio = 'Company:propio-x'
    normalizado = S._normalizar(texto)
    vaciar_caches()   # sin cachés: se mide construir, no recordar
    consulta = getattr(S, que)
    with medida():
        return consulta(normalizado, {propio}, {}, {propio: [nombre]})


def bloque_del_bigrama(que, base, k):
    """AC233 (enmienda 50), AC243 (enmienda 55): diez consultas del bigrama sobre la familia de `base * k` piezas."""
    for _ in range(10):
        consulta_del_bigrama(que, *familia_del_bigrama(base * k))


def razones_del_bigrama(que, bases=(8, 16, 32), intentos=1) -> dict:
    """AC233 (enmienda 50): {base: razón ×4/×1} de `que` (por nombre) sobre la familia de `familia_del_bigrama` de
    `base` piezas, diez consultas por medición (CPU del proceso). AC238 (enmienda 53): con `intentos` > 1, la mejor de
    hasta esas mediciones (`mejor_razon`); el test real usa 3 y el que prueba el control cuadrático, una."""
    return {base: mejor_razon(functools.partial(bloque_del_bigrama, que, base), 3, intentos) for base in bases}


# AC222, AC234 (enmienda 51): las ocho rejillas del nombre largo: (piezas del nombre ajeno, cifras sueltas en el texto,
# nombres con espacios en vez de guiones).
REJILLAS_DE_NOMBRE_LARGO = tuple(itertools.product((2, 4), (False, True), (False, True)))
# El presupuesto con el que se compara el reloj (la razón ×4/×1) y se prueba el control cuadrático: con el real (100.000
# unidades, ~0,25 s) el trabajo constante de la exención tapa un `5 * L**2` a n = 200 (razón 1,54, medida) y solo lo
# muestra de n = 1.600 (0,57 s frente a 0,27 s) o 6.400 (4,86 s frente a 0,45 s), unos 5 s por ejecución; con
# 5.000 (~12 ms) la parte lineal se ve desde n = 200, y todas las rejillas están saturadas a 200 (lo dice el contador).
# AC238 (enmienda 53): la base de la razón sube de 200 a 300 piezas (300 y 1.200): cada medida es ahora un proceso hijo,
# cuyas primeras páginas tocadas cuestan 1 a 2 ms de CPU dentro del cronómetro, y a 200 piezas (consulta de 17 a 22
# ms) eso comprimía la razón del control `3 * L**2` en `_nombres_en` de 4,66-4,99 a 4,56-4,78 (margen de 0,06 sobre
# 4,5); a 300 es 6,38 a 7,85.
TOPE_DE_LA_RAZON, BASE_DE_LA_RAZON = 5_000, 300
# Los límites absolutos con el tope real (segundos de CPU): el predicado y los análisis, 1 s (la spec); la revisión de
# la cita del export, que la lee dos veces, 3 s (el umbral revisado de la enmienda 48).
LIMITES_DE_NOMBRE_LARGO = {'indice_civiles': 1.0, '_nombres_en': 1.0, '_nombres_propios': 1.0,
                           'problemas_dato_civil': 1.0, 'identifica_explicitamente': 1.0, 'problemas_seudonimo': 3.0}
# AC236 (enmienda 52): el predicado a 400 piezas y 16.000 caracteres (4.000 elecciones), 2 s de CPU. Medido
# (`identifica_explicitamente` con «alias Zz Test», que SÍ identifica en las ocho rejillas; mejor de cinco, en frío):
# 0,33 a 0,87 s sin carga (0,80 a 0,87 s en las cuatro rejillas sin espacios, 0,33 a 0,37 s en las demás) y 0,54 a
# 1,24 s con ocho procesos consumiendo CPU; con 2 s, el margen es del 61 % sobre el peor caso con carga (25 % pedía
# 1,55 s) y del 130 % sin ella. A 96 piezas sigue en 1 s (0,01 a 0,03 s medidos, 0,03 s con carga).
LIMITE_DEL_PREDICADO_A_400 = 2.0


def limites_de_nombre_largo(n) -> dict:
    """AC236 (enmienda 52): {consulta: segundos} de las consultas de una rejilla de `n` piezas. AC335 (enmienda 90): con el
    factor de `SM_FACTOR_DE_CPU` ya aplicado (`escalada`): quien los recibe los compara tal cual."""
    limites = LIMITES_DE_NOMBRE_LARGO
    if n >= 400:
        limites = {**LIMITES_DE_NOMBRE_LARGO, 'identifica_explicitamente': LIMITE_DEL_PREDICADO_A_400}
    return {consulta: escalada(segundos) for consulta, segundos in limites.items()}


def rejilla_de_nombre_largo(rejilla, n, elecciones=None, semilla=3, letra='a'):
    """AC234 (enmienda 51): (propio, anidado, ajeno, texto) de una rejilla: el nombre propio de n piezas «ab», el propio
    anidado (n - 2), el ajeno de 2 o 4, y UN texto de `elecciones` (por omisión 2n) entre «a-b» y «a-8» (cifras
    sueltas) o entre «ab» y «a8» (con espacios) unidas por guiones, como la reproducción de Codex 41b (los cuatro
    textos de n que medía AC222 hasta ahora saturaban la exención a 4n piezas, no a n). AC235 (enmienda 52): con otra
    `semilla` y otra `letra` (en lugar de la «a» de «ab»), otra entrada de la misma familia: los intentos en frío de un
    mismo caso no repiten ni el texto ni los nombres."""
    ajeno_piezas, sustituidas, espacios = rejilla
    junta = ' ' if espacios else '-'   # con espacios, los nombres cortan y el texto parte
    azar = random.Random(semilla)
    pieza = letra + 'b'
    piezas = [pieza, letra + '8'] if sustituidas else [pieza]
    pares = [letra + '-b', letra + '-8'] if sustituidas else [letra + '-b']
    texto = '-'.join(azar.choice(piezas) if espacios else azar.choice(pares) for _ in range(elecciones or 2 * n))
    return junta.join([pieza] * n), junta.join([pieza] * (n - 2)), junta.join([pieza] * ajeno_piezas), texto


def consultas_de_nombre_largo(rejilla, n, elecciones=None, publicas=False, solo=None) -> dict:
    """AC234 (enmienda 51): {consulta: preparación} de una rejilla de `n` piezas: la construcción del índice
    (`indice_civiles`) y los tres análisis que consultan lo contenido en un nombre largo (`_nombres_en`,
    `_nombres_propios` y `problemas_dato_civil`); con `publicas`, también el predicado (`identifica_explicitamente`) y
    la revisión de una cita del export (`problemas_seudonimo`). AC236 (enmienda 52): el predicado lee «alias Zz Test»,
    el nombre de pila del roster (con «alias Benito», que el roster no tiene, devolvía False sin llegar a
    `_formula_entre`: 42b inyectó 1,1 s ahí sin que nada lo notara). AC238, AC239 (enmienda 53): cada preparación, sin
    argumentos, construye FUERA del reloj lo que su consulta necesita y devuelve la función sin argumentos que se
    mide, y lo construye de nuevo cada vez (el índice nuevo tiene el `derivado` sin calcular y sus candidatos sin
    preparar). La de `indice_civiles` prepara SOLO las filas: sus candidatos se construyen por primera vez dentro de
    la medida (43a-3: el helper los preparaba antes, con los mismos nombres, y un coste por primera preparación de
    cada nombre no lo veía el reloj); las demás construyen su propio índice, civil o de sociedades: ninguna hereda el
    `derivado` de otra. Con `solo`, únicamente esas."""
    propio, anidado, ajeno, texto = rejilla_de_nombre_largo(rejilla, n, elecciones)
    personas = [('Person:zz-propio', propio), ('Person:zz-propio', anidado), ('Person:zz-ajeno', ajeno)]
    propios = {'Person:zz-propio'}
    nombres = {'Person:zz-propio': {propio}}

    def nuevo(indice):   # AC241: el índice preparado es de este intento, con el `derivado` sin calcular
        if hasattr(indice, 'derivado') and indice.derivado is not None:
            raise AssertionError('el índice preparado ya trae el `derivado` calculado: no es de este intento')
        return indice

    def civiles():
        return nuevo(S.indice_civiles(personas, frozenset()))

    def sociedades():
        return nuevo(S.indice_sociedades({'Company:zz-propio': {propio, anidado}, 'Company:zz-ajeno': {ajeno}}))

    def con_civiles(consulta):
        def prepara():
            indice = civiles()
            return lambda: consulta(indice)
        return prepara

    def con_sociedades(consulta):
        def prepara():
            indice = sociedades()
            return lambda: consulta(indice)
        return prepara

    def con_ambos(consulta):
        def prepara():
            indice, soc = civiles(), sociedades()
            return lambda: consulta(indice, soc)
        return prepara
    consultas = {
        'indice_civiles': lambda: civiles,
        '_nombres_en': con_civiles(lambda c: S._nombres_en(texto, c, frozenset(propios))),
        '_nombres_propios': con_civiles(lambda c: S._nombres_propios(texto, propios, c, nombres, evidencia=True)),
        'problemas_dato_civil': con_sociedades(lambda soc: S.problemas_dato_civil(
            texto, 'contenido', ({}, {}), soc, frozenset({'Company:zz-propio'})))}
    if publicas:
        consultas['identifica_explicitamente'] = con_ambos(lambda c, soc: S.identifica_explicitamente(
            texto + ', alias Zz Test', frozenset({SEUDO}), c, soc, nombres, propios))
        consultas['problemas_seudonimo'] = con_ambos(lambda c, soc: S.problemas_seudonimo(
            [(texto, S.CITA)], {SEUDO, *propios}, frozenset({SEUDO}), c, None, nombres, soc))
    return {c: f for c, f in consultas.items() if solo is None or c in solo}


# AC236 (enmienda 52): la función de `seudonimos` a la que apunta cada consulta. Si no se ejecuta, la cota o el contador
# no miden nada (42b: el predicado devolvía False antes de `_formula_entre`).
RUTAS_DE_NOMBRE_LARGO = {'indice_civiles': 'indice_civiles', '_nombres_en': '_nombres_en',
                         '_nombres_propios': '_nombres_propios', 'problemas_dato_civil': 'problemas_dato_civil',
                         'identifica_explicitamente': '_formula_entre', 'problemas_seudonimo': 'problemas_seudonimo'}


@contextlib.contextmanager
def espiando(*rutas):
    """AC236 (enmienda 52): cuenta las llamadas a cada `seudonimos.<ruta>` (un `Counter`) sin cambiar su respuesta."""
    llamadas = collections.Counter()
    with contextlib.ExitStack() as pila:
        for ruta in rutas:
            original = getattr(S, ruta)

            def espia(*args, _original=original, _ruta=ruta, **kwargs):
                llamadas[_ruta] += 1
                return _original(*args, **kwargs)
            pila.enter_context(mock.patch.object(S, ruta, espia))
        yield llamadas


@contextlib.contextmanager
def ejecutada(consulta):
    """AC236 (enmienda 52): lo que haga el bloque debe ejecutar la ruta de la `consulta` (`RUTAS_DE_NOMBRE_LARGO`) al
    menos una vez; si no, falla: la cota o el contador de ese caso no medirían nada."""
    ruta = RUTAS_DE_NOMBRE_LARGO[consulta]
    with espiando(ruta) as llamadas:
        yield
    if not llamadas[ruta]:
        raise AssertionError(f'{consulta}: {ruta} no se ejecutó, el caso no mide su ruta')


_CANDIDATO = S._candidato   # la caché REAL de los candidatos, antes de cualquier parche


@contextlib.contextmanager
def construyendo():
    """AC238, AC239 (enmienda 53), AC241 (enmienda 54): lo que se CONSTRUYE de verdad mientras dura el bloque:
    `derivado` (las veces que `_derivado` recibe un índice que aún no lo tiene) y `candidatos` (los fallos de la caché
    real de `_candidato` desde la entrada: cada uno ejecuta su cuerpo y construye el candidato). Una LLAMADA a
    `_candidato` no cuenta: un acierto de la caché, o de una memoria por argumentos puesta encima, no construye nada
    (44c-3: con una memoización la guarda aprobaba con cero candidatos nuevos). Un `Counter`."""
    construido, original, antes = collections.Counter(), S._derivado, _CANDIDATO.cache_info().misses

    def espia(indice):
        if getattr(indice, 'derivado', None) is None:
            construido['derivado'] += 1
        return original(indice)
    with mock.patch.object(S, '_derivado', espia):
        yield construido
    construido['candidatos'] += _CANDIDATO.cache_info().misses - antes


# AC238, AC239 (enmienda 53): lo que cada consulta construye DENTRO de su medida, y debe volver a construir en cada
# medida: `indice_civiles`, los candidatos de sus nombres; las demás, el `derivado` de su índice.
CONSTRUYE_EN_LA_MEDIDA = {'indice_civiles': 'candidatos', '_nombres_en': 'derivado', '_nombres_propios': 'derivado',
                          'problemas_dato_civil': 'derivado', 'identifica_explicitamente': 'derivado',
                          'problemas_seudonimo': 'derivado'}


def medir_nombre_largo(consulta, rejilla, n, elecciones=None):
    """AC238, AC239 (enmienda 53): UN intento de medir `consulta` en una rejilla de `n` piezas, para el bloque de
    `_correr` (es decir, dentro de un proceso hijo y con las cachés vacías): prepara FUERA del reloj sus entradas
    (`consultas_de_nombre_largo`: el índice con su `derivado` sin calcular; en `indice_civiles`, solo las filas), vacía
    las cachés y mide solo la consulta. Afirma que su ruta se ejecutó (AC236), que construyó DENTRO de la medida lo que
    le toca (`CONSTRUYE_EN_LA_MEDIDA`: si no, la medida no es en frío) y, en el predicado, que identifica (True)."""
    funcion = consultas_de_nombre_largo(rejilla, n, elecciones, publicas=True, solo=(consulta,))[consulta]()
    vaciar_caches()
    with ejecutada(consulta), construyendo() as construido:
        with medida(consulta):
            respuesta = funcion()
    if not construido[CONSTRUYE_EN_LA_MEDIDA[consulta]]:
        raise AssertionError(f'{consulta} ({rejilla}, {n} piezas) no construyó {CONSTRUYE_EN_LA_MEDIDA[consulta]} '
                             f'dentro de su medida: no es una medida en frío')
    if consulta == 'identifica_explicitamente' and respuesta is not True:
        raise AssertionError(f'{consulta} ({rejilla}, {n} piezas) no identifica: el caso no mide su ruta')


def quemar(segundos):
    """AC235, AC236 (enmienda 52): `segundos` de CPU del proceso (el reloj de estas medidas), sin hacer nada más. Gasta
    CPU, no la mide: lo usan los controles de coste, también cuando el proceso de la prueba los ejecuta para calentar.
    AC253 (enmienda 58): una `EXENCION` de la guarda. AC335 (enmienda 90): `segundos` es el valor a factor 1 y gasta
    `escalada(segundos)`: el sobrecoste de un control crece con el factor igual que la cota a la que se enfrenta."""
    fin = time.process_time() + escalada(segundos)
    while time.process_time() < fin:
        pass


@contextlib.contextmanager
def con_coste_en(ruta, segundos):
    """AC236 (enmienda 52): `seudonimos.<ruta>` con `segundos` de CPU de más, intacta su respuesta: el control de coste
    de una ruta medida. Una vez por proceso, no por llamada (`_nombres_en` se llama cien veces dentro de un árbol): la
    primera llamada de cada hijo, que nace sin memoria (AC243: un control de `controlando`)."""
    original, pendiente = getattr(S, ruta), [True]

    def con_coste(*args, **kwargs):
        if pendiente[0]:
            pendiente[0] = False
            quemar(segundos)
        return original(*args, **kwargs)
    with mock.patch.object(S, ruta, con_coste):
        yield lambda: pendiente.__setitem__(0, True)


def clave_de_formula_entre(seudonimos, civil, formulas, fichas, tope=None):
    """La clave de la memoria de un control de `_formula_entre`: el texto (sus piezas)."""
    return hash(tuple(fichas.piezas))


def clave_del_bigrama_de_27(texto, nombre):
    """La clave de la memoria de un control de `_bigrama_en`: la pareja (texto, nombre), solo con el nombre de 27
    piezas."""
    return (texto, nombre) if sum(c.isalnum() for c in nombre) == 54 else None


def clave_del_nombre_largo(nombre, *args, **kwargs):
    """La clave de la memoria de un control de `_candidato`: el nombre, si es largo."""
    return nombre if len(nombre) > 100 else None


@contextlib.contextmanager
def con_coste_la_primera_vez(ruta, segundos, clave):
    """AC238 (enmienda 53): `seudonimos.<ruta>` con `segundos` de CPU de más la primera vez que ve cada `clave(*args)`
    (si la clave no es `None`), con su respuesta intacta y una memoria propia de las que ya vio, que `vaciar_caches()`
    no borra: el control de las memorias por texto, por pareja, por nombre o por `derivado` que 43a y 43b inyectaron."""
    original, vistos = getattr(S, ruta), set()

    def con_coste(*args, **kwargs):
        k = clave(*args, **kwargs)
        if k is not None and k not in vistos:
            vistos.add(k)
            quemar(segundos)
        return original(*args, **kwargs)
    if hasattr(original, 'cache_clear'):
        con_coste.cache_clear = original.cache_clear   # `vaciar_caches()` sigue vaciando la caché de verdad
    with mock.patch.object(S, ruta, con_coste):
        yield


def _letras_del_mas_largo(indice):
    return max((len(x.cadena.letras) for lista in indice.values() for x, *_ in lista), default=0)


def gastar_iteraciones(n):
    """AC335 (enmienda 90): `n` vueltas vacías. Aparte para que un metatest compruebe cuántas se piden sin gastarlas."""
    for _ in range(n):
        pass


@contextlib.contextmanager
def con_coste_con_el_derivado_sin_calcular(modo, segundos=2.0):
    """AC238 (enmienda 53, 43b-2): `segundos` de CPU de más (o `5 * L**2` iteraciones, `modo` = 'cuadrático') cada vez
    que `_derivado` recibe un índice SIN `derivado` calculado y con un candidato de 10.000 letras o más (6.400
    piezas). AC335 (enmienda 90): los `segundos` son a factor 1 y crecen con `SM_FACTOR_DE_CPU` (`quemar`); las
    iteraciones NO: son trabajo, no tiempo, y su coste ya crece con la lentitud de la máquina (7 s en un Mac, 5,5 s en
    `sm-dev`, 14 a 18 s estimados en un runner de GitHub, frente a la cota de 1,5 s o 3 s con el factor 2); multiplicarlas
    daba 20 a 29 s en el CI frente a la alarma de 20 s del hijo de `tiempos_de_apariciones`."""
    original = S._derivado

    def con_coste(indice):
        if getattr(indice, 'derivado', None) is None and _letras_del_mas_largo(indice) >= 10_000:
            if modo == 'cuadrático':
                gastar_iteraciones(5 * _letras_del_mas_largo(indice) ** 2)
            else:
                quemar(segundos)
        return original(indice)
    with mock.patch.object(S, '_derivado', con_coste):
        yield


# El límite de la razón ×4/×1 (AC194, AC222): no se toca.
LIMITE_DE_LA_RAZON = 4.5


CONSULTAS_DE_LA_RAZON = ('indice_civiles', '_nombres_en', '_nombres_propios', 'problemas_dato_civil')


@contextlib.contextmanager
def con_tope(tope):
    """AC243 (enmienda 55): el presupuesto de la exención en `tope` (un control de `controlando`: lo aplica el hijo)."""
    with mock.patch.object(S, '_TOPE_EXENCION', tope):
        yield


def medir_a_escala(consulta, rejilla, n, k):
    """AC234 (enmienda 51), AC243 (enmienda 55): `medir_nombre_largo` a `n * k` piezas (el bloque de la razón ×4/×1)."""
    return medir_nombre_largo(consulta, rejilla, n * k)


def razones_de_nombre_largo(rejilla, n=BASE_DE_LA_RAZON, tope=TOPE_DE_LA_RAZON, rondas=9, solo=None,
                            intentos=1) -> dict:
    """AC234 (enmienda 51): {consulta: razón ×4/×1} (de n a 4n piezas) de cada consulta de la rejilla, por separado y
    con el presupuesto de la exención en `tope`. AC238 (enmienda 53): cada medida de cada consulta es un proceso hijo
    con sus entradas nuevas (`medir_nombre_largo`: el índice con su `derivado` y los candidatos se construyen de nuevo,
    y el `derivado` de una consulta no abarata a la siguiente) y la razón es entre la MISMA entrada a n y a 4n piezas.
    AC237 (enmienda 52): con `solo`, únicamente esas consultas (la misma medida: el control cuadrático de una no
    necesita medir las demás). Con `intentos` > 1, la mejor (la menor) razón de cada consulta en hasta `intentos`
    mediciones completas, repitiendo solo las que pasan del límite: una regresión cuadrática lo supera en todas y el
    ruido de una carga ajena solo en alguna. `_nombres_propios` es lineal exacto (4,0 de mediana, a un 12 % del límite)
    y, sin intentos, pasaba de 4,5 en 2 de 24 mediciones con ocho procesos consumiendo CPU (4,56 y 4,59, con 9 y con 21
    rondas; en una de las 20 ejecuciones bajo carga, 4,53) y en 1 de 18 sin carga (4,50, con 15 rondas): más rondas no
    lo arreglan, repetir la medición sí."""
    mejor, pendientes = {}, list(CONSULTAS_DE_LA_RAZON if solo is None else solo)
    with controlando(functools.partial(con_tope, tope)):
        for _ in range(intentos):
            for consulta in tuple(pendientes):
                razon = razones_por_consulta(functools.partial(medir_a_escala, consulta, rejilla, n), rondas)[consulta]
                mejor[consulta] = min(mejor.get(consulta, razon), razon)
                if mejor[consulta] <= LIMITE_DE_LA_RAZON:
                    pendientes.remove(consulta)
            if not pendientes:
                break
    return mejor


class _Trabajo:
    """AC234 (enmienda 51): lo que ha gastado una consulta sin reloj: los `_Presupuesto` que creó y las veces que llamó
    a `_hay_lectura` (el respaldo de `_a_la_vez`, que la exención no debe usar en estas rejillas)."""

    def __init__(self):
        self.presupuestos, self.lecturas = [], 0

    @property
    def unidades(self) -> int:
        return max((p.gastado for p in self.presupuestos), default=0)

    @property
    def agotado(self) -> bool:
        return any(p.agotado for p in self.presupuestos)


@contextlib.contextmanager
def trabajo():
    """AC234 (enmienda 51): un `_Trabajo` con lo que gasta el bloque. Son unidades abstractas (AC224): con el mismo
    tope, función solo de la entrada y no de la carga de la máquina, a diferencia del reloj."""
    cuenta, original, presupuesto = _Trabajo(), S._hay_lectura, S._Presupuesto

    class Anotado(presupuesto):
        def __init__(self):
            super().__init__()
            cuenta.presupuestos.append(self)

    def contando(*args, **kwargs):
        cuenta.lecturas += 1
        return original(*args, **kwargs)
    with mock.patch.object(S, '_Presupuesto', Anotado), mock.patch.object(S, '_hay_lectura', contando):
        yield cuenta


_Resumen = collections.namedtuple('_Resumen', 'unidades lecturas agotado presupuestos')


def _trabajo_en_el_hijo(rejilla, n, tope, elecciones):
    empezar_en_frio()
    out = {}
    with mock.patch.object(S, '_TOPE_EXENCION', tope):
        for consulta, prepara in consultas_de_nombre_largo(rejilla, n, elecciones).items():
            if consulta != 'indice_civiles':
                funcion = prepara()
                vaciar_caches()
                with ejecutada(consulta), trabajo() as hecho:
                    funcion()
                if not hecho.presupuestos:
                    raise AssertionError(f'{consulta} ({rejilla}, {n} piezas) no creó ningún presupuesto de exención')
                out[consulta] = _Resumen(hecho.unidades, hecho.lecturas, hecho.agotado, len(hecho.presupuestos))
    return out


def trabajo_de_nombre_largo(rejilla, n, tope, elecciones=None) -> dict:
    """AC234 (enmienda 51): {consulta: `_Resumen`} (unidades gastadas, llamadas a `_hay_lectura`, agotado,
    presupuestos) de los tres análisis de la rejilla de `n` piezas con ese `tope`. AC236 (enmienda 52): cada uno
    ejecutó su función (`ejecutada`) y creó al menos un presupuesto (con ninguno, las unidades valen 0 y «sin saltos y
    por debajo del tope» se cumple en vacío). AC241 (enmienda 54): en un PROCESO HIJO, con el resumen de vuelta por la
    tubería: ejecutarlo en el padre, con las mismas entradas que se miden después, le poblaba la memoria que los hijos
    heredan (44a-1: un `5 * L**2` solo la primera vez por texto en `_nombres_en` pasaba las ocho rejillas de AC222,
    razón 2,38 y 8,87 sin el calentamiento)."""
    return en_hijo(_trabajo_en_el_hijo, rejilla, n, tope, elecciones)


@contextlib.contextmanager
def con_control_cuadratico(funcion, posicion_del_indice, c=5):
    """AC234 (enmienda 51): `seudonimos.<funcion>` con un bucle de `c * L**2` iteraciones antes de devolver, intacta, su
    respuesta; L, las letras del candidato más largo del índice que recibe (el argumento `posicion_del_indice`): la
    regresión cuadrática que 41a y 41c inyectaron y que el test de AC222 dejaba pasar. AC237 (enmienda 52): con `c`
    (5 por omisión; el metatest prueba también 3)."""
    original = getattr(S, funcion)

    def con_bucle(*args, **kwargs):
        respuesta = original(*args, **kwargs)
        for _ in range(int(c * max(len(x.cadena.letras) for lista in args[posicion_del_indice].values()
                                   for x, *_ in lista) ** 2)):
            pass
        return respuesta
    with mock.patch.object(S, funcion, con_bucle):
        yield


