def _aparicion_en_personas(n):
    """AC228 (enmienda 48), AC238 (enmienda 53): la consulta de `_nombres_en` sobre un propio de n piezas «ab», un ajeno
    «ab-ab» dentro y un texto de 2n elecciones entre «a-b» y «a-8»; el índice civil, construido de nuevo."""
    azar = random.Random(17)
    nombre = '-'.join(['ab'] * n)
    texto = '-'.join(azar.choice(['a-b', 'a-8']) for _ in range(2 * n))
    civiles = S.indice_civiles([('Person:zz-propio', nombre), ('Person:zz-ajeno', 'ab-ab')], frozenset())
    return lambda: S._nombres_en(texto, civiles, frozenset({'Person:zz-propio'}))


def _aparicion_en_sociedades(n):
    """AC228, AC238: lo mismo con el índice de sociedades y `problemas_dato_civil`."""
    azar = random.Random(17)
    nombre = '-'.join(['ab'] * n)
    texto = '-'.join(azar.choice(['a-b', 'a-8']) for _ in range(2 * n))
    indice = S.indice_sociedades({'Company:zz-propio': {nombre}, 'Company:zz-ajeno': {'ab-ab'}})
    return lambda: S.problemas_dato_civil(texto, 'contenido', ({}, {}), indice, frozenset({'Company:zz-propio'}))


def _aparicion_caliente(n):
    """Una preparación que calcula el `derivado` antes de vaciar las cachés y del cronómetro (como `preparar(n)` fuera
    del bucle en 43b-2): `medir_apariciones` la rechaza."""
    funcion = _aparicion_en_personas(n)
    funcion()
    return funcion


APARICIONES_POR_CONTENEDORAS = {'_nombres_en': _aparicion_en_personas, 'problemas_dato_civil': _aparicion_en_sociedades}


def medir_apariciones(preparar, n):
    """AC238 (enmienda 53): UNA medida de la familia `preparar` a n piezas, para el bloque de `_correr`: construye FUERA
    del reloj el índice (con su `derivado` sin calcular), vacía las cachés y mide la consulta, que calcula el
    `derivado`. Afirma que lo calculó dentro de la medida: si no, no era una medida en frío."""
    funcion = preparar(n)
    vaciar_caches()
    with construyendo() as construido:
        with medida():
            funcion()
    if not construido['derivado']:
        raise AssertionError(f'{preparar.__name__} ({n} piezas) no calculó el derivado dentro de su medida')


def tiempos_de_apariciones(preparar, tamanos=(800, 1600, 3200, 6400), repeticiones=2) -> dict:
    """AC228, AC238 (enmienda 53): {n piezas: mejor tiempo de CPU} de `repeticiones` medidas frías (un proceso hijo cada
    una) de la MISMA entrada. AC335 (enmienda 90): la alarma del hijo (20 s a factor 1) lleva el factor: cubre controles
    de segundos (`quemar`, que crecen con él) y el `5 * L**2` del `derivado`, que en un runner lento pasa de 14 s."""
    return {n: min(_medido(medir_apariciones, (preparar, n), 'process_time', escalada(20)) for _ in range(repeticiones))
            for n in tamanos}


def _clases_auxiliares():
    """Las pruebas de los controles de `ejecutar_el_cuerpo` (AC248): se crean dentro de una función para que la carga de
    pruebas no las recoja, y el hijo las encuentra por nombre en `AUXILIARES`. Su fixture vive en
    `tempfile.gettempdir()`, que es el directorio del padre."""
    def marca(texto):
        with open(Path(tempfile.gettempdir()) / 'marcas.txt', 'a') as fichero:
            fichero.write(texto + '\n')

    class Sana(unittest.TestCase):
        def runTest(self):
            pass

    class FalloEnSetUp(unittest.TestCase):
        def setUp(self):
            self.directorio = tempfile.mkdtemp()
            self.addCleanup(marca, 'limpieza')
            raise OSError('inyectado tras mkdtemp')

        def runTest(self):
            pass

    class LimpiezaQueFalla(unittest.TestCase):
        def setUp(self):
            self.addCleanup(self.fail, 'la limpieza falla')

        def runTest(self):
            pass

    class Omitida(unittest.TestCase):
        @unittest.skip('omitida a propósito')
        def runTest(self):
            pass

    class FalloEsperado(unittest.TestCase):
        @unittest.expectedFailure
        def runTest(self):
            self.fail('esperado')

    class ExitoInesperado(unittest.TestCase):
        @unittest.expectedFailure
        def runTest(self):
            pass

    class Mortal(unittest.TestCase):
        def setUp(self):
            self.directorio = tempfile.mkdtemp()
            self.addCleanup(marca, 'limpieza')

        def runTest(self):
            (Path(self.directorio) / 'resto').write_text('x')
            os.kill(os.getpid(), signal.SIGKILL)
    return {clase.__name__: clase for clase in (Sana, FalloEnSetUp, LimpiezaQueFalla, Omitida, FalloEsperado,
                                                 ExitoInesperado, Mortal)}


AUXILIARES = _clases_auxiliares()


def ejecutar_el_cuerpo(modulo, clase, metodo, directorio):
    """AC244 (enmienda 55), AC248 (enmienda 56): ejecuta `clase.metodo` en el hijo con `unittest` de verdad: la
    instancia corre con `TestSuite.run` sobre un `TestResult` (el orden `setUp`, prueba, `tearDown` y `doCleanups`, y
    las limpiezas registradas aunque falle `setUp`, y las fixtures de clase) y se devuelve lo que `unittest` anotó:
    errores, fallos (también los de limpieza), omisiones y éxitos inesperados. Su fixture se aloja bajo `directorio`,
    que crea y borra el padre: una terminación forzada del hijo tampoco deja temporales."""
    tempfile.tempdir = directorio
    resultado = unittest.TestResult()
    unittest.TestSuite([(AUXILIARES.get(clase) or getattr(sys.modules[modulo], clase))(metodo)]).run(resultado)
    return {'errores': [traza for _, traza in resultado.errors], 'fallos': [traza for _, traza in resultado.failures],
            'omitidas': [motivo for _, motivo in resultado.skipped], 'inesperados': len(resultado.unexpectedSuccesses)}


def ejecutar_cuerpo_en_hijo(modulo, clase, metodo, directorio=None):
    """AC244 (enmienda 55), AC248 (enmienda 56): la prueba `clase.metodo` de `modulo` se ejecuta en un hijo y el padre
    la hace suya: un error o un fallo del hijo (también de su limpieza) o un éxito inesperado es un `AssertionError`;
    una omisión, un `SkipTest`; un hijo que muere o se cuelga, el `AssertionError` de `en_hijo`. El directorio del
    fixture del hijo lo crea el padre y lo borra en su `finally`, también si el hijo murió a mitad."""
    with contextlib.ExitStack() as pila:
        if directorio is None:
            directorio = pila.enter_context(tempfile.TemporaryDirectory())
        resultado = en_hijo(ejecutar_el_cuerpo, modulo, clase, metodo, directorio)
    if resultado['errores'] or resultado['fallos'] or resultado['inesperados']:
        raise AssertionError(f'falló el cuerpo de {clase}.{metodo} en el hijo:\n'
                             + '\n'.join(resultado['errores'] + resultado['fallos'])
                             + (f"\n{resultado['inesperados']} éxito(s) inesperado(s)"
                                if resultado['inesperados'] else ''))
    if resultado['omitidas']:
        raise unittest.SkipTest('; '.join(resultado['omitidas']))


def en_hijo_el_cuerpo(prueba, metodo):
    """AC244 (enmienda 55): la prueba `prueba` ejecuta su método `metodo` (un `cuerpo_…`) en un hijo."""
    ejecutar_cuerpo_en_hijo(type(prueba).__module__, type(prueba).__name__, metodo)


class _Asegura(unittest.TestCase):
    def runTest(self):
        pass


# AC243 (enmienda 55): las afirmaciones de lo que se ejecuta en un hijo (`self.assert…` no viaja: el hijo no tiene la
# prueba).
ASEGURA = _Asegura()


