def _prefijos_al_azar(n, separadores, semilla):
    azar = random.Random(semilla)
    return ''.join(['ab'] + [azar.choice(separadores) + 'ab' for _ in range(n - 1)])


FAMILIAS_DE_PREFIJOS = {
    'cola única': lambda n, q: ('"'.join(['ab'] * n) + ' ' + q, '"'.join(['ab'] * (2 * n)) + ' ' + q),
    'todo coincide': lambda n, q: ('"'.join(['ab'] * n), '"'.join(['ab'] * (2 * n))),
    'separadores al azar': lambda n, q: ('"'.join(['ab'] * n), _prefijos_al_azar(2 * n, ['"', '-', '\u00b7', ' '], 7)),
    'l por i al final': lambda n, q: ('"'.join(['ib'] * n), '"'.join((['ib'] * (n - 1) + ['lb']) * 2)),
    'guiones, cola única': lambda n, q: ('-'.join(['ab'] * n) + ' ' + q, '-'.join(['ab'] * (2 * n)) + ' ' + q),
    'guiones, todo coincide': lambda n, q: ('-'.join(['ab'] * n), '-'.join(['ab'] * (2 * n))),
}


def bloque_de_prefijos_compartidos(familia, base, k):
    del_indice, texto = FAMILIAS_DE_PREFIJOS[familia](base * k, 'qx0')
    vaciar_caches()   # sin cachés: se mide construir, no recordar
