def bloque_de_verificar_un_nombre_largo(etiqueta, clave, piezas, valor=_valor_x):
    """`verificar_snapshot` COMPLETO (no solo la guarda de homónimos) de un civil con un valor de `piezas` piezas sin candidatos."""
    nodos = _nodos_de_nombres_largos([valor(piezas)], clave, etiqueta)
    with tempfile.TemporaryDirectory() as tmp:
        (Path(tmp) / 'nodes.jsonl').write_text(''.join(json.dumps(n) + '\n' for n in nodos))
        (Path(tmp) / 'relationships.jsonl').write_text('')
        data = permitidos()
        vaciar_caches()
        with medida():
            problemas = S.verificar_snapshot(tmp, _IDS_DE_NOMBRES_LARGOS, data)
    ASEGURA.assertEqual(problemas, [])


def bloque_de_la_exencion(n, junta, corto, semilla, por_elemento, extra=None, caracteres=None, sociedad=False):
    propio, ajeno = 'Person:zz-propio', 'Person:zz-ajeno'
    r = random.Random(semilla)
    piezas = [junta.join('ab'), junta.join(['a', '8'])]   # «a-b» y «a-8», con la junta de la familia
    texto = junta.join((random.Random(semilla + i) if por_elemento else r).choice(piezas)
                       for i in range((caracteres // 3) if caracteres else 2 * n))[:caracteres]
    nombre = junta.join(['ab'] * n)
    if extra:   # el propio escrito entero una vez, o el ajeno una vez más
        texto += ' ' + (nombre if extra == 'entero' else corto)
    vaciar_caches()   # sin cachés: se mide construir, no recordar
    with medida():
        if sociedad:
            indice = S.indice_sociedades({'Company:zz-propio': {nombre}, 'Company:zz-ajeno': {corto}})
            return S.problemas_dato_civil(texto, 'contenido', ({}, {}), indice, frozenset({'Company:zz-propio'}))
        civiles = S.indice_civiles([(propio, nombre), (ajeno, corto)], frozenset())
        return S._nombres_en(texto, civiles, frozenset({propio}))


def bloque_de_la_exencion_a_escala(junta, corto, semilla, por_elemento, sociedad, base, k):
    return bloque_de_la_exencion(base * k, junta, corto, semilla, por_elemento, sociedad=sociedad)


def agota_el_presupuesto():
    """El adversario de 1.600 piezas agota el presupuesto de la exención (y no más): (agotado, gastado), en un hijo."""
    llamadas = []

    class Registro(S._Presupuesto):
        def __init__(self):
            super().__init__()
            llamadas.append(self)
    with mock.patch.object(S, '_Presupuesto', Registro):
        bloque_de_la_exencion(1600, '-', 'ab-ab', 17, False)
    return llamadas[0].agotado, llamadas[0].gastado


