# --- AC253 a AC255 (enmienda 58): el proceso de la prueba no lee relojes. UNA guarda que falla cerrada al llamar
# (`_vigilancia.py`, importada en la primera línea de este módulo y del de `apply`) y sus controles. Los cuerpos de hijo
# (`correr_formas`, `la_guarda_sobrevive_a_los_fixtures`) corren en un intérprete limpio del servidor, con `forzar`.
TESTS = Path(_vigilancia.__file__).resolve().parent
# Las funciones de estos dos módulos que leen un reloj SOLO en un hijo (la guarda no actúa allí), junto a las
# `EXENCIONES` de `_vigilancia`: un metatest exige que sean EXACTAMENTE las funciones que mencionan un reloj.
CUERPOS_DE_HIJO = frozenset({('test_seudonimos.py', 'alarmas_anidadas'),
                             ('test_seudonimos.py', 'sigint_en_cada_llamada.<locals>.pasada'),
                             ('test_seudonimos.py', 'de_27_piezas'), ('test_seudonimos.py', 'presupuesto'),
                             ('test_qa_esc_apply.py', 'medir_en_frio'), ('test_qa_esc_apply.py', 'presupuesto')})
IMPORTA_UN_RELOJ = frozenset({'timeit', 'cProfile', 'profile', 'sched'})


def lectura_desde(fichero, codigo='import time\ntime.perf_counter()\n'):
    """AC253 (enmienda 58): ejecuta `codigo` como si estuviese en `fichero` y devuelve el `AssertionError` que lanza la
    guarda, o `None` si el código leyó el reloj sin que nadie lo rechazara."""
    try:
        exec(compile(codigo, str(fichero), 'exec'), {})
    except AssertionError as fallo:
        return fallo


def lectura_desde_un_fichero_de_pruebas(codigo='import time\ntime.perf_counter()\n'):
    return lectura_desde(TESTS / 'e58_sonda.py', codigo)


def menciones_de_reloj(fuente) -> set:
    """AC253, AC254, AC256, AC263 (enmienda 58, 59, 61): las funciones (por nombre cualificado, como las ve la
    guarda en el marco que lee; `<módulo>` fuera de toda función) de `fuente` que mencionan un reloj: su uso
    (`time.<reloj>`, `os.times`, `resource.getrusage`, `signal.getitimer`, también por alias) y CADA importación de
    uno aunque no tenga usos locales (`from time import perf_counter [as x]`, `from os import times`, `from time
    import *`, `import time as t`; un `import time` sin alias no, porque no guarda ningún reloj, ni el alias de
    `os`, `resource` o `signal`, cuyo único reloj se detecta al usarlo) y los imports de `timeit`, `cProfile`,
    `profile` o `sched`. Un alias puede ligarse a varios módulos (`import resource as api` y, en una función,
    `import signal as api`): cada alias guarda el CONJUNTO de los que lo ligan, sin analizar ámbitos, y `api.attr`
    cuenta si `attr` es un reloj de cualquiera de ellos (cuenta de más, nunca de menos). No es un detector de formas
    (lo que cierra el hueco en ejecución es `instalar`): solo vigila que la tabla de exenciones y los módulos que no
    importan la guarda sean los que son."""
    arbol = ast.parse(fuente)
    relojes = {'time': set(_vigilancia.RELOJES), 'os': {'times'}, 'resource': {'getrusage'}, 'signal': {'getitimer'}}
    modulos, nombres, encontradas = {}, {}, set()
    for nodo in ast.walk(arbol):
        if isinstance(nodo, ast.Import):
            for alias in nodo.names:
                if alias.name in relojes:
                    modulos.setdefault(alias.asname or alias.name, set()).add(alias.name)
        elif isinstance(nodo, ast.ImportFrom):
            for alias in nodo.names:
                if alias.name in relojes.get(nodo.module, ()):
                    nombres.setdefault(alias.asname or alias.name, set()).add(f'{nodo.module}.{alias.name}')

    def visita(nodo, qualname, en_funcion):
        for hijo in ast.iter_child_nodes(nodo):
            if isinstance(hijo, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                nuevo = (hijo.name if not qualname else f'{qualname}.<locals>.{hijo.name}' if en_funcion
                         else f'{qualname}.{hijo.name}')
                visita(hijo, nuevo, not isinstance(hijo, ast.ClassDef))
                continue
            funcion = qualname or '<módulo>'
            if isinstance(hijo, ast.Import):
                for alias in hijo.names:
                    if alias.name.split('.')[0] in IMPORTA_UN_RELOJ:
                        encontradas.add((funcion, alias.name))
                    if alias.name == 'time' and alias.asname and alias.asname != alias.name:
                        encontradas.add((funcion, f'{alias.name} as {alias.asname}'))
            elif isinstance(hijo, ast.ImportFrom):
                modulo = hijo.module or ''
                if modulo.split('.')[0] in IMPORTA_UN_RELOJ:
                    encontradas.add((funcion, modulo))
                for alias in hijo.names:
                    if modulo in relojes and (alias.name == '*' or alias.name in relojes[modulo]):
                        encontradas.add((funcion, f'{modulo}.{alias.name}'))
            elif isinstance(hijo, ast.Attribute) and isinstance(hijo.value, ast.Name) and hijo.value.id in modulos:
                encontradas.update((funcion, f'{modulo}.{hijo.attr}') for modulo in modulos[hijo.value.id]
                                   if hijo.attr in relojes[modulo])
            elif isinstance(hijo, ast.Name) and isinstance(hijo.ctx, ast.Load) and hijo.id in nombres:
                encontradas.update((funcion, reloj) for reloj in nombres[hijo.id])
            visita(hijo, qualname, en_funcion)
    visita(arbol, '', False)
    return encontradas


def rutas_relativas(valores) -> list:
    """AC258, AC261, AC264 (enmienda 59, 60, 61): los nombres cualificados de las funciones de `valores` cuyo
    `co_filename` no es absoluto, siguiendo hasta el código real las cadenas `__wrapped__` de CUALQUIER objeto que lo
    tenga (`contextlib.contextmanager`, `functools.wraps`, `functools.lru_cache`, que no son funciones), el `__func__`
    de `staticmethod` y `classmethod` y el `fget`, `fset` y `fdel` de una `property`. Un nombre como
    `<string>` (el `__new__` de un `namedtuple`) no es una ruta: ese código no está en un fichero de
    `pipeline/tests`."""
    relativas, vistos, pendientes = [], set(), list(valores)
    while pendientes:
        valor = pendientes.pop()
        if id(valor) in vistos:
            continue
        vistos.add(id(valor))
        if getattr(valor, '__wrapped__', None) is not None:
            pendientes.append(valor.__wrapped__)
        if isinstance(valor, (staticmethod, classmethod)):
            pendientes.append(valor.__func__)
        elif isinstance(valor, property):
            pendientes.extend(f for f in (valor.fget, valor.fset, valor.fdel) if f is not None)
        elif isinstance(valor, types.FunctionType):
            fichero = valor.__code__.co_filename
            if not (os.path.isabs(fichero) or fichero.startswith('<')):   # `<string>`: `namedtuple`, `exec`
                relativas.append(valor.__qualname__)
    return sorted(relativas)


# AC267, AC270 (enmienda 62, 63): los únicos errores de ENTORNO al importar que la prueba dinámica tolera, por par
# exacto (tipo de excepción, nombre): el CI (`checks.yml`) corre en un checkout limpio sin `openai`, sin `fitz` y sin
# `specs/` (un symlink al vault, ignorado por git). Se tolera ese fallo concreto de ese módulo, y se informa, solo si el
# error es del tipo builtin exacto (no una subclase), su nombre es igual (`ModuleNotFoundError`) o su ruta es
# exactamente `<raíz del repo>/<nombre>` (`FileNotFoundError`), y no viene encadenado; un tipo distinto, otro nombre,
# otra raíz o un módulo fuera de la tabla fallan. Un módulo que lee un reloj ANTES del fallo lanza la guarda y se
# denuncia.
ERRORES_DE_ENTORNO = {'test_llm_client': ('ModuleNotFoundError', 'openai'),
                      'test_puntos_decision': ('ModuleNotFoundError', 'fitz'),
                      'test_qa_esc_pilot_report': ('FileNotFoundError',
                                                   'specs/063-auditoria-escalonada-por-entidad/tools-063/pilot_report.py')}
ResultadoDeImportar = collections.namedtuple('ResultadoDeImportar', 'denunciados tolerados')
def _limpiar(acciones, intentos=3):
    """AC277 (enmienda 66): corre CADA acción de una limpieza en su propio `try`: un fallo, o un `KeyboardInterrupt`, no
    impide las siguientes. Las acciones son idempotentes: si una pasada falla (salvo con un `RuntimeError`, que es una
    denuncia) o un `KeyboardInterrupt` la aborta entre dos acciones, se repite entera hasta `intentos` veces. Devuelve
    los fallos de la primera pasada que falló: quien llama los relanza (`_relanzar`) cuando ya no queda nada por limpiar."""
    fallos = []
    for _ in range(intentos):
        pasada = []
        try:
            for accion in acciones:
                try:
                    accion()
                except BaseException as error:   # se guarda y se relanza al final: nada impide la acción siguiente
                    pasada.append(error)
        except KeyboardInterrupt as error:   # entre dos acciones
            pasada.append(error)
        fallos = fallos or pasada
        if all(isinstance(error, RuntimeError) for error in pasada):
            break
    return fallos


def _relanzar(fallos):
    """AC277 (enmienda 66): relanza el primer fallo de una limpieza, cuando ya se intentó todo lo demás, SIN pisar la
    excepción que ya está en vuelo (la del `try` que se limpia): prevalece ella y el fallo queda como su `__context__`,
    sin ciclo. Salvo un `KeyboardInterrupt` de la propia limpieza: un Ctrl-C pendiente se entrega siempre."""
    if not fallos:
        return
    fallo = next((f for f in fallos if isinstance(f, KeyboardInterrupt)), fallos[0])
    original = sys.exception()
    if original is None or original is fallo or isinstance(fallo, KeyboardInterrupt):
        raise fallo
    nodo = fallo
    while nodo.__context__ is not None and nodo.__context__ is not original:
        nodo = nodo.__context__
    if nodo.__context__ is original:   # el fallo se lanzó mientras la original volaba: sin ciclo
        nodo.__context__ = None
    original.__context__ = fallo


def _consultar_ps(argumentos, plazo_ps=2, intentos=3):
    """AC285 (enmienda 69): UNA consulta a `ps`, con plazo, cuya terminación no se deja a `subprocess.run` (que mata al `ps`
    y espera SIN plazo: un fallo único de ese `kill` dejaba la espera colgada, igual que `with Popen`). `Popen` sin
    context manager y `communicate(timeout=plazo_ps)`; si no vuelve (plazo vencido, interrupción) se termina en pasos
    aislados y repetibles de `_limpiar`: el `kill` (un `ProcessLookupError` o un `PermissionError` solo vale si `poll()`
    dice que el `ps` ya no vive), un `wait` con plazo y el cierre de los tubos, hasta `intentos` pasadas. AC287 (enmienda
    70): los tubos se cierran SIEMPRE, también si `subprocess` ya recogió al hijo (un `SIGINT` en `communicate` lo espera
    y fija `returncode` antes de propagar); solo matar y recoger dependen del estado del proceso. Con la excepción
    original en vuelo, prevalece (el fallo del `kill` queda como su `__context__`); si el `ps` no muere ni se recoge,
    `AssertionError` propia, sin esperar sin plazo. Devuelve `(pid, código, salida, error)`. Se incrusta en la sonda."""
    import subprocess
    ps = subprocess.Popen(['ps', *argumentos], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    try:
        salida, error = ps.communicate(timeout=plazo_ps)
        return ps.pid, ps.returncode, salida, error
    finally:
        matado = []

        def matar():
            if ps.returncode is None:
                try:
                    ps.kill()
                except (ProcessLookupError, PermissionError):
                    if ps.poll() is None:
                        raise
                matado.append(True)

        def esperar():   # solo con un `kill` hecho: si falló, esperar el plazo entero a un `ps` vivo no sirve de nada
            if matado:
                ps.wait(timeout=plazo_ps)
        fallos = _limpiar([matar, esperar, ps.stdout.close, ps.stderr.close], intentos)
        if ps.returncode is None:
            raise AssertionError(f'el ps {ps.pid} no murió ni se recogió en {intentos} intentos de {plazo_ps:g} s')
        _relanzar(fallos)


def _senalar(pid, numero, plazo_ps=2):
    """AC283 (enmienda 68): envía `numero` a `pid`. Un `ProcessLookupError` o un `PermissionError` NO se toma por «ya
    murió» sin comprobarlo (macOS da `EPERM` a un zombi, pero un `EPERM` único sobre un proceso vivo en otra sesión lo
    dejaría congelado): solo se acepta si `ps` dice, con código 0 o 1 y SIN nada en su error estándar, que el pid ya no
    existe o es un zombi (un `ps` que falla también sale con 1). Si sigue vivo, o `ps` no puede decirlo (falla, o no
    vuelve en `plazo_ps`: `_consultar_ps` lo mata y lo recoge), el error sube y la pasada de `_limpiar` que lo recoge se
    repite, acotada por conteo. Se incrusta en la sonda."""
    import os
    try:
        os.kill(pid, numero)
    except (ProcessLookupError, PermissionError):
        _, codigo, salida, error = _consultar_ps(['-o', 'stat=', '-p', str(pid)], plazo_ps)
        estado = salida.split()
        if not (codigo in (0, 1) and not error.strip() and (not estado or estado[0].startswith('Z'))):
            raise


def _matar_descendientes(raiz, congelar_raiz=False, vueltas=20, plazo_ps=2, fallos_seguidos=4):
    """AC271, AC274, AC275, AC277, AC278, AC283 (enmienda 64 a 68): ningún descendiente de `raiz` sobrevive, cambie de
    grupo o de sesión. Se recorre el árbol por `ppid` (`ps -axo pid=,ppid=`) y se CONGELA (`SIGSTOP`) a cada descendiente nuevo
    hasta un punto fijo (una enumeración VÁLIDA sin descendientes nuevos; es válida si todas sus líneas son dos enteros
    y contiene a `raiz`, lo que descarta una tabla vacía). Cada pid se registra ANTES de congelarlo; el `finally` mata a
    todos los registrados por pasos aislados (`_limpiar`). Cada `ps` (`_consultar_ps`) tiene plazo y código de salida comprobado; una
    enumeración fallida se repite hasta `vueltas` o `fallos_seguidos` fallos seguidos (el presupuesto es
    `fallos_seguidos` × `plazo_ps` s, sin hilo ni reloj que pueda fallar al arrancar) y entonces se DENUNCIA
    (`RuntimeError`): nunca se da por limpia. Con `congelar_raiz` se congela también a `raiz` (sin registrarla: su
    suerte es de quien llama). Toda señal pasa por `_senalar`: «ya murió» se comprueba. Se incrusta en la sonda."""
    import signal
    import subprocess
    registrados, seguidos, ultimo = [], 0, None

    def descendientes():
        pid_ps, codigo, tabla, _ = _consultar_ps(['-axo', 'pid=,ppid='], plazo_ps)
        filas = [linea.split() for linea in tabla.splitlines()]
        if codigo or not all(len(f) == 2 and all(c.isdigit() for c in f) for f in filas):
            raise OSError(f'ps terminó con código {codigo} y la tabla {tabla[:200]!r}')
        if raiz not in {int(f[0]) for f in filas}:
            raise OSError(f'la tabla de ps no contiene a {raiz}')
        hijos = {}
        for pid, padre in ((int(f[0]), int(f[1])) for f in filas if int(f[0]) != pid_ps):
            hijos.setdefault(padre, []).append(pid)
        pendientes, vistos = [raiz], set()
        while pendientes:
            for hijo in hijos.get(pendientes.pop(), ()):
                if hijo not in vistos:
                    vistos.add(hijo)
                    pendientes.append(hijo)
        return vistos
    try:
        if congelar_raiz:   # congelado pero NO registrado: matarlo huérfana a sus descendientes; es cosa de quien llama
            _senalar(raiz, signal.SIGSTOP, plazo_ps)
        for _ in range(vueltas):
            if seguidos >= fallos_seguidos:
                break
            try:
                nuevos = descendientes() - set(registrados)
            except (OSError, subprocess.TimeoutExpired) as error:   # no es un punto fijo: se repite
                ultimo, seguidos = error, seguidos + 1
                continue
            seguidos = 0
            if not nuevos:
                return registrados
            registrados.extend(sorted(nuevos))   # TODOS registrados antes de congelar a ninguno
            for pid in nuevos:
                _senalar(pid, signal.SIGSTOP, plazo_ps)
        raise RuntimeError(f'la limpieza no llegó a enumerar los descendientes de {raiz} (último fallo: {ultimo!r})')
    finally:
        _relanzar(_limpiar([lambda pid=pid: _senalar(pid, signal.SIGKILL, plazo_ps) for pid in registrados]))


def _recoger_lider(proceso):
    """AC271, AC272, AC276, AC277, AC280, AC281 (enmienda 64 a 67): la limpieza del padre cuando el líder sigue vivo
    (plazo vencido, excepción, `KeyboardInterrupt`): se decide si se puede diferir `SIGINT` (`pthread_sigmask`), se
    difiere, se barren sus descendientes, y SOLO con el barrido hecho se mata al líder (`killpg` y `kill`) y se le
    recoge con `wait` y plazo, y se restaura la máscara. TODO son acciones aisladas e idempotentes de `_limpiar`, desde
    decidir si hay máscara y avisar de que no la hay: tras el `return` de la salida normal no queda ninguna llamada
    fuera de ellas, así que una interrupción en cualquiera se repite. El `wait` va SIEMPRE tras matar, aunque el `poll`
    de `Popen.kill` ya haya recogido al líder (vuelve al instante): las llamadas de la limpieza no dependen del
    planificador. Si un fallo persistente impidió barrer, al final se mata al líder igualmente: ni un descendiente ni la
    suite quedan colgados. El primer fallo se relanza al final con `_relanzar`: si ya había una excepción en vuelo,
    prevalece ella."""
    if proceso.returncode is not None:   # salida normal: `communicate()` ya recogió al líder
        return
    mascara, avisado, antes, barrido, grupo, forzado = [], [], [], [], [], []

    def tolerante(accion, *args):   # AC283: «ya murió» solo si el líder ya no vive (el `poll` recoge a un zombi)
        try:
            accion(*args)
        except (ProcessLookupError, PermissionError):
            if proceso.poll() is None:
                raise

    def vivo():   # el líder sigue vivo y su grupo ya recibió el SIGKILL (o no hay más remedio)
        return proceso.returncode is None and bool(grupo or forzado)

    def decidir_mascara():   # una vez decidido, no se vuelve a preguntar
        if not mascara:
            mascara.append(os.name == 'posix' and threading.current_thread() is threading.main_thread())

    def avisar():   # una sola vez, aunque `-W error` lo convierta en una excepción y la pasada se repita
        if mascara and not mascara[0] and not avisado:
            avisado.append(True)
            warnings.warn('AC276: no se puede diferir SIGINT durante la limpieza (no POSIX o no es el hilo principal)',
                          stacklevel=4)   # `avisar` <- `_limpiar` <- `_recoger_lider` <- quien limpia

    def con_mascara():
        return bool(mascara and mascara[0])

    def guardar_mascara():
        if con_mascara() and not antes:
            antes.append(signal.pthread_sigmask(signal.SIG_BLOCK, set()))

    def bloquear_sigint():
        if con_mascara() and antes:   # solo con la máscara original ya guardada
            signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT})

    def barrer():
        if not forzado and proceso.poll() is None:
            _matar_descendientes(proceso.pid, congelar_raiz=True)
        barrido.append(True)

    def matar_grupo():   # antes de recoger al líder: si falla, se repite mientras su pgid siga siendo nuestro
        if proceso.returncode is None and bool(barrido or forzado):
            tolerante(os.killpg, proceso.pid, signal.SIGKILL)
            grupo.append(True)

    def matar_lider():
        if vivo():
            tolerante(proceso.kill)

    def esperar():
        for _ in range(3):
            if not (grupo or forzado):   # todavía no se le ha matado: nada que esperar
                return
            try:
                proceso.wait(timeout=1)   # también si el `poll` de `Popen.kill` ya lo recogió: vuelve al instante
                return
            except subprocess.TimeoutExpired:   # no murió: se repite la muerte
                matar_grupo()
                matar_lider()
        if vivo():
            raise RuntimeError(f'el líder de la sonda ({proceso.pid}) sigue vivo tras la limpieza')

    def cerrar_tubos():   # el llamador no usa `with Popen`: su `__exit__` esperaría al líder sin plazo
        for tubo in (proceso.stdout, proceso.stderr):
            if tubo is not None:
                tubo.close()

    def restaurar_mascara():
        if con_mascara() and antes:
            signal.pthread_sigmask(signal.SIG_SETMASK, antes[0])
    acciones = [decidir_mascara, avisar, guardar_mascara, bloquear_sigint, barrer, matar_grupo, matar_lider, esperar,
                cerrar_tubos, restaurar_mascara]
    fallos = _limpiar(acciones)
    if proceso.returncode is None:   # un fallo persistente impidió barrer: al líder se le mata igualmente
        forzado.append(True)
        fallos += _limpiar(acciones)
    _relanzar(fallos)


_MARCA_DE_IMPORTAR, _MARCA_DE_LIMPIEZA = '@@AC265@@', '@@AC275@@'
_IMPORTAR_TODO = """
import builtins, importlib, json, os, signal, sys
EXACTOS = (builtins.ModuleNotFoundError, builtins.FileNotFoundError)
@LIMPIAR@
@RELANZAR@
@PS@
@SENALAR@
@MATAR@
directorio = sys.argv[1]
sys.path.insert(0, directorio)
import _vigilancia   # PRIMERO: instala la guarda; solo después se importa ningún otro módulo
import unittest   # como `python -m unittest` y `discover`: cargado antes que ningún módulo del directorio
nombres = []
for raiz, subdirectorios, ficheros in os.walk(directorio):
    subdirectorios[:] = [d for d in subdirectorios if d != '__pycache__']
    relativa = os.path.relpath(raiz, directorio)
    for fichero in ficheros:
        if fichero.endswith('.py') and not (relativa == '.' and fichero == '_vigilancia.py'):
            partes = [] if relativa == '.' else relativa.split(os.sep)
            if fichero != '__init__.py':
                partes.append(fichero[:-3])
            nombres.append('.'.join(partes) or '__init__')
guarda, otros = {}, {}
for nombre in sorted(nombres):   # un paquete antes que sus submódulos
    try:
        importlib.import_module(nombre)
    except AssertionError as fallo:
        guarda[nombre] = str(fallo)
    except BaseException as fallo:
        otros[nombre] = {'tipo': type(fallo).__name__, 'exacto': any(type(fallo) is t for t in EXACTOS),
                         'name': fallo.name if type(getattr(fallo, 'name', None)) is str else None,
                         'filename': fallo.filename if type(getattr(fallo, 'filename', None)) is str else None,
                         'causa': fallo.__cause__ is not None, 'contexto': fallo.__context__ is not None,
                         'mensaje': str(fallo)[:300]}
print(@MARCA@ + json.dumps({'guarda': guarda, 'otros': otros, 'importados': len(nombres)}), flush=True)
sys.stderr.flush()
fallos = _limpiar([lambda: _matar_descendientes(os.getpid())])   # todo descendiente por ppid, de cualquier grupo
if fallos:   # una enumeración fallida nunca es «árbol limpio»: sin el marcador, el padre lo convierte en un fallo
    print('la limpieza de la sonda falló: ' + repr(fallos[0]), file=sys.stderr, flush=True)
else:
    print(@LIMPIA@, flush=True)
if os.getpgrp() == os.getpid():   # y el grupo propio (`start_new_session`)
    os.killpg(os.getpgrp(), signal.SIGKILL)
""".replace('@LIMPIAR@', inspect.getsource(_limpiar)).replace('@RELANZAR@', inspect.getsource(_relanzar)).replace(
    '@PS@', inspect.getsource(_consultar_ps)).replace('@SENALAR@', inspect.getsource(_senalar)).replace('@MATAR@', inspect.getsource(_matar_descendientes)).replace(
    '@MARCA@', repr(_MARCA_DE_IMPORTAR)).replace('@LIMPIA@', repr(_MARCA_DE_LIMPIEZA))


def leen_un_reloj_al_importar(directorio, plazo=60, entorno=ERRORES_DE_ENTORNO) -> ResultadoDeImportar:
    """AC254, AC265, AC267 a AC273 (enmienda 58, 62, 63, 64): los módulos de `directorio` que leen un reloj AL
    IMPORTARSE, por la forma que sea (asignación, bloque, `getattr`, `importlib`, un atributo privado de la biblioteca
    estándar): un intérprete NUEVO en un grupo de procesos propio (`sys.executable`, el `PYTHONPATH` del CI más la raíz
    del repo, `cwd` la raíz) importa `_vigilancia` de `directorio` primero, que instala la guarda, después `unittest`
    (como el ejecutor real) y después, por su nombre cualificado y un paquete antes que sus submódulos, cada `*.py` de
    `directorio` y de sus subdirectorios (sin `__pycache__`). Devuelve `ResultadoDeImportar(denunciados, tolerados)`:
    `denunciados` es `{módulo: mensaje de la guarda}` de los que lanzan `AssertionError`, y `tolerados`
    `{módulo: 'tipo: nombre'}` de los que no se pudieron importar por un error de ENTORNO de la tabla cerrada `entorno`
    (`ERRORES_DE_ENTORNO`), con el tipo builtin exacto, el nombre o la ruta exactos (igualdad de texto) y sin causa ni
    contexto; gana la primera excepción, así que una lectura antes del fallo se denuncia. Cualquier otro error de
    importación, un intérprete que muere sin resultado o un plazo vencido hacen fallar con su propio mensaje: nada se
    oculta. Procesos: ningún descendiente de la sonda sobrevive (`_matar_descendientes`, por `ppid`: aunque cambie de
    grupo o de sesión). En la salida normal la sonda lo hace sola antes de su `killpg` y `communicate()` ya recogió al
    líder (código -9) cuando vuelve; si el plazo vence, hay una excepción o un `KeyboardInterrupt`, el líder sigue vivo
    y el `finally` congela a sus descendientes, los mata, hace `killpg` y LO RECOGE con `wait()` y plazo (sin `with
    Popen`: su `__exit__` no lo recoge tras un `KeyboardInterrupt` y, en los demás casos, espera sin plazo). La
    excepción original prevalece sobre un fallo de la limpieza, que queda como su `__context__`. No escribe
    fuera de `directorio` ni deja bytecode. Límites declarados: el descendiente que se desvincula por doble `fork` (se
    reparenta a `init`: ocultación deliberada) y que la sonda no reproduce el `sys.argv` ni el `__main__` del ejecutor
    real (corre con `-c`)."""
    directorio = Path(directorio).resolve()
    raiz = TESTS.parents[1]
    variables = {**os.environ, 'PYTHONDONTWRITEBYTECODE': '1',
                 'PYTHONPATH': os.pathsep.join([str(raiz), str(raiz / 'pipeline'), str(directorio)])}
    proceso = subprocess.Popen([sys.executable, '-c', _IMPORTAR_TODO, str(directorio)], cwd=raiz, env=variables,
                               stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, start_new_session=True)
    try:   # sin `with`: su `__exit__` espera al líder SIN plazo (un fallo persistente de la limpieza lo colgaría)
        salida, errores = proceso.communicate(timeout=plazo)
    finally:
        _recoger_lider(proceso)
    marcadas = [linea for linea in salida.splitlines() if linea.startswith(_MARCA_DE_IMPORTAR)]
    limpias = [linea for linea in salida.splitlines() if linea.startswith(_MARCA_DE_LIMPIEZA)]
    if proceso.returncode not in (0, -signal.SIGKILL) or len(marcadas) != 1 or len(limpias) != 1:
        raise RuntimeError(f'importar {directorio} terminó con código {proceso.returncode} sin dar resultado o sin '
                           f'limpiar sus procesos: {errores[-1500:]}')
    visto = json.loads(marcadas[0][len(_MARCA_DE_IMPORTAR):])
    tolerados, fallos = {}, {}
    for modulo, dato in visto['otros'].items():
        esperado = entorno.get(modulo)
        if (esperado is not None and dato['exacto'] and not dato['causa'] and not dato['contexto']
                and dato['tipo'] == esperado[0]
                and ((esperado[0] == 'ModuleNotFoundError' and dato['name'] == esperado[1])
                     or (esperado[0] == 'FileNotFoundError' and dato['filename'] == str(raiz / esperado[1])))):
            tolerados[modulo] = f'{dato["tipo"]}: {esperado[1]}'
        else:
            fallos[modulo] = f'{dato["tipo"]}: {dato["mensaje"]}'
    if fallos:
        raise RuntimeError(f'no se pudo importar (no es la guarda ni un error de entorno de la tabla): {fallos}; la '
                           f'guarda denuncia {sorted(visto["guarda"])}; tolerados {sorted(tolerados)}')
    return ResultadoDeImportar(visto['guarda'], tolerados)


