    barata = m2.VigilanciaDeRelojesTest('test_la_guarda_de_relojes_esta_instalada_y_actua_en_este_proceso')
    resultado = unittest.TextTestRunner(stream=io.StringIO()).run(unittest.TestSuite([barata]))
    extra.update(vistos=builtins.vistos, ok=resultado.wasSuccessful(), corridas=resultado.testsRun)
