def fixtures_efectivos(clases, modulos, limpiezas_de_modulo, originales) -> list:
    """AC305 (enmienda 75), AC310 (enmienda 77): los fixtures EFECTIVOS de `clases` y `modulos`, por reflexión (lo instalado al importar, sea
    cual sea la forma: cuerpo, asignación externa, decorador, `type(...)`, herencia, mixin). Para cada clase: ninguna de su `__mro__` salvo
    `unittest.TestCase` y `object` define `FIXTURES_DE_CLASE` ni tiene un `_class_cleanups` con algo (`TestCase.__init_subclass__` da a cada
    subclase uno vacío); los que resuelve son los ORIGINALES de `unittest.TestCase` (`originales`, la primera parte de
    `instantanea_de_testcase` tomada antes de importar: contra la `TestCase` actual, una base parcheada daría igual en los dos lados); y su
    `_class_cleanups` está vacío. Ningún módulo define `setUpModule`/`tearDownModule`, y la importación no añadió ninguna de las
    `limpiezas_de_modulo`. Devuelve las denuncias, en texto. No ve lo que se instala en tiempo de ejecución (un `addClassCleanup` dentro de
    un método): eso lo cubre la defensa léxica (`fixtures_fuera_de_run`)."""
    denuncias = []
    for clase in clases:
        for propia in clase.__mro__:
            if propia not in (unittest.TestCase, object):
                denuncias.extend(f'{clase.__qualname__}: {propia.__qualname__} define {n}' for n in FIXTURES_DE_CLASE if n in vars(propia))
                if vars(propia).get('_class_cleanups'):
                    denuncias.append(f'{clase.__qualname__}: {propia.__qualname__} tiene _class_cleanups no vacío')
        for n in ('setUpClass', 'tearDownClass', 'addClassCleanup', 'doClassCleanups') if issubclass(clase, unittest.TestCase) else ():
            if getattr(getattr(clase, n), '__func__', None) is not originales[n][1]:
                denuncias.append(f'{clase.__qualname__}: {n} no es el de unittest.TestCase')
        if getattr(clase, '_class_cleanups', None):
            denuncias.append(f'{clase.__qualname__}: _class_cleanups no está vacío')
    for modulo in modulos:
        denuncias.extend(f'{modulo.__name__}: define {n}' for n in ('setUpModule', 'tearDownModule') if hasattr(modulo, n))
    if limpiezas_de_modulo:
        denuncias.append(f'{len(limpiezas_de_modulo)} limpieza(s) de módulo añadidas al importar')
    return denuncias


NOMBRES_DE_FAULTHANDLER = ('faulthandler', 'dump_traceback_later', 'cancel_dump_traceback_later')


def referencias_a(fuente, buscados) -> collections.Counter:
    """AC303 (enmienda 74), AC307 (enmienda 75): cuántas veces `fuente` nombra cada uno de los `buscados`, por nombre y SIN mirar el
    receptor: un `Name`, un `Attribute` (`faulthandler.x`, pero también `_plazo_duro.faulthandler.x` o `otro.dump_traceback_later`), un
    `alias` o el módulo de un `from ... import` (con `as` o sin él), y una cadena literal que sea un nombre con puntos de esos (o los
    contenga) como argumento de cualquier llamada (`getattr(m, '...')`, `import_module('faulthandler')`, `patch('faulthandler.x')`) o
    como índice (`sys.modules['faulthandler']`). El texto de un docstring o de un mensaje no cuenta. Es una comprobación estrecha
    sobre UNA API; un nombre construido en tiempo de ejecución (`'cancel_' + ...`) no se ve."""
    def literal(nodo):   # una cadena literal que es un nombre con puntos: sus componentes
        if isinstance(nodo, ast.Constant) and isinstance(nodo.value, str) and re.fullmatch(r'[A-Za-z_][\w.]*', nodo.value):
            return nodo.value.split('.')
        return []

    nombres = collections.Counter()
    for nodo in ast.walk(ast.parse(fuente)):
        if isinstance(nodo, ast.Name):
            nombres[nodo.id] += 1
        elif isinstance(nodo, ast.Attribute):
            nombres[nodo.attr] += 1
        elif isinstance(nodo, ast.alias):
            nombres.update(nodo.name.split('.') + ([nodo.asname] if nodo.asname else []))
        elif isinstance(nodo, ast.ImportFrom) and nodo.module:
            nombres.update(nodo.module.split('.'))
        elif isinstance(nodo, ast.Call):
            for argumento in [*nodo.args, *(palabra.value for palabra in nodo.keywords)]:
                nombres.update(literal(argumento))
        elif isinstance(nodo, ast.Subscript):
            nombres.update(literal(nodo.slice))
    return collections.Counter({nombre: veces for nombre, veces in nombres.items() if nombre in buscados})


def referencias_en(directorio, buscados) -> dict:
    """AC307 (enmienda 75), AC308 (enmienda 76): `{ruta relativa: referencias_a(su fuente, buscados)}` de TODOS los `*.py` de `directorio` y de sus
    subdirectorios, a cualquier profundidad y sin `__pycache__`. La clave es la ruta relativa, no el nombre: dos `timer.py` de directorios
    distintos no se pisan."""
    rutas = sorted(ruta for ruta in directorio.rglob('*.py') if ruta.is_file() and '__pycache__' not in ruta.relative_to(directorio).parts)
    return {ruta.relative_to(directorio).as_posix(): referencias_a(ruta.read_text(encoding='utf-8'), buscados) for ruta in rutas}


def enlaces_simbolicos(directorio) -> list:
    """AC309 (enmienda 77): las rutas relativas de TODO enlace simbólico bajo `directorio` (a un fichero o a un directorio, válido o roto, a
    cualquier profundidad, incluso uno llamado `__pycache__`), con un recorrido que NO los sigue: `os.walk(followlinks=False)` lista un enlace
    a un directorio en `dirnames` (sin entrar en él) y uno roto en `filenames`, así que se miran las dos listas con `os.path.islink`. Los
    enumeradores de AC308 no entran en un directorio enlazado: un `helpers` enlazado a un directorio externo sacaría código del árbol revisado."""
    enlaces = []
    for raiz, carpetas, ficheros in os.walk(directorio, followlinks=False):
        enlaces.extend(Path(raiz, nombre).relative_to(directorio).as_posix() for nombre in carpetas + ficheros
                       if os.path.islink(os.path.join(raiz, nombre)))
    return sorted(enlaces)


def inventario_de_py(directorio) -> set:
    """AC308 (enmienda 76): las rutas relativas de los `*.py` de `directorio` (sin `__pycache__`) con OTRO enumerador (`os.walk`) que el de
    `referencias_en` (`rglob`): el contraste no hereda un fallo del recorrido que comprueba."""
    rutas = set()
    for raiz, carpetas, ficheros in os.walk(directorio):
        carpetas[:] = [d for d in carpetas if d != '__pycache__']
        rutas.update(Path(raiz, fichero).relative_to(directorio).as_posix() for fichero in ficheros if fichero.endswith('.py'))
    return rutas


def salidas_distintas(mutante, corpus, esperado):
    """AC301 (enmienda 73): los índices de las cinco salidas de `resultados_de_la_guarda` (llamadas sin plazo, `ps`, atributos,
    importaciones, módulos sueltos) en los que el espacio de nombres `mutante` difiere de lo `esperado` en alguna fuente."""
    return {k for c, e in zip(corpus, esperado) for k, (a, b) in enumerate(zip(resultados_de_la_guarda(mutante, c), e)) if a != b}


def corpus_de_llamadas():
    """AC298 (enmienda 72): un corpus GENERADO de fuentes, el producto de cada API de la tabla por las formas de sus argumentos
    (posicional, keyword, `*args`, `**kw`, nombre, `None`, negativo, signos apilados, `False`/`True`, literales sin evaluar) y por
    sus envoltorios (receptor instancia, texto, `os.path` o clase; dentro de un `partial` o de dos; guardado en un nombre y
    llamado; llamado por una llamada), más los lanzadores de procesos por las formas de su orden (`ps`, otra orden, lista, cadena,
    `args=`, posiciones, dentro de un `partial`). Sirve para demostrar que dos guardas dan el mismo resultado."""
    cabecera = 'def f(a, x, kw, p, proceso, evento, hilo, cerrojo):\n'
    fuentes = []

    def anadir(sentencia, previo=''):
        fuentes.append(cabecera + ''.join(f'    {linea}\n' for linea in (previo + sentencia).split('\n') if linea))
    formas = ('', 'x', '0', '1', '-1', '+-1', '--1', 'None', 'False', 'True', "'s'", '1.5', '2 * 3', 'x + 1', 'x.y', '*a', 'x, *a',
              '*a, x', '*a, False', 'False, *a', 'x, 1', 'x, -1', 'x, None', 'x, x', '1, 1', 'None, 1', 'timeout=1', 'timeout=0',
              'timeout=-1', 'timeout=None', 'timeout=x', 'timeout=True', '**kw', 'x, **kw', 'timeout=1, **kw', 'blocking=False',
              'blocking=True, timeout=1', 'False, timeout=1', 'x, timeout=1', 'x, x, x, 1', '[x], [], [], 1', '[x], [], [], None',
              '[x], [], [], timeout=1', '[x], [], []', "['ps']", "['git']", 'x, 5', 'x, os.WNOHANG', 'x, os.WNOHANG | 0',
              'x, os.WNOHANG & 0', 'x, 0', "['ps'], x", "['git'], ['ps']")
    metodos = ('wait', 'join', 'result', 'acquire', 'communicate', 'readline', 'readlines', 'recv', 'accept')
    receptores = ('proceso', 'evento()', "' '", 'subprocess.Popen')
    funciones = ('subprocess.run', 'subprocess.check_output', 'subprocess.check_call', 'subprocess.call', 'select.select',
                 'os.waitpid', 'os.read', 'os.wait')
    for forma in formas:
        for metodo in metodos:
            for receptor in receptores:
                anadir(f'{receptor}.{metodo}({forma})')
            anadir(f'accion = functools.partial(proceso.{metodo}, {forma})' if forma else f'accion = functools.partial(proceso.{metodo})')
        for funcion in funciones:
            anadir(f'{funcion}({forma})')
            anadir(f'accion = functools.partial({funcion}, {forma})' if forma else f'accion = functools.partial({funcion})')
        anadir(f'functools.partial(evento.wait, timeout=1)({forma})')
        anadir(f'functools.partial(functools.partial(evento.wait, timeout=1), {forma})()' if forma else 'functools.partial(functools.partial(evento.wait))()')
        anadir(f'accion = functools.partial(invocar, {forma})\naccion()' if forma else 'accion = functools.partial(invocar)\naccion()')
        anadir(f'accion = functools.partial(proceso.wait, {forma})\naccion()' if forma else 'accion = functools.partial(proceso.wait)\naccion()')
        anadir(f'invocar({forma})({forma})')
    for previo in ('x = None\n', 'x = -1\n', 'x = 5\n', 'x = +-1\n', 'x = True\n', 'x = 1 if a else None\n', 'x: float = None\n', 'x, y = None, 1\n',
                   'y = None\nx = y\n', 'for x in (None,):\n    pass\n', '(x := None)\n', 'x += 1\n', 'class Espia:\n    pass\n',
                   "p = subprocess.Popen(['x'])\n", "p = subprocess.Popen(['x'])\nq = p\n", "p = subprocess.Popen(['x'])\nq: object = p\n"):
        for sentencia in ('evento.wait(x)', 'cerrojo.acquire(timeout=x)', 'cerrojo.acquire(x, x)', 'Espia.wait(x)', 'with p:\n    pass',
                          'pila.enter_context(p)', 'pila.push(p, 1)', 'invocar(p)', 'p.wait(x)', 'with q:\n    pass', 'r = p',
                          'x = p is None', 'cerrojo.acquire(*a, False)', 'cerrojo.acquire(False, *a)', 'return p'):
            anadir(sentencia, previo)
    for modulo in ('subprocess', 'os', 'select', 'threading', 'signal', 'time', 'functools', 'contextlib', 'multiprocessing'):
        for sentencia in (f'import {modulo} as x', f'import {modulo}.sub', f'import {modulo}', f'from {modulo} import y',
                          f'from {modulo}.sub import y', f'from .{modulo} import y', f'x = {modulo}', f'f({modulo})', f'x = [{modulo}]',
                          f'{modulo} = 1', f'x = {modulo}.atributo', f'x = {modulo}.atributo.sub', f'x = y.{modulo}',
                          f"x = getattr({modulo}, 'atributo')"):
            anadir(sentencia)
    for sentencia in ('subprocess.run(x, shell=True)', 'subprocess.run(x, shell=False)', 'subprocess.run(x, shell=y)', 'f(shell=1)',
                      'import queue', 'import concurrent.futures', 'import asyncio', 'from . import a', 'from .b import c'):
        anadir(sentencia)
    lanzadores = ('subprocess.run', 'subprocess.check_output', 'subprocess.check_call', 'subprocess.call', 'subprocess.Popen')
    ordenes = ("['ps']", "['ps', '-x']", "['/bin/ps']", "['git']", "('ps',)", "'ps -ax'", "'git status'", '[]', '[x]', "[x, 'ps']", '[1]',
               '5', 'x', "['ps', *a]")
    for lanzador in lanzadores:
        for orden in ordenes:
            anadir(f'{lanzador}({orden})')
            anadir(f'{lanzador}(args={orden})')
            anadir(f'{lanzador}({orden}, timeout=1)')
            anadir(f"{lanzador}(['git'], {orden})")
            anadir(f"{lanzador}({orden}, ['git'])")
            anadir(f"{lanzador}(['git'], args={orden})")
            anadir(f'{lanzador}(check={orden})')
            anadir(f'accion = functools.partial({lanzador}, {orden})')
            anadir(f"accion = functools.partial({lanzador}, ['git'], {orden})")
            anadir(f"accion = functools.partial({lanzador}, {orden}, ['git'])")
            anadir(f'accion = functools.partial({lanzador}, args={orden})')
            anadir(f'accion = functools.partial(invocar, {lanzador}, {orden})')
            anadir(f'accion = functools.partial(functools.partial({lanzador}, {orden}))')
    return list(dict.fromkeys(fuentes))


