def huella_del_barrido(ver):
    """AC293 (enmienda 71): lo que tiene que repetirse igual en cada vuelta: los números `(generados, muertos, descartados,
    sobreviven)`, lo descartado por tipo de excepción y una huella de la clasificación entera `(función, descripción,
    veredicto)`. Un mutante que pasa de muerto a descartado entre dos vueltas cambia la huella."""
    veredicto = {**{clave: 'muerto' for clave in ver['muertos']}, **{clave: 'sobrevive' for clave in ver['sobreviven']},
                 **{clave[:2]: f'descartado {clave[2]}' for clave in ver['descartados']},
                 **{clave: 'vencido' for clave in ver['vencidos']}}
    huella = hashlib.sha256('\n'.join(f'{f}|{d}|{v}' for (f, d), v in sorted(veredicto.items())).encode('utf-8')).hexdigest()[:16]
    return ((len(ver['generados']), len(ver['muertos']), len(ver['descartados']), len(ver['sobreviven'])),
            collections.Counter(clave[2] for clave in ver['descartados']), huella)


# Los mutantes que NO cambian lo que la guarda decide, con la razón. Cerrada en los dos sentidos: un superviviente que no
# está aquí falla el barrido, y una entrada que ya no se genera o que ya no sobrevive también.
EQUIVALENTES = {
    ('PLAZO_DE', "constante None por 0 en la entrada `'os.waitpid'`"):
        'la clave de `os.waitpid` no se consulta: su bandera tiene su propia rama en `llamadas_sin_plazo`',
    ('PLAZO_DE', "constante None por 0 en la entrada `'select.select'`"):
        '`select.select` no admite keywords: la clave solo se compara con `palabra.arg`, que nunca vale 0 (el `arg` de un `**kw`'
        ' es `None` y `None == 0` es falso, igual que con `clave is None`)',
    ('ps_fuera_del_ayudante', "constante 1 por 0 en `posicionales, nombre = (nodo.args[1:2], f'functools.partial({ast.un...`"):
        '`args[0:2]` de un `partial` añade el lanzador (un `Attribute`), que no es una lista ni una cadena: no puede ser un `ps`'}


def _forma(texto):
    return textwrap.dedent(texto).replace('@MODULO@', __name__)


def _prueba(cuerpo, cabecera='import time, unittest\n', antes='', decorador=''):
    """Un módulo de pruebas sintético: `cabecera`, una `TestCase` con los métodos `antes` y `test_x` (con `cuerpo`)."""
    return (_forma(cabecera) + 'class T(unittest.TestCase):\n' + textwrap.indent(textwrap.dedent(antes), '    ')
            + textwrap.indent(decorador, '    ') + '    def test_x(self):\n'
            + textwrap.indent(textwrap.dedent(cuerpo), ' ' * 8))


def _formas_de_la_guarda():
    """AC253 (enmienda 58): las formas de leer un reloj en el proceso de la prueba que las pasadas 46ª a 48ª
    reprodujeron (y las directas) y las que NO deben fallar, como módulos completos: nombre -> (fuente, módulos
    auxiliares {nombre: (fuente, fichero)}, fichero de la fuente, rechazada). `fichero` es el que el código dice tener
    (la guarda mira al llamador por su fichero, resuelto): casi todas, uno de `pipeline/tests`. El hijo importa los
    módulos con la guarda ya instalada (el orden real: los dos módulos de pruebas la instalan en su primera línea) y
    corre sus pruebas con `unittest`."""
    def ayudante(texto, fichero):
        return (_forma(texto), fichero)
    t = _prueba
    rechazadas = {
        'alias de importación': t('cpu()', 'import unittest\nfrom time import process_time as cpu\n'),
        'getattr': t('getattr(time, "process_time")()'),
        'reloj pasado como argumento': t('ayuda(time.process_time)', 'import time, unittest\n'
                                         'def ayuda(reloj):\n    return reloj()\n'),
        'lambda invocada': t('(lambda: time.perf_counter())()'),
        'import perezoso': t('import time as t\nt.process_time()', 'import unittest\n'),
        'decorador': t('pass', 'import time, unittest\ndef cronometrado(f):\n    def g(*a):\n'
                       '        time.perf_counter()\n        return f(*a)\n    return g\n',
                       decorador='@cronometrado\n'),
        'reloj en una asignación de módulo': t('CLOCK()', 'import time, unittest\nCLOCK = time.perf_counter\n'),
        'asignación transitiva de dos saltos': t('B()', 'import time, unittest\nA = time.perf_counter\nB = A\n'),
        'reloj en un atributo de clase': t('C.clk()', 'import time, unittest\nclass C:\n    clk = time.perf_counter\n'),
        'reloj en un valor por omisión': t('medir()', 'import time, unittest\n'
                                           'def medir(c=time.perf_counter):\n    return c()\n'),
        'reloj en un cierre': t('MEDIR()', 'import time, unittest\ndef fabrica():\n    c = time.perf_counter\n'
                                '    return lambda: c()\nMEDIR = fabrica()\n'),
        'reloj en un contenedor': t('CLOCKS["a"]()', 'import time, unittest\nCLOCKS = {"a": time.perf_counter}\n'),
        'functools.partial de un reloj': t('CLOCK()', 'import functools, time, unittest\n'
                                           'CLOCK = functools.partial(time.perf_counter)\n'),
        'clase sin decorar': t('time.process_time()'),
        'reloj privado del soporte llamado': t('_ahora()', 'import unittest\nfrom @MODULO@ import _ahora\n'),
        'os.times': t('os.times().user', 'import os, unittest\n'),
        'resource.getrusage': t('resource.getrusage(resource.RUSAGE_SELF)', 'import resource, unittest\n'),
        'signal.getitimer': t('signal.getitimer(signal.ITIMER_REAL)', 'import signal, unittest\n'),
        'from os import times': t('t().user', 'import unittest\nfrom os import times as t\n'),
        'import resource as r': t('r.getrusage(r.RUSAGE_SELF)', 'import resource as r, unittest\n'),
        'time.time': t('time.time()'),
        'time.time_ns': t('time.time_ns()'),
        'una función homónima de una exenta, en otro fichero': t(
            'quemar()', 'import time, unittest\ndef quemar():\n    return time.process_time()\n'),
        'fixture de módulo': t('pass', 'import time, unittest\ndef setUpModule():\n    time.perf_counter()\n'),
        'fixture de módulo (cierre)': t('pass', 'import time, unittest\n'
                                        'def tearDownModule():\n    time.perf_counter()\n'),
        'fixture de clase': t('pass', antes='@classmethod\ndef setUpClass(cls):\n    time.perf_counter()\n\n'),
        'fixture de clase (cierre)': t('pass', antes='@classmethod\ndef tearDownClass(cls):\n'
                                       '    time.perf_counter()\n\n'),
        # los seis de la 48ª pasada, con ayudantes de pipeline/tests importados DESPUÉS de instalar la guarda
        'método enlazado': t('now()', 'import unittest\nfrom e58_h_metodo import now\n'),
        'instancia con __slots__': t('E58_CLOCK.read()', 'import unittest\nfrom e58_h_slots import E58_CLOCK\n'),
        'función con lru_cache': t('medir(1)', 'import unittest\nfrom e58_h_lru import medir\n'),
        'addCleanup con time_ns': t('self.addCleanup(medir_time_ns)',
                                    'import unittest\nfrom e58_h_cb import medir_time_ns\n'),
        'addCleanup con time': t('self.addCleanup(medir_time)', 'import unittest\nfrom e58_h_cb import medir_time\n'),
        'addClassCleanup': t('self.addClassCleanup(medir_perf)', 'import unittest\nfrom e58_h_cb import medir_perf\n'),
        'addModuleCleanup (tras tearDownModule)': t('unittest.addModuleCleanup(medir_perf)',
                                                    'import unittest\nfrom e58_h_cb import medir_perf\n'),
        'ayudante de tests con time_ns': t('duracion()', 'import unittest\nfrom e58_h_time import duracion\n'),
    }
    for nombre in _vigilancia.RELOJES:   # uno por reloj del conjunto reflejado: llamado y guardado con otro nombre
        rechazadas[f'time.{nombre}'] = t(f'time.{nombre}()')
        rechazadas[f'from time import {nombre}'] = t('c()', f'import unittest\nfrom time import {nombre} as c\n')
    auxiliares = {
        'e58_h_metodo': ayudante('''
            import time
            class Reloj:
                def __init__(self):
                    self.clock = time.perf_counter
                def now(self):
                    return self.clock()
            now = Reloj().now
            ''', 'e58_h_metodo.py'),
        'e58_h_slots': ayudante('''
            import time
            class Lector:
                __slots__ = ('read',)
                def __init__(self):
                    self.read = time.perf_counter
            E58_CLOCK = Lector()
            ''', 'e58_h_slots.py'),
        'e58_h_lru': ayudante('''
            import functools
            from time import perf_counter as clock
            @functools.lru_cache(maxsize=None)
            def medir(n):
                return clock()
            ''', 'e58_h_lru.py'),
        'e58_h_cb': ayudante('''
            import time
            def medir_time():
                return time.time()
            def medir_time_ns():
                return time.time_ns()
            def medir_perf():
                return time.perf_counter()
            ''', 'e58_h_cb.py'),
        'e58_h_time': ayudante('''
            import time
            def duracion():
                inicio = time.time_ns()
                return time.time_ns() - inicio
            ''', 'e58_h_time.py'),
    }
    formas = {nombre: (fuente, auxiliares, 'e58_prueba.py', True) for nombre, fuente in rechazadas.items()}
    formas['una ruta con «..» que vuelve a pipeline/tests'] = (t('time.process_time()'), {}, 'sub/../e58_prueba.py',
                                                              True)
    # el nombre de una exenta no basta: el guardián compara el nombre CUALIFICADO (un método homónimo no lo es)
    formas['un método homónimo de una exenta (quemar), en test_seudonimos.py'] = (t(
        'X().quemar()', 'import time, unittest\nclass X:\n    def quemar(self):\n        return time.process_time()\n'),
        {}, 'test_seudonimos.py', True)
    formas['un método homónimo de una supervisora (en_hijo) que llama a _ahora'] = (t(
        'X().en_hijo()', 'import unittest\nfrom @MODULO@ import _ahora\nclass X:\n    def en_hijo(self):\n'
        '        return _ahora()\n'), {}, 'test_seudonimos.py', True)
    # lo que NO debe fallar: un llamador que no es de pipeline/tests (src, la biblioteca estándar, structlog, yaml, un
    # fichero homónimo de fuera) y lo exento
    leer = ('import os, resource, time\n'
            'def leer():\n'
            '    return (time.time(), time.time_ns(), time.perf_counter(), time.monotonic(), time.process_time(),\n'
            '            os.times().user, resource.getrusage(resource.RUSAGE_SELF).ru_utime)\n')
    usa = t('leer()', 'import unittest\nfrom e58_ajeno import leer\n')
    for nombre, fichero in (('src', REAL_REPO / 'pipeline' / 'src' / 'e58_ajeno.py'),
                            ('la biblioteca estándar', Path(unittest.__file__).with_name('e58_ajeno.py')),
                            ('structlog', Path(structlog.__file__).with_name('e58_ajeno.py')),
                            ('yaml', Path(yaml.__file__).with_name('e58_ajeno.py')),
                            ('un fichero homónimo de uno de pipeline/tests, fuera de él',
                             REAL_REPO / 'pipeline' / 'e58_fuera' / 'test_seudonimos.py'),
                            ('una ruta con «..» que sale de pipeline/tests', TESTS / '..' / 'src' / 'e58_ajeno.py')):
        formas[f'llamador: {nombre}'] = (usa, {'e58_ajeno': (leer, str(fichero))}, 'e58_prueba.py', False)
    formas['lo exento: quemar y una alarma'] = (t('quemar(0.001)\nwith alarma(1):\n    pass\ntime.sleep(0)',
                                                  'import time, unittest\nfrom @MODULO@ import alarma, quemar\n'), {},
                                                'e58_prueba.py', False)
    return formas


def correr_formas(formas) -> dict:
    """AC253 (enmienda 58), un cuerpo de hijo (intérprete limpio, la guarda heredada del servidor): primero, SIN forzar,
    un fichero de `pipeline/tests` lee el reloj y nadie lo rechaza (los hijos miden con relojes reales); después
    `forzar` y, para cada forma, importa sus módulos con la guarda ya instalada, corre sus pruebas con `unittest` y
    devuelve {'trazas': errores y fallos}."""
    sin_forzar = lectura_desde_un_fichero_de_pruebas()
    _vigilancia.instalar(forzar=True)
    resultados = {'<sin forzar>': {'trazas': str(sin_forzar or '')}}
    for forma, (fuente, auxiliares, fichero, _) in formas.items():
        modulos = []
        try:
            for nombre, (texto, ruta) in {**auxiliares, 'e58_prueba': (fuente, fichero)}.items():
                ruta = Path(ruta) if Path(ruta).is_absolute() else TESTS / ruta
                modulo = types.ModuleType(nombre)
                sys.modules[nombre] = modulo
                modulos.append(modulo)
                exec(compile(texto, str(ruta), 'exec'), modulo.__dict__)
            resultado = unittest.TestResult()
            unittest.defaultTestLoader.loadTestsFromModule(modulos[-1]).run(resultado)
            resultados[forma] = {'trazas': '\n'.join(traza for _, traza in resultado.errors + resultado.failures)}
        finally:
            for modulo in modulos:
                sys.modules.pop(modulo.__name__, None)
    return resultados


def la_guarda_sobrevive_a_los_fixtures() -> dict:
    """AC253 (enmienda 58), un cuerpo de hijo: un `setUpModule` que falla (`OSError`) y uno interrumpido por un `SIGINT`
    real no dejan nada que liberar: la guarda sigue instalada, no hay contador, un fichero de `pipeline/tests` sigue sin
    poder leer un reloj y `src` sí. Devuelve lo que se vio tras cada uno."""
    _vigilancia.instalar(forzar=True)
    signal.signal(signal.SIGINT, signal.default_int_handler)
    visto = {}
    for caso in ('OSError', 'SIGINT'):
        modulo = types.ModuleType(f'e58_fixture_{caso}')
        sys.modules[modulo.__name__] = modulo
        exec(compile(textwrap.dedent(f"""
            import os, signal, unittest
            def setUpModule():
                if {caso!r} == 'OSError':
                    raise OSError('inyectado')
                os.kill(os.getpid(), signal.SIGINT)
                sum(range(10))
            class T(unittest.TestCase):
                def test_x(self):
                    pass
            """), str(TESTS / 'e58_fixture.py'), 'exec'), modulo.__dict__)
        interrumpido = False
        resultado = unittest.TestResult()
        try:
            unittest.defaultTestLoader.loadTestsFromModule(modulo).run(resultado)
        except KeyboardInterrupt:
            interrumpido = True
        del sys.modules[modulo.__name__]
        visto[caso] = {'fallo_el_fixture': bool(resultado.errors) or interrumpido, 'instalada': _vigilancia.instalada(),
                       'sin_contador': not any(hasattr(getattr(m, n), '_niveles') for m, n in _vigilancia.OBJETIVOS),
                       'rechaza_a_pruebas': isinstance(lectura_desde_un_fichero_de_pruebas(), AssertionError),
                       'deja_pasar_a_src': lectura_desde(REAL_REPO / 'pipeline' / 'src' / 'e58.py') is None}
    return visto


def sigint_en_cada_llamada() -> dict:
    """AC252 (enmienda 57), un cuerpo de hijo: un `SIGINT` REAL en cada punto donde CPython atiende una señal dentro de
    `_con_temporizador` y de lo que llama (al volver de una llamada de C y al entrar en una función de Python: la
    instalación, la restauración, `signal.signal`, `_ahora`), con una alarma previa de 5 s y un manejador previo. Tras
    cada una, el manejador y lo que quedaba de la alarma tienen que ser los de antes. Devuelve
    {'llamadas': n, 'rotas': [(k, qué)], 'sin_interrumpir': [k]}."""
    signal.signal(signal.SIGINT, signal.default_int_handler)

    def previo(*_):
        pass

    def pasada(k):
        signal.signal(signal.SIGALRM, previo)
        signal.setitimer(signal.ITIMER_REAL, 5)
        cuenta = [0]

        def perfil(marco, evento, _):
            # donde CPython atiende una señal: al volver de una llamada de C y al entrar en una función de Python,
            # también dentro de `signal.signal` y de `_ahora`, que `_con_temporizador` llama
            if evento in ('c_return', 'call'):
                while marco is not None and marco.f_code.co_name != '_con_temporizador':
                    marco = marco.f_back
                if marco is not None:
                    cuenta[0] += 1
                    if cuenta[0] == k:
                        os.kill(os.getpid(), signal.SIGINT)
        interrumpida = False
        sys.setprofile(perfil)
        try:
            with _con_temporizador(lambda *_: None, segundos=1.0):
                pass
        except KeyboardInterrupt:
            interrumpida = True
        finally:
            sys.setprofile(None)
        manejador, (restante, intervalo) = signal.getsignal(signal.SIGALRM), signal.getitimer(signal.ITIMER_REAL)
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, signal.SIG_DFL)
        estado = None
        if manejador is not previo:
            estado = 'manejador sin restaurar'
        elif not 4.0 < restante <= 5.0 or intervalo:
            estado = f'alarma exterior {restante:.2f} s, intervalo {intervalo}'
        return cuenta[0], interrumpida, estado
    pasada(0)   # calienta la caché de rutas de la guarda: los puntos se cuentan como en las pasadas siguientes
    llamadas = pasada(0)[0]
    rotas, sin_interrumpir = [], []
    for k in range(1, llamadas + 2):
        _, interrumpida, estado = pasada(k)
        if estado:
            rotas.append((k, estado))
        if not interrumpida and k <= llamadas:
            sin_interrumpir.append(k)
    return {'llamadas': llamadas, 'rotas': rotas, 'sin_interrumpir': sin_interrumpir}


def alarmas_anidadas() -> dict:
    """AC252 (enmienda 57), un cuerpo de hijo: una `alarma` anidada deja la alarma exterior y el manejador como estaban
    (antes la desarmaba), y si la exterior vence antes que la interior, corta igual. Devuelve lo que se vio."""
    signal.signal(signal.SIGINT, signal.default_int_handler)
    with alarma(60):
        with alarma(5):
            dentro = signal.getitimer(signal.ITIMER_REAL)[0]
        fuera = signal.getitimer(signal.ITIMER_REAL)[0]
    desarmada = signal.getitimer(signal.ITIMER_REAL)[0]
    corto, inicio = None, time.monotonic()
    try:
        with alarma(0.3):
            with alarma(30):
                select.select([], [], [], 5)
    except TimeoutError as fallo:
        corto = str(fallo)
    return {'dentro': dentro, 'fuera': fuera, 'desarmada': desarmada, 'corto': corto,
            'tardo': time.monotonic() - inicio}


# AC299, AC302 (enmiendas 73 y 74): PLAZO DURO DE PROCESO. Cada test de las dos clases de guarda (`GuardaDeRelojesTest` aquí y
# `VigilanciaDeRelojesTest` en `test_qa_esc_apply.py`) corre bajo `faulthandler.dump_traceback_later(T, exit=True, file=sys.stderr)`:
# si un test se cuelga, por la forma que sea (la guarda estática de AC284 a AC298 no las ve todas, y no tiene que verlas), vuelca la
# traza de todos los hilos y termina el proceso con un código distinto de 0. El plazo lo arma y lo cancela UN solo gestor, `run` del mixin
# `_plazo_duro.PlazoDuro` (así cubre `setUp`, el cuerpo, `tearDown` y todos los cleanups, y se cancela aunque `setUp` falle o salte).
# `T` = 1500 s por test: al menos 5 veces el test más lento medido CON la carga de 4 procesos (el barrido generado de AC293, de 110 a
# 160 s en un Mac; `MAS_LENTO_MEDIDO` es esa cota declarada, T/5 = 300 s, que deja holgura a un runner de CI más lento); ningún test puede
# pasar de la mitad de `T` (la estabilidad lo mide). No excede la hora del job (`timeout-minutes: 60`).
# AC305 a AC307 (enmienda 75): el plazo no cubre los fixtures de clase ni de módulo (`TestSuite` los ejecuta fuera de `run`), así que no puede
# haber ninguno en las clases protegidas ni en el mixin: lo comprueba la REFLEXIÓN (`fixtures_efectivos`), no el texto; que `run` entregue el
# resultado al ejecutor lo comprueba `PropagacionDelPlazoDuroTest` (sin el mixin, a propósito); y `faulthandler` se nombra solo en el gestor.
MAS_LENTO_MEDIDO = 300.0


class GuardaDeRelojesTest(_plazo_duro.PlazoDuro, unittest.TestCase):
    """AC253 a AC255 (enmienda 58): la guarda de relojes de `_vigilancia.py` y su tabla de exenciones. Los controles de
    las formas corren en un hijo (intérprete limpio) con `forzar`; los de importación, en intérpretes nuevos; el resto,
    en el proceso de las pruebas, que es donde la guarda actúa. AC299, AC302 (enmiendas 73, 74): cada test corre bajo el plazo
    duro de proceso, que arma `run` del mixin (primero en las bases) y no se sobrescribe."""

    def test_la_guarda_rechaza_cada_forma_y_deja_pasar_a_los_legitimos(self):
        """AC253.6 (a), (b), (c), (d): cada forma de `_formas_de_la_guarda` falla con el `AssertionError` de la guarda.
        Los seis hallazgos de la 48ª (un método enlazado, una instancia con `__slots__`, una función con `lru_cache`,
        `addCleanup` con `time_ns`, `addModuleCleanup` tras `tearDownModule`, un ayudante de `tests` con `time_ns`), las
        de la 46ª y 47ª (alias, `getattr`, lambda, import perezoso, decorador, asignación de módulo y transitiva,
        atributo de clase, valor por omisión, cierre, contenedor, `partial`, `_ahora()`, clase sin decorar, fixtures de
        clase y de módulo, `os.times`, `resource.getrusage`, `signal.getitimer`, `time.time`, `time.time_ns`), una
        función homónima de una exenta en otro fichero, una ruta con «..» que vuelve a `pipeline/tests` y un reloj por
        cada elemento del conjunto reflejado. NO fallan los llamadores que no son de `pipeline/tests` (`src`, la
        biblioteca estándar, `structlog`, `yaml`, un fichero homónimo de fuera, una ruta con «..» que sale) ni lo exento
        (`quemar`, una `alarma`); y en un hijo sin `forzar` una prueba lee el reloj (los hijos miden)."""
        formas = _formas_de_la_guarda()
        resultados = en_hijo(correr_formas, formas)
        self.assertEqual(resultados.pop('<sin forzar>')['trazas'], '')
        for forma, (_, _, _, rechazada) in formas.items():
            with self.subTest(forma=forma, rechazada=rechazada):
                trazas = resultados[forma]['trazas']
                if rechazada:
                    self.assertIn('leído desde', trazas)
                else:
                    self.assertEqual(trazas, '')

    def test_la_guarda_actua_en_el_proceso_de_la_prueba(self):
        """AC253 (enmienda 58): en ESTE proceso (el de las pruebas, sin `forzar`) un fichero de `pipeline/tests` no lee
        ningún reloj, `src` sí, y lo exento funciona: `quemar` y una `alarma` (que lee `signal.getitimer`)."""
        self.assertTrue(_vigilancia.instalada())
        _vigilancia.instalar()   # idempotente: ni duplicada ni más envuelta
        self.assertTrue(all(not hasattr(getattr(m, n).__wrapped__, '_vigilado') for m, n in _vigilancia.OBJETIVOS))
        for lectura in ('time.perf_counter()', 'time.time()', 'time.time_ns()', 'os.times()',
                        'resource.getrusage(resource.RUSAGE_SELF)', 'signal.getitimer(signal.ITIMER_REAL)'):
            with self.subTest(lectura=lectura):
                codigo = f'import os, resource, signal, time\n{lectura}\n'
                self.assertIsInstance(lectura_desde_un_fichero_de_pruebas(codigo), AssertionError)
                self.assertIsNone(lectura_desde(REAL_REPO / 'pipeline' / 'src' / 'e58_sonda.py', codigo))
        self.assertIsInstance(lectura_desde_un_fichero_de_pruebas(f'from {__name__} import _ahora\n_ahora()\n'),
                              AssertionError)
        quemar(0.001)
        with alarma(5):
            pass

