    def test_la_guarda_se_instala_antes_que_nada_y_no_se_suelta(self):
        """AC254, AC257.2 (enmienda 58, 59): por el camino REAL de importación (intérpretes nuevos, con `pipeline` y
        `pipeline/tests` en el `PYTHONPATH` como el CI), tras importar los dos módulos de pruebas en cualquiera de los
        dos órdenes, o solo el de `apply` (que importa este), todos los relojes son la envoltura, UNA vez; antes de
        importarlos, no. Y tras correr una prueba real con `unittest`, la guarda sigue ahí (nada la suelta al acabar el
        módulo). La sonda conserva el `TestProgram`, exige `wasSuccessful()` y UNA prueba ejecutada y sale con código 3
        si no: antes descartaba el resultado y un `RuntimeError` en la prueba interior dejaba el metatest en verde.
        Control negativo de la sonda: apuntada a una prueba que no existe, sale con código distinto de 0."""
        sonda = textwrap.dedent("""
            import json, sys, time, unittest
            antes = hasattr(time.perf_counter, '_vigilado')
            @IMPORTAR@
            import _vigilancia as v
            una_vez = all(not hasattr(getattr(m, n).__wrapped__, '_vigilado') for m, n in v.OBJETIVOS)
            instalada = v.instalada()
            programa = unittest.main(module=None, argv=['x', '@OBJETIVO@'], exit=False, verbosity=0)
            ok = programa.result.wasSuccessful() and programa.result.testsRun == 1
            print(json.dumps({'antes': antes, 'instalada': instalada, 'una_vez': una_vez, 'al_acabar': v.instalada(),
                              'ejecutadas': programa.result.testsRun, 'exito': ok}))
            sys.exit(0 if ok else 3)
            """)
        entorno = {**os.environ, 'PYTHONPATH': os.pathsep.join(p for p in sys.path if p)}

        def correr(importar, objetivo):
            codigo = sonda.replace('@IMPORTAR@', importar).replace('@OBJETIVO@', objetivo)
            return subprocess.run([sys.executable, '-c', codigo], cwd=REAL_REPO / 'pipeline', env=entorno,
                                  capture_output=True, text=True, timeout=300)
        real = 'test_qa_esc_apply.VigilanciaDeRelojesTest'
        for importar in ('import test_seudonimos, test_qa_esc_apply', 'import test_qa_esc_apply, test_seudonimos',
                         'import test_qa_esc_apply'):
            with self.subTest(importar=importar):
                proceso = correr(importar, real)
                self.assertEqual(proceso.returncode, 0, proceso.stderr[-1500:])
                self.assertEqual(json.loads(proceso.stdout.strip().splitlines()[-1]),
                                 {'antes': False, 'instalada': True, 'una_vez': True, 'al_acabar': True,
                                  'ejecutadas': 1, 'exito': True})
        with self.subTest(control='una prueba interior que no existe'):
            self.assertNotEqual(correr('import test_qa_esc_apply', 'test_qa_esc_apply.NoExiste').returncode, 0)
        for nombre in MODULOS_DE_PRUEBAS:
            arbol = ast.parse((TESTS / nombre).read_text(encoding='utf-8'))
            primera = next(n for n in arbol.body if not (isinstance(n, ast.Expr) and isinstance(n.value, ast.Constant)))
            with self.subTest(modulo=nombre):
                self.assertTrue(isinstance(primera, ast.Import) and [a.name for a in primera.names] == ['_vigilancia'])
                self.assertFalse({'setUpModule', 'tearDownModule'} & {n.name for n in arbol.body
                                                                       if isinstance(n, ast.FunctionDef)})

    def test_ningun_alias_del_reloj_original_sobrevive_a_la_instalacion(self):
        """AC256.3 (enmienda 59, Codex 49a-1, 49b-1, 49c-1): `instalar` sustituye por la envoltura todo valor de un
        módulo ya cargado que sea un reloj original. En un intérprete nuevo: (a) un ayudante cargado ANTES de la guarda
        reexporta `from time import perf_counter as clock` y un consumidor de `pipeline/tests` lo llama: AssertionError
        (antes, un float); (b) `threading._time()` desde una sonda de `pipeline/tests`: AssertionError (antes, un float:
        `threading` es la biblioteca estándar y `multiprocessing` lo carga antes), y `threading.Timer`,
        `Thread.join(timeout)` y `Event.wait` siguen funcionando; (c) un alias creado DESPUÉS de la instalación sale
        envuelto, y repetir la instalación no envuelve dos veces."""
        sonda = textwrap.dedent(r"""
            import json, sys, threading, types
            from pathlib import Path
            TESTS = Path('@TESTS@')
            OBJETIVOS = json.loads('@OBJETIVOS@')
            # los que piden argumentos los llevan válidos; para el resto no hay ninguno (el original fallaría con
            # TypeError, que tampoco es el rechazo)
            ARGUMENTOS = {'clock_gettime': '0', 'clock_gettime_ns': '0', 'clock_getres': '0',
                          'get_clock_info': "'monotonic'", 'getrusage': '0', 'getitimer': '0'}

            class ModuloConVista(types.ModuleType):
                @property
                def __dict__(self):
                    return types.MappingProxyType(types.ModuleType.__dict__['__dict__'].__get__(self))

            def cargar(nombre, texto, fichero, clase=types.ModuleType):
                modulo = clase(nombre)
                sys.modules[nombre] = modulo
                espacio = types.ModuleType.__dict__['__dict__'].__get__(modulo)
                exec(compile(texto, str(TESTS / fichero), 'exec'), espacio)
                return modulo

            def veredicto(funcion):
                try:
                    funcion()
                except AssertionError:
                    return 'AssertionError'
                except Exception as fallo:
                    return type(fallo).__name__
                return 'lee el reloj'
            # ANTES de la guarda: un módulo por CADA reloj, un ayudante que reexporta perf_counter y uno exótico
            for i, (modulo, nombre) in enumerate(OBJETIVOS):
                cargar(f'e60_alias_{i}', f'from {modulo} import {nombre} as alias\n', f'e60_alias_{i}.py')
            cargar('e59_ayudante', 'from time import perf_counter as clock\n', 'e59_ayudante.py')
            cargar('e60_vista', 'from time import perf_counter as clock\n', 'e60_vista.py', ModuloConVista)
            import test_seudonimos   # la instala en su primera línea
            import _vigilancia as v
            usos = {}
            for i, (modulo, nombre) in enumerate(OBJETIVOS):
                uso = cargar(f'e60_uso_{i}', f'from e60_alias_{i} import alias\n'
                             f'def leer():\n    return alias({ARGUMENTOS.get(nombre, "")})\n', f'e60_uso_{i}.py')
                usos[f'{modulo}.{nombre}'] = veredicto(uso.leer)   # el rechazo, ya, sin volver a llamar a instalar()
            consumidor = cargar('e59_consumidor', 'from e59_ayudante import clock\ndef leer():\n    return clock()\n',
                                'e59_consumidor.py')
            vista = cargar('e60_vista_desde', 'from e60_vista import clock\ndef leer():\n    return clock()\n',
                           'e60_vista_desde.py')
            vista_atributo = cargar('e60_vista_atributo', 'import e60_vista\n'
                                    'def leer():\n    return e60_vista.clock()\n', 'e60_vista_atributo.py')
            hilos = cargar('e59_hilos', 'import threading\ndef leer():\n    return threading._time()\n', 'e59_hilos.py')
            posterior = cargar('e59_posterior', 'from time import perf_counter as otro\n'
                               'def leer():\n    return otro()\n', 'e59_posterior.py')   # DESPUÉS de la guarda
            resultado = {'ayudante': veredicto(consumidor.leer), 'threading': veredicto(hilos.leer),
                         'vista_desde': veredicto(vista.leer), 'vista_atributo': veredicto(vista_atributo.leer),
                         'posterior': veredicto(posterior.leer)}
            hecho = threading.Event()
            temporizador = threading.Timer(0.01, hecho.set)
            temporizador.start()
            temporizador.join(timeout=5)
            v.instalar()
            una_vez = all(not hasattr(getattr(m, n).__wrapped__, '_vigilado') for m, n in v.OBJETIVOS)
            print(json.dumps({'usos': usos, **resultado, 'temporizador': hecho.is_set(),
                              'espera': threading.Event().wait(0.01), 'envuelta_una_vez': una_vez}))
            """).replace('@TESTS@', str(TESTS)).replace('@OBJETIVOS@', json.dumps(
            [(modulo.__name__, nombre) for modulo, nombre in _vigilancia.OBJETIVOS]))
        entorno = {**os.environ, 'PYTHONPATH': os.pathsep.join(p for p in sys.path if p)}
        proceso = subprocess.run([sys.executable, '-c', sonda], cwd=REAL_REPO / 'pipeline', env=entorno,
                                 capture_output=True, text=True, timeout=300)
        self.assertEqual(proceso.returncode, 0, proceso.stderr[-1500:])
        visto = json.loads(proceso.stdout.strip().splitlines()[-1])
        usos = visto.pop('usos')
        self.assertEqual(usos, {f'{modulo.__name__}.{nombre}': 'AssertionError'
                                for modulo, nombre in _vigilancia.OBJETIVOS})
        self.assertEqual(visto, {'ayudante': 'AssertionError', 'threading': 'AssertionError',
                                 'vista_desde': 'AssertionError', 'vista_atributo': 'AssertionError',
                                 'posterior': 'AssertionError', 'temporizador': True, 'espera': False,
                                 'envuelta_una_vez': True})

    def test_una_importacion_de_un_reloj_cuenta_como_mencion(self):
        """AC256.2 (enmienda 59, Codex 49a-1, 49b-1): `menciones_de_reloj` cuenta CADA importación de un reloj aunque no
        tenga usos locales (un módulo que solo reexporta), también con asterisco o con un alias del módulo; un `import
        time` sin alias, `time.sleep` y lo que no es un reloj, no. Defensa en profundidad: lo que cierra el hueco en
        ejecución es `instalar`."""
        for fuente in ('from time import perf_counter as clock\n', 'from time import perf_counter\n',
                       'from os import times\n', 'from time import *\n', 'from os import *\n', 'import time as t\n',
                       'from resource import getrusage as ru\n', 'from signal import getitimer\n', 'import timeit\n',
                       'def f():\n    from time import time_ns\n'):
            with self.subTest(mencion=fuente):
                self.assertTrue(menciones_de_reloj(fuente))
        for fuente in ('import time\n', 'import time\ntime.sleep(0)\n', 'from time import sleep, strftime\n',
                       'from os import path\n', 'import os, signal\n', 'import signal\nsignal.SIGINT\n'):
            with self.subTest(sin_mencion=fuente):
                self.assertEqual(menciones_de_reloj(fuente), set())

    def test_un_alias_reutilizado_en_otro_ambito_no_oculta_una_mencion(self):
        """AC263 (enmienda 61, Codex 51b-1): un alias de `import X as Y` o de `from X import n as m` puede ligarse a
        varios relojes en ámbitos distintos (`import resource as api` global y `import signal as api` en una función):
        `menciones_de_reloj` guarda el CONJUNTO por alias y no deja que el último sobrescriba al primero, en cualquier
        orden y con el alias local en una función, un método o el cuerpo de una clase. Un alias reutilizado SIN reloj no
        se cuenta."""
        global_ = 'import resource as api\nvalor = api.getrusage(0)\n'
        local = 'def f():\n    import signal as api\n    return api\n'
        mencion = {('<módulo>', 'resource.getrusage')}
        for forma, fuente in (
                ('global y después local en una función', global_ + local),
                ('local en una función y después global', local + global_),
                ('local en un método', global_ + 'class C:\n    def m(self):\n        import signal as api\n'),
                ('local en el cuerpo de una clase', global_ + 'class C:\n    import signal as api\n'),
                ('sin el alias local', global_)):
            with self.subTest(forma=forma):
                self.assertEqual(menciones_de_reloj(fuente), mencion)
        with self.subTest(forma='el otro orden de los módulos'):
            self.assertEqual(menciones_de_reloj('import signal as api\nvalor = api.getitimer(0)\n'
                                                'def f():\n    import resource as api\n    return api\n'),
                             {('<módulo>', 'signal.getitimer')})
        with self.subTest(forma='from … import … as, una función que usa el global'):
            self.assertEqual(menciones_de_reloj('from time import perf_counter as c\n'
                                                'def f():\n    from os import times as c\n'
                                                'def g():\n    return c()\n'),
                             {('<módulo>', 'time.perf_counter'), ('f', 'os.times'),
                              ('g', 'time.perf_counter'), ('g', 'os.times')})
        for forma, fuente in (('resource y signal', 'import resource as api\nvalor = api.RLIMIT_CPU\n'
                                                    'def f():\n    import signal as api\n    return api.SIGINT\n'),
                              ('os y signal', 'import os as api\nvalor = api.path\n'
                                              'def f():\n    import signal as api\n    return api.SIGINT\n')):
            with self.subTest(sin_mencion=forma):
                self.assertEqual(menciones_de_reloj(fuente), set())

    def test_los_modulos_de_pruebas_y_sus_ayudantes_tienen_co_filename_absoluto(self):
        """AC258 (enmienda 59, Codex 49a-2): la guarda supone `co_filename` ABSOLUTO, como lo da el sistema de
        importación (`import`, `discover`, `-m unittest`); un código cargado por ruta relativa con `runpy` y un `chdir`
        previo puede escapar (límite declarado). La precondición, comprobada: las funciones de los módulos de
        `pipeline/tests` cargados (los dos de pruebas, sus copias y los ayudantes) tienen un `co_filename` absoluto, y
        también sus `__file__`. AC261 (enmienda 60, Codex 50c-1): también los cuerpos envueltos (`presupuesto`,
        `medida`, `AuditoriaTest.snapshot_vacio`): se siguen `__wrapped__`, `__func__` y `fget`."""
        for nombre in ('test_seudonimos', 'test_qa_esc_apply'):   # los dos están cargados, también si se corre uno solo
            importlib.import_module(nombre)
        vistos = set()
        for modulo in list(sys.modules.values()):
            fichero = getattr(modulo, '__file__', None)
            if not fichero or not Path(fichero).resolve().is_relative_to(TESTS):
                continue
            vistos.add(os.path.basename(fichero))
            with self.subTest(modulo=modulo.__name__):
                self.assertTrue(os.path.isabs(fichero))
                valores = list(vars(modulo).values())
                for clase in [v for v in valores if isinstance(v, type) and v.__module__ == modulo.__name__]:
                    valores += list(vars(clase).values())
                self.assertEqual(rutas_relativas(valores), [])
        self.assertLessEqual({'test_seudonimos.py', 'test_qa_esc_apply.py', '_vigilancia.py'}, vistos)

    def test_la_precondicion_de_rutas_absolutas_mira_los_cuerpos_envueltos(self):
        """AC261 (enmienda 60, Codex 50c-1), controles negativos: `rutas_relativas` encuentra una función de
        `co_filename` relativo aunque esté tras un `contextlib.contextmanager`, un `functools.wraps`, un `staticmethod`,
        un `classmethod` o una `property` (el control anterior solo miraba las funciones desnudas y daba verde), y no da
        nada si todo es absoluto."""
        def funcion(fichero):
            ambito = {}
            exec(compile('def f():\n    yield\n', fichero, 'exec'), ambito)
            return ambito['f']
        relativa, absoluta = funcion('relativa.py'), funcion(str(TESTS / 'e60_absoluta.py'))

        def con_wraps(f):
            @functools.wraps(f)
            def envoltura(*args, **kwargs):
                return f(*args, **kwargs)
            return envoltura
        for nombre, valor in (('desnuda', relativa), ('contextmanager', contextlib.contextmanager(relativa)),
                              ('wraps', con_wraps(relativa)), ('staticmethod', staticmethod(relativa)),
                              ('classmethod', classmethod(relativa)), ('property', property(relativa)),
                              ('contextmanager sobre wraps', contextlib.contextmanager(con_wraps(relativa)))):
            with self.subTest(forma=nombre):
                self.assertEqual(rutas_relativas([valor]), ['f'])
        for nombre, valor in (('desnuda', absoluta), ('contextmanager', contextlib.contextmanager(absoluta)),
                              ('staticmethod', staticmethod(absoluta)), ('property', property(absoluta)),
                              ('código generado (`<string>`)', funcion('<string>'))):
            with self.subTest(forma=nombre, absoluta=True):
                self.assertEqual(rutas_relativas([valor]), [])

    def test_rutas_relativas_sigue_wrapped_en_cualquier_objeto(self):
        """AC264 (enmienda 61, Codex 51c-1): `rutas_relativas` sigue `__wrapped__` en CUALQUIER objeto que lo tenga, no
        solo en una función: un `functools.lru_cache` (que no es una función) cortaba la cadena y el cuerpo relativo
        quedaba sin ver. Sin lista de tipos; un ciclo de `__wrapped__` termina."""
        def funcion(fichero):
            ambito = {}
            exec(compile('def f():\n    yield\n', fichero, 'exec'), ambito)
            return ambito['f']
        relativa, absoluta = funcion('relativa.py'), funcion(str(TESTS / 'e61_absoluta.py'))

        def con_wraps(f):
            @functools.wraps(f)
            def envoltura(*args, **kwargs):
                return f(*args, **kwargs)
            return envoltura

        class Llamable:
            def __call__(self, *args):
                return None

        def sin_envuelto(self):
            raise AttributeError('__wrapped__')

        class Estatico(staticmethod):   # desde Python 3.10 un `staticmethod` expone `__wrapped__`; este no
            __wrapped__ = property(sin_envuelto)

        class DeClase(classmethod):
            __wrapped__ = property(sin_envuelto)
        lru = functools.lru_cache(maxsize=1)
        real = AuditoriaTest.__dict__['snapshot_vacio'].__func__
        snapshot_relativo = types.FunctionType(real.__code__.replace(co_filename='relativa.py'), real.__globals__,
                                               real.__name__)
        snapshot_relativo.__qualname__ = real.__qualname__
        envuelto = functools.update_wrapper(Llamable(), relativa)
        for forma, valor in (('lru_cache', lru(relativa)),
                             ('staticmethod sobre lru_cache', staticmethod(lru(relativa))),
                             ('classmethod sobre lru_cache', classmethod(lru(relativa))),
                             ('wraps sobre un objeto que no es función', envuelto),
                             ('staticmethod sin `__wrapped__`: queda `__func__`', Estatico(relativa)),
                             ('classmethod sin `__wrapped__`: queda `__func__`', DeClase(relativa)),
                             ('dos envoltorios', lru(con_wraps(relativa))),
                             ('tres envoltorios', staticmethod(lru(con_wraps(lru(relativa)))))):
            with self.subTest(forma=forma):
                self.assertEqual(rutas_relativas([valor]), ['f'])
        with self.subTest(forma='AuditoriaTest.snapshot_vacio envuelto con staticmethod(lru_cache(…))'):
            self.assertEqual(rutas_relativas([staticmethod(lru(snapshot_relativo))]), ['AuditoriaTest.snapshot_vacio'])
        for forma, valor in (('lru_cache', lru(absoluta)),
                             ('staticmethod sobre lru_cache', staticmethod(lru(absoluta)))):
            with self.subTest(forma=forma, absoluta=True):
                self.assertEqual(rutas_relativas([valor]), [])
        ciclo, ciclo_de_funcion = Llamable(), funcion('relativa.py')
        ciclo.__wrapped__, ciclo_de_funcion.__wrapped__ = ciclo, ciclo_de_funcion
        with self.subTest(forma='ciclo a.__wrapped__ = a'):
            self.assertEqual(rutas_relativas([ciclo]), [])
            self.assertEqual(rutas_relativas([ciclo_de_funcion]), ['f'])

