    def test_la_prueba_dinamica_denuncia_cada_forma_y_no_a_los_limpios(self):
        """AC265 (enmienda 62), controles: módulos sintéticos en un directorio temporal (con una copia de
        `_vigilancia.py`, así la guarda lo trata como `pipeline/tests`) que leen un reloj AL IMPORTARSE (alias por
        asignación y cadenas, con `time`, `os`, `resource` y `signal`; lectura dentro de `if`, `try` y `with` antes de
        importar la guarda; `getattr`; `importlib`; un atributo privado de la biblioteca estándar; el literal; uno
        cuyo nombre empieza por `test_qa`) se denuncian por su nombre, con su fichero en el mensaje; los limpios, no."""
        lee = {
            'e62_asig_time': 'import time\notro = time\nLEIDO = otro.perf_counter()\n',
            'e62_asig_os': 'import os\napi = os\nLEIDO = api.times()\n',
            'e62_asig_resource': 'import resource\napi = resource\nLEIDO = api.getrusage(0)\n',
            'e62_asig_signal': 'import signal\napi = signal\nLEIDO = api.getitimer(signal.ITIMER_REAL)\n',
            'e62_cadena_time': 'import time\na = time\nb = a\nLEIDO = b.perf_counter()\n',
            'e62_cadena_os': 'import os\na = os\nb = a\nLEIDO = b.times()\n',
            'e62_cadena_resource': 'import resource\na = resource\nb = a\nLEIDO = b.getrusage(0)\n',
            'e62_cadena_signal': 'import signal\na = signal\nb = a\nLEIDO = b.getitimer(signal.ITIMER_REAL)\n',
            'e62_tupla': 'import os\napi, _ = os, 0\nLEIDO = api.times()\n',
            'e62_if': 'if True:\n    import resource as api\n    LEIDO = api.getrusage(0)\nimport _vigilancia\n',
            'e62_try': ('try:\n    import resource as api\n    LEIDO = api.getrusage(0)\n'
                        'except ImportError:\n    pass\nimport _vigilancia\n'),
            'e62_with': ('with open(__file__):\n    import resource as api\n    LEIDO = api.getrusage(0)\n'
                         'import _vigilancia\n'),
            'e62_getattr': "import time\nLEIDO = getattr(time, 'perf_counter')()\n",
            'e62_from_import': 'from time import perf_counter as c\nLEIDO = c()\n',
            'e62_importlib': "import importlib\nLEIDO = importlib.import_module('time').perf_counter()\n",
            'e62_privado': 'from threading import _time as c\nLEIDO = c()\n',
            'e62_literal': 'import time\nLEIDO = time.perf_counter()\n',
            'test_qa_e62_literal': 'import time\nLEIDO = time.perf_counter()\n'}
        limpios = {
            'e62_limpio_importa_time': 'import time\nDORMIR = time.sleep\nMEDIR = time.perf_counter\n',
            'e62_limpio_alias_sin_reloj': ('import resource as api\nLIMITE = api.RLIMIT_CPU\n\n\ndef f():\n'
                                           '    import signal as api\n    return api.SIGINT\n'),
            'e62_limpio_guarda_primero': 'import _vigilancia\nimport os\nPID = os.getpid()\n',
            'e62_limpio_mediado_por_la_biblioteca': 'import threading\nESPERA = threading.Event().wait(0.001)\n'}
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio)
            shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
            for nombre, fuente in {**lee, **limpios}.items():
                (carpeta / f'{nombre}.py').write_text(fuente, encoding='utf-8')
            antes = sorted(ruta.name for ruta in carpeta.iterdir())
            resultado = leen_un_reloj_al_importar(carpeta)
            denunciados = resultado.denunciados
            self.assertEqual(resultado.tolerados, {})
            self.assertEqual(sorted(ruta.name for ruta in carpeta.iterdir()), antes)   # ni bytecode ni temporales
        for nombre in lee:
            with self.subTest(denuncia=nombre):
                self.assertIn(nombre, denunciados)
                self.assertIn(f'{nombre}.py', denunciados[nombre])
        for nombre in limpios:
            with self.subTest(limpio=nombre):
                self.assertNotIn(nombre, denunciados)
        self.assertEqual(set(denunciados), set(lee))

    def test_la_prueba_dinamica_no_oculta_otros_errores_ni_un_cuelgue(self):
        """AC265 (enmienda 62), controles: un error de importación que no es de la guarda, un módulo que mata el
        intérprete sin resultado (código de salida distinto de 0) y uno que se cuelga hacen fallar la prueba con su
        propio mensaje (no devuelven `{}`); lo de la guarda se sigue viendo junto a un error."""
        casos = (('un error de importación', {'e62_roto': 'import modulo_que_no_existe_e62\n'}, RuntimeError,
                  'ModuleNotFoundError'),
                 ('el error y la denuncia', {'e62_roto': 'import modulo_que_no_existe_e62\n',
                                             'e62_literal': 'import time\nLEIDO = time.perf_counter()\n'},
                  RuntimeError, 'e62_literal'),
                 ('un intérprete que muere', {'e62_muere': 'import os\nos._exit(3)\n'}, RuntimeError, 'código 3'),
                 ('un módulo que se cuelga', {'e62_cuelga': 'import time\ntime.sleep(12)\n'},
                  subprocess.TimeoutExpired, '1'))
        for forma, modulos, excepcion, texto in casos:
            with self.subTest(forma=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio)
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                for nombre, fuente in modulos.items():
                    (carpeta / f'{nombre}.py').write_text(fuente, encoding='utf-8')
                with self.assertRaises(excepcion) as visto:
                    leen_un_reloj_al_importar(carpeta, plazo=1 if excepcion is subprocess.TimeoutExpired else 60)
                self.assertIn(texto, str(visto.exception))
                if excepcion is RuntimeError and 'e62_roto' in modulos:
                    self.assertIn('e62_roto', str(visto.exception))

    def _importar_sintetico(self, modulos, tabla=None, plazo=60, enlaces=None):
        """Los módulos sintéticos `modulos` ({ruta relativa: fuente, o una función de la carpeta física que la da}) en
        un directorio temporal FÍSICO (resuelto) con una copia de `_vigilancia.py` (la guarda lo trata como
        `pipeline/tests`) y los enlaces simbólicos `enlaces` ({nombre: destino}), y el resultado de
        `leen_un_reloj_al_importar`."""
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
            for nombre, destino in (enlaces or {}).items():
                os.symlink(destino, carpeta / nombre)
            for nombre, fuente in modulos.items():
                (carpeta / nombre).parent.mkdir(parents=True, exist_ok=True)
                (carpeta / nombre).write_text(fuente(carpeta) if callable(fuente) else fuente, encoding='utf-8')
            if tabla is None:
                return leen_un_reloj_al_importar(carpeta, plazo=plazo)
            return leen_un_reloj_al_importar(carpeta, plazo=plazo, entorno=tabla)

    def test_la_prueba_dinamica_tolera_solo_el_error_de_entorno_exacto_de_la_tabla(self):
        """AC267, AC270 (enmienda 62, 63), controles con una tabla sintética: el par EXACTO de la tabla (tipo builtin
        exacto, nombre igual o ruta exacta bajo la raíz del repo, sin encadenar) se tolera y SE INFORMA; una subclase
        homónima, el mismo tipo con otro nombre (`another/…`, `….types`), otra raíz con el mismo sufijo (alineado o
        no), otro tipo, un error encadenado (con `from` o implícito) o un módulo fuera de la tabla fallan; una lectura
        de reloj ANTES del import que falla se denuncia (gana la primera excepción), y una entrada de la tabla para un
        módulo que lanza la guarda se denuncia igual."""
        relativa = 'specs/tools/ausente_e63.py'
        exacta = str(TESTS.parents[1] / relativa)
        tabla = {'e63_sin_modulo': ('ModuleNotFoundError', 'modulo_inexistente_e63'),
                 'e63_sin_fichero': ('FileNotFoundError', relativa)}
        sin_modulo = 'import modulo_inexistente_e63\n'
        sin_fichero = f'open({exacta!r})\n'
        lee = 'import time\nLEIDO = time.perf_counter()\n'
        with self.subTest(forma='el error exacto de la tabla se tolera y se informa'):
            resultado = self._importar_sintetico(
                {'e63_sin_modulo.py': sin_modulo, 'e63_sin_fichero.py': sin_fichero, 'e63_literal.py': lee,
                 'e63_limpio.py': 'X = 1\n'}, tabla)
            self.assertEqual(resultado.tolerados, {'e63_sin_modulo': 'ModuleNotFoundError: modulo_inexistente_e63',
                                                   'e63_sin_fichero': f'FileNotFoundError: {relativa}'})
            self.assertEqual(set(resultado.denunciados), {'e63_literal'})
        homonima_m = ('class ModuleNotFoundError(ModuleNotFoundError):\n    pass\n'
                      "raise ModuleNotFoundError('x', name='modulo_inexistente_e63')\n")
        homonima_f = ('class FileNotFoundError(FileNotFoundError):\n    pass\n'
                      f"raise FileNotFoundError(2, 'no', {exacta!r})\n")
        encadenado = ("try:\n    {causa}\nexcept {tipo} as e:\n"
                      "    raise ModuleNotFoundError('x', name='modulo_inexistente_e63') from e\n")
        for forma, modulos in (
                ('el mismo tipo con otro nombre', {'e63_sin_modulo.py': 'import otro_modulo_e63\n'}),
                ('un nombre con un prefijo de ruta',
                 {'e63_sin_modulo.py': "raise ModuleNotFoundError('x', name='another/modulo_inexistente_e63')\n"}),
                ('un submódulo del nombre',
                 {'e63_sin_modulo.py': "raise ModuleNotFoundError('x', name='modulo_inexistente_e63.types')\n"}),
                ('otra raíz con el mismo sufijo', {'e63_sin_fichero.py': f"open('/otro-checkout/{relativa}')\n"}),
                ('un sufijo que no está alineado', {'e63_sin_fichero.py': f"open('/otro/x{relativa}')\n"}),
                ('la ruta de otro nombre',
                 {'e63_sin_fichero.py': f"open({str(TESTS.parents[1] / 'specs/otra/cosa.py')!r})\n"}),
                ('otro tipo de excepción',
                 {'e63_sin_modulo.py': 'raise FileNotFoundError(2, "no", "modulo_inexistente_e63")\n'}),
                ('una subclase homónima de ModuleNotFoundError', {'e63_sin_modulo.py': homonima_m}),
                ('una subclase homónima de FileNotFoundError', {'e63_sin_fichero.py': homonima_f}),
                ('encadenado desde RuntimeError',
                 {'e63_sin_modulo.py': encadenado.format(causa="raise RuntimeError('x')", tipo='RuntimeError')}),
                ('encadenado desde ZeroDivisionError',
                 {'e63_sin_modulo.py': encadenado.format(causa='1 / 0', tipo='ZeroDivisionError')}),
                ('con un contexto implícito', {'e63_sin_modulo.py': (
                    "try:\n    1 / 0\nexcept ZeroDivisionError:\n"
                    "    raise ModuleNotFoundError('x', name='modulo_inexistente_e63')\n")}),
                ('con una causa explícita y contexto nulo (fuera de un except)', {'e63_sin_modulo.py': (
                    "raise ModuleNotFoundError('x', name='modulo_inexistente_e63') from RuntimeError('causa')\n")}),
                ('una ruta con `..` equivalente a la exacta', {'e63_sin_fichero.py': (
                    f"open({str(TESTS.parents[1] / 'specs/otra/../tools/ausente_e63.py')!r})\n")}),
                ('un módulo fuera de la tabla', {'e63_fuera.py': sin_modulo})):
            with self.subTest(forma=forma):
                with self.assertRaises(RuntimeError) as visto:
                    self._importar_sintetico(modulos, tabla)
                self.assertIn(next(iter(modulos))[:-3], str(visto.exception))
        with self.subTest(forma='una ruta equivalente por un enlace simbólico físico a la raíz'):
            with self.assertRaises(RuntimeError) as visto:
                self._importar_sintetico(
                    {'e63_sin_fichero.py': lambda carpeta: f"open({str(carpeta / 'enlace' / relativa)!r})\n"},
                    tabla, enlaces={'enlace': TESTS.parents[1]})
            self.assertIn('e63_sin_fichero', str(visto.exception))
        with self.subTest(forma='una lectura antes del import que falla se denuncia'):
            resultado = self._importar_sintetico({'e63_sin_modulo.py': lee + sin_modulo}, tabla)
            self.assertEqual((set(resultado.denunciados), resultado.tolerados), ({'e63_sin_modulo'}, {}))
        with self.subTest(forma='una entrada de la tabla para un módulo que lanza la guarda'):
            resultado = self._importar_sintetico({'e63_sin_fichero.py': lee}, tabla)
            self.assertEqual((set(resultado.denunciados), resultado.tolerados), ({'e63_sin_fichero'}, {}))
        with self.subTest(forma='una entrada de la tabla para un módulo que importa bien'):
            resultado = self._importar_sintetico({'e63_sin_modulo.py': 'X = 1\n'}, tabla)
            self.assertEqual((resultado.denunciados, resultado.tolerados), ({}, {}))

    def test_la_prueba_dinamica_recorre_todo_el_arbol_y_arranca_como_el_ejecutor_real(self):
        """AC268 (enmienda 63, Codex 53a-1, 53a-2): la prueba dinámica importa también los paquetes y subdirectorios,
        por su nombre cualificado y un paquete antes que sus submódulos (sin `__pycache__`), y con `unittest` ya
        cargado como en `python -m unittest` y en `discover`: un `__init__.py` que lee el reloj, un submódulo de un
        paquete limpio que lo lee, y un ayudante que solo lo lee si `unittest` está cargado se denuncian; un árbol
        limpio, y un `.py` en `__pycache__`, no."""
        lee = 'import time\nLEIDO = time.perf_counter()\n'
        with self.subTest(forma='un paquete con un __init__ que lee el reloj, y su submódulo'):
            resultado = self._importar_sintetico({'e63_pkg/__init__.py': lee, 'e63_pkg/sub.py': 'X = 1\n'})
            # el paquete, antes que su submódulo
            self.assertEqual(list(resultado.denunciados), ['e63_pkg', 'e63_pkg.sub'])
        with self.subTest(forma='un submódulo de un paquete limpio que lee el reloj'):
            resultado = self._importar_sintetico({'e63_limpio/__init__.py': 'X = 1\n', 'e63_limpio/sub.py': lee,
                                                  'e63_limpio/hondo/__init__.py': 'Y = 2\n',
                                                  'e63_limpio/hondo/m.py': lee})
            self.assertEqual(set(resultado.denunciados), {'e63_limpio.sub', 'e63_limpio.hondo.m'})
        with self.subTest(forma='un ayudante que solo lee el reloj si unittest está cargado'):
            resultado = self._importar_sintetico({
                '_ayuda.py': "import sys\nimport time\nif 'unittest' in sys.modules:\n    time.perf_counter()\n",
                'test_a.py': 'import unittest\nimport _ayuda\n'})
            self.assertIn('_ayuda', resultado.denunciados)
        with self.subTest(forma='un árbol limpio y un .py en __pycache__ no se denuncian'):
            resultado = self._importar_sintetico({
                'e63_ok/__init__.py': 'X = 1\n', 'e63_ok/sub/__init__.py': 'Y = 2\n', 'e63_ok/sub/m.py': 'Z = 3\n',
                'e63_plano.py': 'W = 4\n', '__pycache__/e63_x.py': lee, 'e63_ok/__pycache__/e63_y.py': lee})
            self.assertEqual((resultado.denunciados, resultado.tolerados), ({}, {}))

    def test_la_prueba_dinamica_no_deja_procesos_vivos(self):
        """AC269 (enmienda 63, Codex 53a-3): el intérprete de la sonda va en un grupo de procesos propio y, por
        cualquier camino de salida (plazo vencido, salida normal), el grupo entero muere: el descendiente que lanza un
        módulo ya no existe al volver, y tras un plazo vencido el módulo no llega a ejecutar lo que va después de
        colgarse. Sin `killpg` cada subTest falla por aserción en pocos segundos (el descendiente vive 600 s, mucho más
        que todo)."""
        def vivo(pid):
            for _ in range(60):   # SIGKILL es asíncrono: hasta que el sistema lo recoja
                try:
                    os.kill(pid, 0)
                except ProcessLookupError:
                    return False
                threading.Event().wait(0.05)
            return True
        for forma, cuelgue, plazo in (('tras el plazo vencido', 'import time\ntime.sleep(5)\n', 1),
                                      ('tras una salida normal del intérprete', '', 10)):
            with self.subTest(forma=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio)
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                (carpeta / 'e63_z.py').write_text(
                    "import subprocess, sys\n"
                    "p = subprocess.Popen([sys.executable, '-c', 'import time; time.sleep(600)'])\n"
                    f"open({str(carpeta / 'pid.txt')!r}, 'w').write(str(p.pid))\n" + cuelgue
                    + f"open({str(carpeta / 'llego.txt')!r}, 'w').write('llegó')\n", encoding='utf-8')
                try:
                    if cuelgue:
                        with self.assertRaises(subprocess.TimeoutExpired):
                            leen_un_reloj_al_importar(carpeta, plazo=plazo)
                        self.assertFalse((carpeta / 'llego.txt').exists(), 'el módulo siguió ejecutándose')
                    else:
                        self.assertEqual(leen_un_reloj_al_importar(carpeta, plazo=plazo).denunciados, {})
                    self.assertFalse(vivo(int((carpeta / 'pid.txt').read_text())), 'el descendiente sigue vivo')
                finally:   # nada queda vivo aunque el control falle
                    if (carpeta / 'pid.txt').exists():
                        pid = int((carpeta / 'pid.txt').read_text())
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            if os.getpgid(pid) != os.getpgrp():   # nunca el grupo del propio ejecutor de pruebas
                                os.killpg(os.getpgid(pid), signal.SIGKILL)
                        with contextlib.suppress(ProcessLookupError):
                            os.kill(pid, signal.SIGKILL)

    @classmethod
    def _siguen_vivos(cls, pids):
        """Los de `pids` que existen y no son zombis (muertos que nadie ha recogido todavía) tras una espera COMPARTIDA:
        SIGKILL es asíncrono, y esperar a cada uno por separado multiplicaría el plazo de un fallo."""
        vivos = list(pids)
        for _ in range(60):
            vivos = [pid for pid in vivos if cls._existe(pid)]
            if not vivos:
                break
            threading.Event().wait(0.05)
        return vivos

    @staticmethod
    def _estado_de(pid, plazo=2):
        """AC284, AC285 (enmienda 68, 69): el estado de `ps` de `pid` (`''` si no existe), con plazo, por el ayudante único.
        Un `ps` que no vuelve hace fallar con una aserción propia (`_consultar_ps` lo mata y lo recoge, aunque su primer
        `kill` falle), sin depender del vigilante ni de un límite externo."""
        try:
            return _consultar_ps(['-o', 'stat=', '-p', str(pid)], plazo)[2].strip()
        except subprocess.TimeoutExpired as error:
            raise AssertionError(f'ps -p {pid} no volvió en {plazo:g} s: se le mató') from error

    @classmethod
    def _existe(cls, pid):
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return False
        estado = cls._estado_de(pid)
        return bool(estado) and not estado.startswith('Z')

    @classmethod
    def _sigue_vivo(cls, pid):
        return bool(cls._siguen_vivos([pid]))

    @staticmethod
    def _leer_pids(carpeta):
        """Los pid que escribieron `a.pid` a `d.pid` (esperando a que existan)."""
        pids = {}
        for nombre in 'abcd':
            ruta = carpeta / f'{nombre}.pid'
            for _ in range(150):
                if ruta.exists() and ruta.read_text().strip().isdigit():
                    pids[nombre] = int(ruta.read_text())
                    break
                threading.Event().wait(0.02)
        return pids

    @staticmethod
    def _escribir_descendientes(carpeta, cuelga):
        """AC271: `e64_z.py` lanza cuatro descendientes (a: `process_group=0`; b: `start_new_session=True`, que a su vez
        lanza c con `process_group=0`; d: nieto por doble `fork` que queda huérfano pero SIGUE en el grupo de la sonda,
        al que solo llega `killpg`), espera a que los cuatro hayan escrito su pid y, con `cuelga`, se cuelga. Todos
        duermen 600 s: mucho más que cualquier otra cosa de la prueba."""
        (carpeta / 'dormir.code').write_text('import time\ntime.sleep(600)\n')
        (carpeta / 'b.code').write_text(
            'import subprocess, sys, time\n'
            "c = subprocess.Popen([sys.executable, sys.argv[1] + '/dormir.code'], process_group=0,\n"
            '                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n'
            "open(sys.argv[1] + '/c.pid', 'w').write(str(c.pid))\ntime.sleep(600)\n")
        (carpeta / 'e64_z.py').write_text(
            'import os, subprocess, sys, time\n'
            f'AQUI = {str(carpeta)!r}\n'
            'nulo = dict(stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n'
            "a = subprocess.Popen([sys.executable, AQUI + '/dormir.code'], process_group=0, **nulo)\n"
            "open(AQUI + '/a.pid', 'w').write(str(a.pid))\n"
            "b = subprocess.Popen([sys.executable, AQUI + '/b.code', AQUI], start_new_session=True, **nulo)\n"
            "open(AQUI + '/b.pid', 'w').write(str(b.pid))\n"
            'intermedio = os.fork()\n'
            'if intermedio == 0:\n'
            '    if os.fork() == 0:\n'
            '        nulo = os.open(os.devnull, os.O_RDWR)\n'
            '        os.dup2(nulo, 1)\n        os.dup2(nulo, 2)\n'
            "        open(AQUI + '/d.pid', 'w').write(str(os.getpid()))\n"
            '        time.sleep(600)\n'
            '    os._exit(0)\n'
            'os.waitpid(intermedio, 0)\n'
            "while not (os.path.exists(AQUI + '/c.pid') and os.path.exists(AQUI + '/d.pid')):\n    time.sleep(0.02)\n"
            + ('time.sleep(60)\n' if cuelga else ''), encoding='utf-8')

    @staticmethod
    def _arrancar_hilo(hilo):
        """Arranca `hilo` con `SIGINT` bloqueado (un hilo hereda la máscara): un hilo auxiliar del propio control no
        puede recibir el `SIGINT` que el control manda al proceso y que la limpieza difiere en el hilo principal."""
        anterior = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGINT})
        try:
            hilo.start()
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, anterior)

    @contextlib.contextmanager
    def _vigilante(self, lideres, espera=8, tambien=lambda: ()):
        """Si la limpieza se cuelga (un líder congelado que nadie mata, un `ps` que no vuelve), tras `espera` s mata,
        sin parar hasta que vuelva, a `lideres[0]` y a los pid de `tambien()` para que el control falle por aserción en
        lugar de colgar la suite."""
        actuo, terminado = [], threading.Event()

        def vigilar():
            if terminado.wait(espera):
                return
            actuo.append(True)
            while not terminado.wait(0.2):
                for pid in [lider.pid for lider in lideres[:1]] + list(tambien()):
                    with contextlib.suppress(ProcessLookupError, PermissionError):
                        os.kill(pid, signal.SIGKILL)
        hilo = threading.Thread(target=vigilar, daemon=True)
        self._arrancar_hilo(hilo)
        try:
            yield
        finally:
            terminado.set()
            hilo.join(timeout=5)
            if hilo.is_alive():   # seguiría matando al líder: el plazo del join no puede vencer en silencio
                self.fail('el hilo vigía no terminó')
            if actuo:
                self.fail('la limpieza de la sonda se colgó (un líder congelado o un ps que nadie mata)')

    def test_la_prueba_dinamica_mata_a_todo_descendiente_por_ppid_en_cada_camino(self):
        """AC271, AC272 (enmienda 64, Codex 54a-1, 54c-1, 54c-2): ningún descendiente de la sonda sobrevive aunque
        cambie de grupo (`process_group=0`) o de sesión (`start_new_session=True`, con un nieto de `process_group=0`),
        ni un nieto huérfano por doble `fork` que sigue en el grupo de la sonda (lo mata `killpg`), por los CUATRO
        caminos de salida: una salida normal, un plazo vencido, una excepción del padre mientras espera y un
        `KeyboardInterrupt` real (un `SIGINT` al propio proceso durante `communicate()`); y en los cuatro el líder queda
        recogido (`waitpid` ya no encuentra al hijo: tras un `KeyboardInterrupt`, `Popen.__exit__` no lo recoge). Los
        pid ya no existen al volver."""
        original = subprocess.Popen.communicate

        def esperar_y_fallar(carpeta):
            def communicate(proceso, *args, **kwargs):
                if proceso.args[1:2] != ['-c']:   # solo el de la sonda; `ps` sigue siendo real
                    return original(proceso, *args, **kwargs)
                self._leer_pids(carpeta)
                raise RuntimeError('fallo del padre mientras espera')
            return communicate
        for camino in ('una salida normal', 'un plazo vencido', 'una excepción del padre', 'un KeyboardInterrupt'):
            with self.subTest(camino=camino), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                self._escribir_descendientes(carpeta, cuelga=camino != 'una salida normal')
                lideres = []

                class Espia(subprocess.Popen):
                    def __init__(proceso, *args, **kwargs):
                        super().__init__(*args, **kwargs)
                        lideres.append(proceso)
                parar = threading.Event()
                manejador = signal.signal(signal.SIGINT, signal.default_int_handler)
                try:
                    with mock.patch('subprocess.Popen', Espia), self._vigilante(lideres):
                        if camino == 'una salida normal':
                            self.assertEqual(leen_un_reloj_al_importar(carpeta, plazo=30).denunciados, {})
                        elif camino == 'un plazo vencido':
                            with self.assertRaises(subprocess.TimeoutExpired):
                                leen_un_reloj_al_importar(carpeta, plazo=3)
                        elif camino == 'una excepción del padre':
                            with mock.patch.object(Espia, 'communicate', esperar_y_fallar(carpeta)):
                                with self.assertRaises(RuntimeError):
                                    leen_un_reloj_al_importar(carpeta, plazo=60)
                        else:
                            def interrumpir():
                                self._leer_pids(carpeta)
                                if not parar.is_set():
                                    os.kill(os.getpid(), signal.SIGINT)
                            hilo = threading.Thread(target=interrumpir, daemon=True)
                            self._arrancar_hilo(hilo)
                            try:
                                with self.assertRaises(KeyboardInterrupt):
                                    leen_un_reloj_al_importar(carpeta, plazo=60)
                            finally:
                                parar.set()
                                hilo.join(timeout=5)
                    pids = self._leer_pids(carpeta)
                    self.assertEqual(sorted(pids), ['a', 'b', 'c', 'd'])
                    for nombre, pid in pids.items():
                        self.assertFalse(self._sigue_vivo(pid), f'el descendiente {nombre} sigue vivo')
                    with self.assertRaises(ChildProcessError, msg='el líder de la sonda quedó sin recoger'):
                        os.waitpid(lideres[0].pid, os.WNOHANG)
                finally:
                    signal.signal(signal.SIGINT, manejador)
                    for pid in self._leer_pids(carpeta).values():   # nada queda vivo aunque el control falle
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            os.kill(pid, signal.SIGKILL)

    @staticmethod
    def _sin_sigint_pendiente():
        """La máscara de señales está como siempre: `SIGINT` no quedó bloqueado por la limpieza (si lo hubiera, el
        siguiente Ctrl-C no llegaría)."""
        return signal.SIGINT not in signal.pthread_sigmask(signal.SIG_BLOCK, set())

    def test_la_limpieza_mata_todo_lo_registrado_aunque_falle_a_mitad(self):
        """AC274 (enmienda 65, Codex 55a-1, 55b-1, 55c-1): un líder y un hijo reales (`start_new_session=True`) y un
        fallo en la SEGUNDA enumeración, cuando el hijo ya está congelado (un `KeyboardInterrupt` real, una
        excepción, un `OSError` persistente), o un `SIGINT` real justo después del primer `SIGSTOP` (antes de que el
        pid se pudiera registrar si se registrase después): la excepción original sale y el hijo está MUERTO al
        volver, comprobado antes de cualquier limpieza del propio test."""
        original_kill = os.kill
        casos = (('un KeyboardInterrupt en la segunda enumeración', KeyboardInterrupt, 'ps2:sigint'),
                 ('una excepción en la segunda enumeración', RuntimeError, 'ps2:error'),
                 ('un OSError persistente desde la segunda enumeración', RuntimeError, 'ps2:oserror'),
                 ('un SIGINT real justo después del primer SIGSTOP', KeyboardInterrupt, 'stop:sigint'))
        for forma, excepcion, inyeccion in casos:
            with self.subTest(forma=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                (carpeta / 'dormir.code').write_text('import time\ntime.sleep(600)\n')
                (carpeta / 'lider.code').write_text(
                    'import subprocess, sys, time\n'
                    "h = subprocess.Popen([sys.executable, sys.argv[1] + '/dormir.code'], start_new_session=True,\n"
                    '                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n'
                    "open(sys.argv[1] + '/hijo.pid', 'w').write(str(h.pid))\ntime.sleep(600)\n")
                lider = subprocess.Popen([sys.executable, str(carpeta / 'lider.code'), str(carpeta)],
                                         start_new_session=True)
                cuenta = []

                class Espia(subprocess.Popen):
                    def __init__(proceso, *args, **kwargs):
                        if args[0][0] == 'ps':
                            cuenta.append(1)
                            if len(cuenta) >= 2 and inyeccion == 'ps2:oserror':
                                raise OSError(5, 'ps inyectado')
                            if len(cuenta) == 2 and inyeccion == 'ps2:error':
                                raise RuntimeError('fallo inyectado en la segunda enumeración')
                            if len(cuenta) == 2 and inyeccion == 'ps2:sigint':
                                os.kill(os.getpid(), signal.SIGINT)
                        super().__init__(*args, **kwargs)
                disparado = []

                def kill_espiado(pid, senal):
                    original_kill(pid, senal)
                    if senal == signal.SIGSTOP and not disparado and inyeccion == 'stop:sigint':
                        disparado.append(True)
                        original_kill(os.getpid(), signal.SIGINT)
                manejador = signal.signal(signal.SIGINT, signal.default_int_handler)
                hijo = None
                try:
                    for _ in range(150):
                        if (carpeta / 'hijo.pid').exists() and (carpeta / 'hijo.pid').read_text().strip().isdigit():
                            break
                        threading.Event().wait(0.02)
                    hijo = int((carpeta / 'hijo.pid').read_text())
                    with mock.patch('subprocess.Popen', Espia), mock.patch('os.kill', kill_espiado):
                        if inyeccion == 'stop:sigint':
                            self.assertEqual(len(cuenta), 0)
                        with self.assertRaises(excepcion):
                            _matar_descendientes(lider.pid)
                    # ANTES de cualquier limpieza del test: el hijo registrado ya no puede estar vivo (ni congelado)
                    self.assertFalse(self._sigue_vivo(hijo), 'un descendiente registrado sobrevivió a la limpieza')
                finally:
                    signal.signal(signal.SIGINT, manejador)
                    for pid in [lider.pid] + ([hijo] if hijo else []):
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            os.kill(pid, signal.SIGKILL)
                    lider.wait(timeout=10)

    @staticmethod
    def _espia_de_ps(codigo=None, siempre=False, interrumpe=False, cierre_falla=None):
        """`(parche, lanzados, fallos)`: un `Popen` que anota los `ps` que se lanzan (el propio objeto, con su pid y su
        código: sin carreras con el arranque del guion de un `ps` sustituto que se mata antes de escribir nada). Con
        `codigo` (un `errno`), el `kill` de un `ps` falla UNA vez con él (AC285), o siempre con `siempre`; con
        `'silenciado'`, `send_signal` vuelve UNA vez sin señalar (el `ESRCH` que `Popen.send_signal` silencia con el `ps`
        aún vivo: `kill` no falla y el `ps` sigue ahí). Con `interrumpe`, `communicate` hace lo que el manejador de
        `SIGINT` de `subprocess` (AC287): mata al hijo, lo recoge (`returncode` fijado) y propaga `KeyboardInterrupt`.
        `fallos` anota cada fallo inyectado. Con `cierre_falla` (`'una vez'` o `'siempre'`), el `close` de `stdout` falla con
        `EIO` (AC287: cada tubo se cierra aislado del otro); el tubo real queda en `proceso.stdout._tubo`."""
        lanzados, fallos = [], []

        class Tubo:
            def __init__(tubo, proceso, real):
                tubo._tubo, tubo._proceso, tubo._intentos = real, proceso, 0

            def close(tubo):
                tubo._intentos += 1
                if cierre_falla == 'siempre' or tubo._intentos == 1:
                    fallos.append(tubo._proceso.pid)
                    raise OSError(errno.EIO, 'fallo inyectado en el close de stdout')
                tubo._tubo.close()

            def __getattr__(tubo, nombre):
                return getattr(tubo._tubo, nombre)

        class Espia(subprocess.Popen):
            def __init__(proceso, *args, **kwargs):
                super().__init__(*args, **kwargs)
                if args and isinstance(args[0], list) and args[0][:1] == ['ps']:
                    lanzados.append(proceso)
                    if cierre_falla:
                        proceso.stdout = Tubo(proceso, proceso.stdout)

            def kill(proceso):
                if proceso in lanzados and isinstance(codigo, int) and (siempre or not fallos):
                    fallos.append(proceso.pid)
                    raise OSError(codigo, 'fallo inyectado en el kill del ps')
                return super().kill()

            def communicate(proceso, *args, **kwargs):
                if proceso in lanzados and interrumpe:
                    os.kill(proceso.pid, signal.SIGKILL)   # sin pasar por `Popen.kill` (que puede estar parcheado)
                    super().wait(timeout=10)
                    raise KeyboardInterrupt
                return super().communicate(*args, **kwargs)

            def send_signal(proceso, numero):
                if proceso in lanzados and codigo == 'silenciado' and not fallos:
                    fallos.append(proceso.pid)
                    return   # como el `ESRCH` silenciado: sin error y sin señal
                return super().send_signal(numero)
        return mock.patch('subprocess.Popen', Espia), lanzados, fallos

    def _con_plazo(self, funcion, soltar, plazo=5):
        """AC284, AC285 (enmienda 68, 69): corre `funcion()` en un hilo y devuelve `(excepción o None, ¿seguía en pie al
        vencer el plazo?)`. Solo si se colgó llama a `soltar()` (lo que la bloquee: mata el `ps` dormido) para poder esperar
        al hilo. Un cuelgue lo decide el CONTROL con su propia aserción; no depende del vigilante ni de un límite externo,
        y lo que no se colgó no recibe ningún rescate."""
        salida = []

        def correr():
            try:
                funcion()
            except BaseException as error:   # se devuelve; el control la compara
                salida.append(error)
        hilo = threading.Thread(target=correr, daemon=True)
        self._arrancar_hilo(hilo)
        hilo.join(timeout=plazo)
        colgado = hilo.is_alive()
        if colgado:   # solo entonces se rescata: si no, lo que murió lo mató la propia función
            soltar()
        hilo.join(timeout=10)
        self.assertFalse(hilo.is_alive(), 'la función sigue bloqueada aunque se soltó lo que la bloqueaba')
        return (salida[0] if salida else None), colgado

    def _ps_sustituto(self, carpeta, cuerpo):
        """Un `ps` falso en `carpeta/bin`, el primero del `PATH` mientras dure el `with`: lo ven el padre y la sonda."""
        (carpeta / 'bin').mkdir()
        (carpeta / 'bin' / 'ps').write_text('#!/bin/sh\n' + cuerpo, encoding='utf-8')
        (carpeta / 'bin' / 'ps').chmod(0o755)
        return mock.patch.dict(os.environ, {'PATH': str(carpeta / 'bin') + os.pathsep + os.environ['PATH']})

    @lento
    def test_la_limpieza_no_da_por_limpio_un_ps_que_falla_ni_se_cuelga(self):
        """AC275 (enmienda 65, Codex 55a-2, 55b-3): un `ps` que sale con error no es «árbol limpio» (la sonda falla con
        su mensaje y el líder queda recogido, en lugar de devolver `denunciados={}` en silencio); un `ps` que se queda
        dormido tiene plazo y presupuesto: con `plazo=0.1` la función vuelve en menos de 15 s por aserción (vigilante),
        denunciando el fallo (sin pisar al plazo vencido, que sale con la denuncia en su `__context__`), y ni el `ps`
        sustituto ni el líder quedan vivos."""
        for forma in ('un ps que sale con error', 'un ps con una tabla válida pero código 1',
                      'un ps que se queda dormido'):
            with self.subTest(forma=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                self._escribir_descendientes(carpeta, cuelga=False)
                dormido = forma == 'un ps que se queda dormido'
                cuerpo = ('exit 1\n' if forma == 'un ps que sale con error' else
                          'echo "$PPID 1"\necho "$$ $PPID"\nexit 1\n' if not dormido else
                          f'echo $$ >> "{carpeta}/ps.pids"\nexec sleep 600\n')
                sustituto = self._ps_sustituto(carpeta, cuerpo)
                lideres = []

                class Espia(subprocess.Popen):
                    def __init__(proceso, *args, **kwargs):
                        super().__init__(*args, **kwargs)
                        if args[0][0] != 'ps':
                            lideres.append(proceso)

                def pids_de_ps():
                    ruta = carpeta / 'ps.pids'
                    return [int(linea) for linea in ruta.read_text().split()] if ruta.exists() else []
                try:
                    with sustituto, mock.patch('subprocess.Popen', Espia), \
                            self._vigilante(lideres, espera=15, tambien=pids_de_ps):
                        with self.assertRaises(subprocess.TimeoutExpired if dormido else RuntimeError) as visto:
                            leen_un_reloj_al_importar(carpeta, plazo=0.1 if dormido else 30)
                    if dormido:
                        self.assertTrue(self._cuelga_de(visto.exception, 'ps', RuntimeError))
                    else:
                        self.assertIn('limpi', str(visto.exception))
                    self.assertTrue(self._sin_sigint_pendiente())
                    with self.assertRaises(ChildProcessError, msg='el líder de la sonda quedó sin recoger'):
                        os.waitpid(lideres[0].pid, os.WNOHANG)
                    for pid in pids_de_ps():
                        self.assertFalse(self._sigue_vivo(pid), 'el ps sustituto sigue vivo')
                finally:   # los descendientes que ps no pudo enumerar, si los hubo
                    for pid in list(self._leer_pids(carpeta).values()) + pids_de_ps():
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            os.kill(pid, signal.SIGKILL)

    def test_la_limpieza_del_padre_no_se_interrumpe_con_sigint(self):
        """AC276 (enmienda 65, Codex 55b-2): un `SIGINT` real justo antes de `poll`, de `killpg` o de `wait` de la
        limpieza del padre se difiere hasta el final: el `KeyboardInterrupt` se entrega con el líder ya muerto y
        recogido, sin ningún descendiente vivo, sin vuelta colgada (vigilante) y con la máscara de señales
        restaurada."""
        if os.name != 'posix' or threading.current_thread() is not threading.main_thread():
            self.skipTest('AC276: sin pthread_sigmask o fuera del hilo principal no se difiere SIGINT (declarado)')
        original = subprocess.Popen.communicate
        original_killpg = os.killpg
        for objetivo in ('poll', 'killpg', 'wait'):
            with self.subTest(antes_de=objetivo), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                self._escribir_descendientes(carpeta, cuelga=True)
                lideres, armado, disparado = [], [], []

                def inyectar():
                    if armado and not disparado:
                        disparado.append(True)
                        os.kill(os.getpid(), signal.SIGINT)

                class Espia(subprocess.Popen):
                    def __init__(proceso, *args, **kwargs):
                        super().__init__(*args, **kwargs)
                        lideres.append(proceso)

                    def communicate(proceso, *args, **kwargs):
                        if proceso.args[1:2] != ['-c']:
                            return original(proceso, *args, **kwargs)
                        self._leer_pids(carpeta)
                        armado.append(True)
                        raise RuntimeError('fallo del padre mientras espera')

                    def poll(proceso):
                        if objetivo == 'poll' and proceso is lideres[0]:
                            inyectar()
                        return super().poll()

                    def wait(proceso, *args, **kwargs):
                        if objetivo == 'wait' and proceso is lideres[0]:
                            inyectar()
                        return super().wait(*args, **kwargs)

                def killpg_espiado(grupo, senal):
                    if objetivo == 'killpg':
                        inyectar()
                    return original_killpg(grupo, senal)
                llegada = []

                def al_llegar(numero, marco):   # cuándo se ENTREGA el SIGINT: con la máscara, al terminar
                    llegada.append(lideres[0].returncode)
                    raise KeyboardInterrupt
                manejador = signal.signal(signal.SIGINT, al_llegar)
                try:
                    with mock.patch('subprocess.Popen', Espia), \
                            mock.patch('os.killpg', killpg_espiado), self._vigilante(lideres):
                        with self.assertRaises(KeyboardInterrupt):
                            leen_un_reloj_al_importar(carpeta, plazo=60)
                    self.assertTrue(disparado, 'el SIGINT no llegó a inyectarse')
                    self.assertEqual(len(llegada), 1)
                    self.assertIsNotNone(llegada[0], 'el SIGINT se entregó con el líder todavía sin recoger')
                    self.assertTrue(self._sin_sigint_pendiente())
                    with self.assertRaises(ChildProcessError, msg='el líder de la sonda quedó sin recoger'):
                        os.waitpid(lideres[0].pid, os.WNOHANG)
                    pids = self._leer_pids(carpeta)
                    for nombre, pid in pids.items():
                        self.assertFalse(self._sigue_vivo(pid), f'el descendiente {nombre} sigue vivo')
                finally:
                    signal.signal(signal.SIGINT, manejador)
                    for pid in self._leer_pids(carpeta).values():
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            os.kill(pid, signal.SIGKILL)

    def test_la_prueba_dinamica_mata_al_lider_aunque_falle_el_barrido(self):
        """AC271, AC272, AC275 (enmienda 64, 65): si el barrido del padre falla (aquí `ps` no existe) el líder, ya
        congelado, se mata y se recoge igual y no queda colgado en `wait()`; el fallo se DENUNCIA (`RuntimeError`) sin
        pisar al plazo vencido (AC277): sale `TimeoutExpired` y la denuncia es su `__context__`. Un vigilante convierte un
        cuelgue en un fallo."""
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
            self._escribir_descendientes(carpeta, cuelga=True)
            lideres = []

            class Espia(subprocess.Popen):
                def __init__(proceso, *args, **kwargs):
                    if args[0][0] == 'ps':
                        raise FileNotFoundError(2, 'No existe ps', 'ps')
                    super().__init__(*args, **kwargs)
                    lideres.append(proceso)
            try:
                with mock.patch('subprocess.Popen', Espia), self._vigilante(lideres):
                    with self.assertRaises(subprocess.TimeoutExpired) as visto:
                        leen_un_reloj_al_importar(carpeta, plazo=3)
                # el fallo se DENUNCIA, no se da por limpio: cuelga de la original
                self.assertTrue(self._cuelga_de(visto.exception, 'No existe ps', RuntimeError))
                with self.assertRaises(ChildProcessError, msg='el líder de la sonda quedó sin recoger'):
                    os.waitpid(lideres[0].pid, os.WNOHANG)
                self.assertFalse(self._sigue_vivo(self._leer_pids(carpeta)['d']), 'killpg no llegó al nieto del grupo')
            finally:   # el barrido falló: los descendientes que cambiaron de grupo siguen ahí, a limpiar
                for pid in self._leer_pids(carpeta).values():
                    with contextlib.suppress(ProcessLookupError, PermissionError):
                        os.kill(pid, signal.SIGKILL)

    def test_la_prueba_dinamica_congela_a_lo_que_no_deja_de_bifurcar(self):
        """AC271 (enmienda 64), punto fijo: un descendiente (o el propio líder) que lanza procesos sin parar, cada uno
        en un grupo propio, mientras la sonda los enumera no deja huérfanos: se le CONGELA y se repite la enumeración
        hasta que una vuelta no encuentre ninguno nuevo, y solo entonces se mata a todos (con una sola vuelta, o sin
        congelar, los hijos nacidos entre la enumeración y la muerte se reparentan a `init` y siguen vivos)."""
        ficha = f'e64ficha{os.getpid()}'

        def con_la_ficha():
            for _ in range(60):
                tabla = _consultar_ps(['-axo', 'pid=,command='], 10)[2]
                pids = [int(linea.split(None, 1)[0]) for linea in tabla.splitlines()
                        if ficha in linea and 'ps -axo' not in linea]
                if not pids:
                    return []
                threading.Event().wait(0.05)
            return pids
        for forma, plazo in (('un descendiente que no deja de bifurcar (salida normal)', 60),
                             ('el líder que no deja de bifurcar (plazo vencido)', 2)):
            with self.subTest(forma=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                # a lo sumo ~30 vivos a la vez: lanza uno y mata al más viejo
                bucle = ('n = 0\nvivos = []\nwhile True:\n'
                         "    vivos.append(subprocess.Popen(['bash', '-c', 'exec -a \"$0\" sleep 600', "
                         + repr(ficha) + "],\n"
                         '                                  process_group=0, stdout=subprocess.DEVNULL,\n'
                         '                                  stderr=subprocess.DEVNULL))\n'
                         '    if len(vivos) > 30:\n'
                         '        viejo = vivos.pop(0)\n        viejo.kill()\n        viejo.wait()\n'
                         '    n += 1\n'
                         "    if n == 5:\n        open(AQUI + '/listo', 'w').write('listo')\n"
                         '    time.sleep(0.002)\n')
                cabecera = f'import os, subprocess, sys, time\nAQUI = {str(carpeta)!r}\n'
                if plazo == 60:
                    (carpeta / 'bifurca.code').write_text(
                        'import os, subprocess, sys, time\nAQUI = sys.argv[1]\n' + bucle, encoding='utf-8')
                    (carpeta / 'e64_z.py').write_text(
                        cabecera + "subprocess.Popen([sys.executable, AQUI + '/bifurca.code', AQUI], process_group=0,\n"
                        '                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n'
                        "while not os.path.exists(AQUI + '/listo'):\n    time.sleep(0.02)\n", encoding='utf-8')
                else:
                    (carpeta / 'e64_z.py').write_text(cabecera + bucle, encoding='utf-8')
                try:
                    if plazo == 60:
                        self.assertEqual(leen_un_reloj_al_importar(carpeta, plazo=plazo).denunciados, {})
                    else:
                        with self.assertRaises(subprocess.TimeoutExpired):
                            leen_un_reloj_al_importar(carpeta, plazo=plazo)
                    self.assertEqual(con_la_ficha(), [], 'quedan procesos que nacieron durante la limpieza')
                finally:
                    tabla = _consultar_ps(['-axo', 'pid=,command='], 10)[2]
                    for linea in tabla.splitlines():
                        if ficha in linea and 'ps -axo' not in linea:
                            with contextlib.suppress(ProcessLookupError, PermissionError):
                                os.kill(int(linea.split(None, 1)[0]), signal.SIGKILL)

    def test_una_tabla_de_ps_invalida_no_se_toma_por_limpia(self):
        """AC278, AC282 (enmienda 66, 67, Codex 56b-3, 57b): una enumeración de `ps` solo vale si TODAS sus líneas son dos
        enteros y contiene a la raíz; con código de salida 0 pero salida vacía, basura, un pid truncado, una línea de
        tres columnas o una tabla sin la raíz, la sonda falla (nunca «sin descendientes») y el líder queda recogido. Las
        cinco primeras no tienen la raíz (la rechaza esa exigencia); las cuatro últimas la SÍ tienen (el `ps` sustituto
        imprime `$PPID`, que es la sonda) y una línea inválida: solo las rechaza la exigencia de que TODAS valgan."""
        raiz = 'echo "$PPID 1"\n'
        tablas = (('vacía', ''), ('basura', 'esto no es una tabla\n'), ('un pid truncado', '1 0\n42\n'),
                  ('una línea de tres columnas', '1 0 0\n'), ('sin la raíz', '1 0\n2 1\n'),
                  ('con la raíz y basura', raiz + 'echo "esto no es una tabla"\n'),
                  ('con la raíz y un pid truncado', raiz + 'echo 42\n'),
                  ('con la raíz y tres columnas', raiz + 'echo "1 0 0"\n'),
                  ('con la raíz y una línea vacía interior', raiz + 'echo\necho "7 $PPID"\n'))
        for forma, tabla in tablas:
            with self.subTest(tabla=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                self._escribir_descendientes(carpeta, cuelga=False)
                cuerpo = tabla if tabla.startswith('echo') else f"printf '%s' '{tabla}'\n"
                sustituto = self._ps_sustituto(carpeta, cuerpo + 'exit 0\n')
                lideres = []

                class Espia(subprocess.Popen):
                    def __init__(proceso, *args, **kwargs):
                        super().__init__(*args, **kwargs)
                        if args[0][0] != 'ps':
                            lideres.append(proceso)
                try:
                    with sustituto, mock.patch('subprocess.Popen', Espia), self._vigilante(lideres, espera=30):
                        with self.assertRaises(RuntimeError) as visto:
                            leen_un_reloj_al_importar(carpeta, plazo=30)
                    self.assertIn('sin limpiar', str(visto.exception))
                    with self.assertRaises(ChildProcessError, msg='el líder de la sonda quedó sin recoger'):
                        os.waitpid(lideres[0].pid, os.WNOHANG)
                finally:   # lo que ps no pudo enumerar, si lo hubo
                    for pid in self._leer_pids(carpeta).values():
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            os.kill(pid, signal.SIGKILL)

    def test_la_limpieza_no_se_cuelga_si_el_lider_no_muere(self):
        """AC277 (enmienda 66): un fallo PERSISTENTE (`killpg` y `kill` del líder fallan siempre) se denuncia tras
        intentar todo lo demás y sin colgarse (`wait` con plazo, vigilante): se barren los descendientes, no queda
        ninguna espera sin plazo, y la máscara de señales queda restaurada aunque la limpieza falle."""
        if os.name != 'posix':
            self.skipTest('AC277: sin pthread_sigmask no se puede comprobar la máscara (declarado)')
        original_killpg, original_kill = os.killpg, subprocess.Popen.kill
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
            lider, pids = self._escenario_de_procesos(carpeta)
            lideres = [lider]

            def no_muere_killpg(grupo, senal):
                if grupo == lider.pid:
                    raise OSError(5, 'killpg inyectado')
                return original_killpg(grupo, senal)

            def no_muere_kill(proceso, *args, **kwargs):
                if proceso is lider:
                    raise OSError(5, 'kill inyectado')
                return original_kill(proceso, *args, **kwargs)
            try:
                with mock.patch('os.killpg', no_muere_killpg), \
                        mock.patch('subprocess.Popen.kill', no_muere_kill), \
                        self._vigilante(lideres, espera=15):
                    with self.assertRaises((OSError, RuntimeError)):
                        _recoger_lider(lider)
                self.assertTrue(self._sin_sigint_pendiente())
                for nombre in 'abc':
                    self.assertFalse(self._sigue_vivo(pids[nombre]), f'el descendiente {nombre} sigue vivo')
            finally:
                self._matar_todo(lider, pids)

    @lento
    def test_la_limpieza_por_el_camino_real_conserva_la_excepcion_original_y_no_se_cuelga(self):
        """AC277 (enmienda 66, 57ª): por `leen_un_reloj_al_importar`, con un módulo colgado y el plazo vencido, un fallo
        de la limpieza (el primer `SIGKILL` a un descendiente, una vez) no pisa a la excepción original
        (`TimeoutExpired`): queda en su `__context__`, y todo lo registrado está muerto y el líder recogido; y un fallo
        PERSISTENTE (`killpg` y `kill` del líder fallan siempre) tampoco la pisa ni cuelga la llamada (`Popen.__exit__`
        esperaría al líder congelado sin plazo): el vigilante solo actúa si se cuelga."""
        original_kill, original_killpg, original_popen_kill = os.kill, os.killpg, subprocess.Popen.kill
        for forma in ('un fallo único', 'un fallo persistente'):
            with self.subTest(forma=forma), tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                shutil.copy2(TESTS / '_vigilancia.py', carpeta / '_vigilancia.py')
                self._escribir_descendientes(carpeta, cuelga=True)
                lideres, disparado = [], []

                class Espia(subprocess.Popen):
                    def __init__(proceso, *args, **kwargs):
                        super().__init__(*args, **kwargs)
                        lideres.append(proceso)

                def kill(pid, senal):   # el primer SIGKILL a algo que no es el líder (un descendiente registrado)
                    if (forma == 'un fallo único' and senal == signal.SIGKILL and not disparado and lideres
                            and pid != lideres[0].pid):
                        disparado.append(pid)
                        raise OSError(5, 'fallo inyectado en un SIGKILL')
                    return original_kill(pid, senal)

                def killpg(grupo, senal):
                    if forma == 'un fallo persistente':
                        raise OSError(5, 'fallo inyectado en killpg')
                    return original_killpg(grupo, senal)

                def matar_lider(proceso, *args, **kwargs):
                    if forma == 'un fallo persistente' and lideres and proceso is lideres[0]:
                        raise OSError(5, 'fallo inyectado en kill')
                    return original_popen_kill(proceso, *args, **kwargs)
                try:
                    with mock.patch('subprocess.Popen', Espia), mock.patch('os.kill', kill), \
                            mock.patch('os.killpg', killpg), mock.patch.object(Espia, 'kill', matar_lider), \
                            self._vigilante(lideres, espera=20):
                        try:
                            leen_un_reloj_al_importar(carpeta, plazo=3)
                            capturada = None
                        except BaseException as error:   # la excepción que sale se COMPARA: sea cual sea, es una aserción
                            capturada = error
                    self.assertIs(type(capturada), subprocess.TimeoutExpired, f'salió {capturada!r}')
                    self.assertTrue(self._cuelga_de(capturada, 'fallo inyectado'),
                                    'el fallo de la limpieza no cuelga de la excepción original')
                    pids = self._leer_pids(carpeta)
                    self.assertEqual(sorted(pids), ['a', 'b', 'c', 'd'])
                    for nombre in 'abc' if forma == 'un fallo persistente' else 'abcd':   # `d` solo muere por `killpg`
                        self.assertFalse(self._sigue_vivo(pids[nombre]), f'el descendiente {nombre} sigue vivo')
                    if forma == 'un fallo único':
                        with self.assertRaises(ChildProcessError, msg='el líder de la sonda quedó sin recoger'):
                            os.waitpid(lideres[0].pid, os.WNOHANG)
                finally:   # el líder de un fallo persistente sigue congelado: la limpieza del propio control
                    for pid in [lider.pid for lider in lideres] + list(self._leer_pids(carpeta).values()):
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            original_kill(pid, signal.SIGKILL)
                    for lider in lideres:
                        with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):
                            lider.wait(timeout=5)

    @staticmethod
    def _matar_todo(lider, pids):
        """Limpieza AUXILIAR del propio control (siempre después de las comprobaciones)."""
        for pid in [lider.pid] + list(pids.values()):
            with contextlib.suppress(ProcessLookupError, PermissionError):
                os.kill(pid, signal.SIGKILL)
        with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):   # recoge a un líder recién matado
            lider.wait(timeout=10)

    def _escenario_de_procesos(self, carpeta):
        """Un líder real en sesión propia con cuatro descendientes: a (`process_group=0`), b (sesión propia) y su hijo
        c, y d (nieto huérfano por doble `fork` que sigue en el grupo del líder). Devuelve `(líder, {a, b, c, d:
        pid})`. El líder publica `d.pid` SOLO tras recoger al hijo intermedio del doble `fork`: mientras ese hijo vive
        o es un zombi, cuelga del líder por `ppid` (y `d` de él), el barrido encuentra un descendiente de más y las
        posiciones de la inyección se desplazan según el planificador."""
        (carpeta / 'lider.code').write_text(
            'import os, subprocess, sys, time\n'
            'AQUI = sys.argv[1]\n'
            'nulo = dict(stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)\n'
            "a = subprocess.Popen(['sleep', '6007'], process_group=0, **nulo)\n"
            "open(AQUI + '/a.pid', 'w').write(str(a.pid))\n"
            "b = subprocess.Popen(['sh', '-c', 'sleep 6007 & echo $! > \"$0/c.pid\"; wait', AQUI],\n"
            "                     start_new_session=True, **nulo)\n"
            "open(AQUI + '/b.pid', 'w').write(str(b.pid))\n"
            'if os.fork() == 0:\n'
            '    if os.fork() == 0:\n'
            '        nulo = os.open(os.devnull, os.O_RDWR)\n'
            '        os.dup2(nulo, 1)\n        os.dup2(nulo, 2)\n'
            "        open(AQUI + '/d.nieto', 'w').write(str(os.getpid()))\n"
            "        os.execvp('sleep', ['sleep', '6007'])\n"
            '    os._exit(0)\n'
            'os.wait()\n'
            "while not (os.path.exists(AQUI + '/d.nieto') and open(AQUI + '/d.nieto').read().strip().isdigit()):\n"
            '    time.sleep(0.02)\n'
            "os.replace(AQUI + '/d.nieto', AQUI + '/d.pid')\n"
            'time.sleep(600)\n', encoding='utf-8')
        lider = subprocess.Popen([sys.executable, str(carpeta / 'lider.code'), str(carpeta)], start_new_session=True)
        pids = self._leer_pids(carpeta)
        self.assertEqual(sorted(pids), ['a', 'b', 'c', 'd'], 'el escenario no arrancó')
        return lider, pids

    # Las llamadas de la limpieza en una corrida SANA, por modo (AC279, AC281): si una limpieza gana o pierde un paso,
    # este número cambia y el control salta hasta que se decida cómo se comporta ese paso ante un fallo. Se cuentan los
    # pasos LÓGICOS: las llamadas que hace el propio `subprocess` por dentro (el `poll` y el `os.kill` de `Popen.kill`, el
    # `wait` de `communicate`) existen según el planificador y no son posiciones. El modo `directo` es la limpieza de la
    # sonda: no mata ni recoge al líder, así que no tiene ramas.
    POSICIONES_DEL_BARRIDO = {'padre': 20, 'padre sin máscara': 18, 'directo': 11}
    MODOS_DEL_BARRIDO = (('padre', 'recogido'), ('padre', 'pendiente'), ('padre sin máscara', 'pendiente'),
                         ('directo', None))
    # AC283: las llamadas de señal, donde se inyectan además `EPERM` y `ESRCH` únicos (en las demás no tienen sentido)
    SENALES_DEL_BARRIDO = {'kill', 'killpg', 'Popen.kill'}
    ERRNOS_DEL_BARRIDO = {'oserror': errno.EIO, 'eperm': errno.EPERM, 'esrch': errno.ESRCH}
    CorridaDelBarrido = collections.namedtuple('CorridaDelBarrido',
                                               'llamadas excepcion vivos mascara_libre disparado rama')

    @classmethod
    def _esperar_zombi(cls, pid, vueltas=100, plazo=2):
        """Hasta que `pid`, hijo nuestro, haya muerto y NO se haya recogido (estado `Z`): así el `poll` de `Popen.kill` lo
        recoge. Con `ps`, no con `os.waitid` (no existe en macOS con CPython 3.12). AC284: cada `ps` tiene plazo
        (`_estado_de`) y el presupuesto total se cuenta (`vueltas` × `plazo`), no se mide con un reloj."""
        for _ in range(vueltas):
            estado = cls._estado_de(pid, plazo)
            if not estado or estado.startswith('Z'):
                return
            time.sleep(0.01)
        raise AssertionError(f'el líder {pid} no murió tras el killpg')

    def _corrida_del_barrido(self, modo, rama=None, falla=None, cesion=0):
        """Una corrida de la limpieza con un líder y descendientes reales en sesión propia y los pasos de la limpieza
        (`os.kill`, `os.killpg`, `pthread_sigmask`, `signal.signal`, `threading.current_thread` y `main_thread`,
        `warnings.warn`, `Timer.start` y `cancel`, y `Popen.__init__` de `ps`, `communicate`, `kill`, `wait` y `poll`)
        contados SI los llama la limpieza y no el propio `subprocess`. `modo`: `padre` (`_recoger_lider` con el plazo vencido en vuelo, como el
        camino real), `padre sin máscara` (el hilo no es el principal: se avisa) y `directo` (la de la sonda). `rama`
        fuerza al líder tras el `killpg`, cuando ya es un zombi: `recogido` (el `poll` de `Popen.kill` lo recoge) o
        `pendiente` (ese `poll` no lo ve y lo recoge el `wait`); `cesion` cede esos segundos tras el `killpg`.
        `falla=(k, clase)` hace fallar la k-ésima UNA vez: `'oserror'` (`EIO` transitorio), `'eperm'`, `'esrch'` o
        `'sigint'` (un `SIGINT` real al propio proceso). Las comprobaciones se hacen ANTES de cualquier limpieza
        auxiliar del propio control."""
        llamadas, disparado, paradas, armado, visto, matado, suspendido = [], [], set(), [], [], [], []
        originales = {'kill': os.kill, 'killpg': os.killpg, 'pthread_sigmask': signal.pthread_sigmask,
                      'signal': signal.signal, 'threading.current_thread': threading.current_thread,
                      'threading.main_thread': threading.main_thread, 'warnings.warn': warnings.warn,
                      'Timer.start': threading.Timer.start, 'Timer.cancel': threading.Timer.cancel,
                      'Popen.__init__': subprocess.Popen.__init__, 'Popen.communicate': subprocess.Popen.communicate,
                      'Popen.kill': subprocess.Popen.kill, 'Popen.wait': subprocess.Popen.wait,
                      'Popen.poll': subprocess.Popen.poll}
        ajeno = object()   # en `padre sin máscara`, «el hilo actual» no es el principal

        def contar(nombre, ps=False):
            if not armado or suspendido:   # suspendido: la espera del zombi es del control, no un paso de la limpieza
                return
            llamadas.append(f'{nombre}{"(ps)" if ps else ""}')
            if falla and len(llamadas) == falla[0] and not disparado:
                disparado.append(len(llamadas))
                if falla[1] != 'sigint':
                    raise OSError(self.ERRNOS_DEL_BARRIDO[falla[1]], 'fallo inyectado')
                originales['kill'](os.getpid(), signal.SIGINT)

        def llama(modulo):   # ¿la espía que me llama la llama `modulo`, y no otro?
            return sys._getframe(2).f_globals.get('__name__') == modulo

        def funcion(nombre):
            def espiada(*args, **kwargs):
                if not llama('subprocess'):
                    if nombre == 'kill' and len(args) > 1 and args[1] == signal.SIGSTOP and armado:
                        paradas.add(args[0])
                    contar(nombre)
                resultado = originales[nombre](*args, **kwargs)
                if nombre == 'killpg' and armado:
                    matado.append(True)
                    if rama:   # el líder YA ha muerto: la rama la decide solo el `poll` de `Popen.kill`
                        suspendido.append(True)
                        try:
                            self._esperar_zombi(lider.pid)
                        finally:
                            suspendido.clear()
                    if cesion:
                        time.sleep(cesion)
                return resultado
            return espiada

        def del_modulo(nombre):   # `threading` y `warnings` los usan todos: solo cuentan los pasos de la limpieza
            def espiada(*args, **kwargs):
                if armado and llama(__name__):
                    contar(nombre)
                    if nombre == 'threading.current_thread' and modo == 'padre sin máscara':
                        return ajeno
                    if nombre == 'warnings.warn':
                        with warnings.catch_warnings():
                            warnings.simplefilter('ignore')
                            return originales[nombre](*args, **kwargs)
                return originales[nombre](*args, **kwargs)
            return espiada

        def metodo(nombre):
            def espiado(proceso, *args, **kwargs):
                interna = llama('subprocess')
                if nombre == 'Popen.poll' and interna and proceso is lider and matado and armado:
                    # el `poll` de `Popen.kill` tras el `killpg`: es el que decide la rama del líder
                    recogido = None if rama == 'pendiente' and not visto else originales[nombre](proceso, *args)
                    visto.append('pendiente' if recogido is None else 'recogido')
                    return recogido
                if not interna:
                    orden = args[0] if nombre == 'Popen.__init__' and args else getattr(proceso, 'args', None)
                    contar(nombre, isinstance(proceso, subprocess.Popen) and isinstance(orden, list)
                           and orden[:1] == ['ps'])
                return originales[nombre](proceso, *args, **kwargs)
            return espiado
        manejador = signal.signal(signal.SIGINT, signal.default_int_handler)
        mascara_inicial = signal.pthread_sigmask(signal.SIG_BLOCK, set())
        excepcion, resultado = None, []
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            lider, pids = self._escenario_de_procesos(carpeta)
            try:
                parches = [mock.patch('os.kill', funcion('kill')),
                           mock.patch('os.killpg', funcion('killpg')),
                           mock.patch('signal.pthread_sigmask', funcion('pthread_sigmask')),
                           mock.patch('signal.signal', funcion('signal'))]
                parches += [mock.patch('threading.current_thread', del_modulo('threading.current_thread')),
                            mock.patch('threading.main_thread', del_modulo('threading.main_thread')),
                            mock.patch.object(warnings, 'warn', del_modulo('warnings.warn'))]
                parches += [mock.patch(f'threading.Timer.{nombre}', metodo(f'Timer.{nombre}'))
                            for nombre in ('start', 'cancel')]   # ya no hay temporizador: si vuelve, salta el recuento
                parches += [mock.patch(f'subprocess.Popen.{nombre}', metodo(f'Popen.{nombre}'))
                            for nombre in ('__init__', 'communicate', 'kill', 'wait', 'poll')]
                with contextlib.ExitStack() as pila:
                    for parche in parches:
                        pila.enter_context(parche)
                    pila.enter_context(self._vigilante([lider], espera=4))
                    armado.append(True)
                    try:
                        if modo != 'directo':   # como `leen_un_reloj_al_importar`: la limpieza en un `finally`, con una
                            try:                # excepción en vuelo (el plazo vencido) que no debe pisarse
                                raise subprocess.TimeoutExpired('importar', 1)
                            finally:
                                _recoger_lider(lider)
                        else:   # lo que hace la sonda: la limpieza aislada y reintentada, y el primer fallo, al final
                            fallos = _limpiar([lambda: _matar_descendientes(lider.pid, congelar_raiz=True)])
                            if fallos:
                                raise fallos[0]
                    except BaseException as error:   # la excepción esperada se compara fuera
                        excepcion = error
                    armado.clear()
                # ANTES de cualquier limpieza auxiliar: lo registrado (o todo, en el padre, que reintenta) está muerto
                candidatos = {nombre: pid for nombre, pid in pids.items() if pid in paradas or modo != 'directo'}
                siguen = self._siguen_vivos(candidatos.values())
                vivos = [nombre for nombre, pid in candidatos.items() if pid in siguen]
                if modo != 'directo':
                    try:
                        os.waitpid(lider.pid, os.WNOHANG)
                        vivos.append('líder sin recoger')
                    except ChildProcessError:
                        pass
                resultado = (vivos, self._sin_sigint_pendiente())
            finally:
                signal.signal(signal.SIGINT, manejador)
                signal.pthread_sigmask(signal.SIG_SETMASK, mascara_inicial)   # una corrida no contamina la siguiente
                self._matar_todo(lider, pids)
        return self.CorridaDelBarrido(llamadas, excepcion, *resultado, bool(disparado), visto[0] if visto else None)

    @staticmethod
    def _esperada_en_el_barrido(modo, clase, etiqueta):
        """`(excepción, ¿cuelga de su cadena el fallo inyectado?)` que debe salir de la limpieza si la llamada `etiqueta`
        falla una vez. Un `SIGINT` real sale siempre (un Ctrl-C pendiente se entrega). Un `OSError` transitorio de una
        enumeración de `ps` se repite dentro del bucle y se cura. En el padre hay una excepción en vuelo (el plazo
        vencido), como en el camino real: prevalece, y el fallo no curado cuelga de su `__context__` (AC277). Un `EPERM` o
        un `ESRCH` sobre un proceso VIVO sube igual que un `EIO` (se reintenta); sobre el líder ya muerto (el `kill` que
        sigue al `killpg`, cuando es un zombi) se acepta como muerte (AC283): sin error propio y sin reintento."""
        if clase == 'sigint':
            return KeyboardInterrupt, False
        if clase in ('eperm', 'esrch') and etiqueta == 'Popen.kill':
            return subprocess.TimeoutExpired, False
        curado = etiqueta.endswith('(ps)')
        if modo != 'directo':
            return subprocess.TimeoutExpired, not curado
        return (None if curado else OSError), False

    @staticmethod
    def _cuelga_de(error, texto, tipo=OSError):
        """Algún eslabón de la cadena `__context__`/`__cause__` de `error` es un `tipo` cuyo mensaje lleva `texto`."""
        pendientes, vistos = [error], set()
        while pendientes:
            actual = pendientes.pop()
            if actual is None or id(actual) in vistos:
                continue
            vistos.add(id(actual))
            if isinstance(actual, tipo) and texto in str(actual):
                return True
            pendientes += [actual.__context__, actual.__cause__]
        return False

    def _problemas_del_barrido(self, modo, rama, posicion, clase, etiqueta):
        """Los problemas de la limpieza cuando la llamada `etiqueta`, la `posicion`-ésima, falla una vez (`clase`)."""
        corrida = self._corrida_del_barrido(modo, rama, (posicion, clase))
        esperada, encadenada = self._esperada_en_el_barrido(modo, clase, etiqueta)
        problemas = []
        if not corrida.disparado:   # AC281: una posición que ya no existe no inyecta nada: no vale como prueba
            problemas.append('la inyección no se disparó: la corrida no llegó a esa posición')
        if corrida.vivos:
            problemas.append(f'queda algo vivo, congelado o sin recoger: {corrida.vivos}')
        if modo != 'directo' and not corrida.mascara_libre:
            problemas.append('SIGINT quedó bloqueado')
        if esperada is None and corrida.excepcion is not None or (
                esperada is not None and not isinstance(corrida.excepcion, esperada)):
            problemas.append(f'salió {corrida.excepcion!r} y se esperaba {esperada and esperada.__name__}')
        elif encadenada and not self._cuelga_de(corrida.excepcion, 'fallo inyectado'):
            problemas.append(f'el fallo inyectado no cuelga de {corrida.excepcion!r}')
        if clase in ('eperm', 'esrch') and etiqueta == 'Popen.kill' and corrida.llamadas.count('Popen.kill') != 1:
            problemas.append('un error sobre un líder ya muerto se reintentó (o se denunció)')
        return problemas

    @lento
    def test_la_limpieza_cumple_su_invariante_ante_cualquier_fallo_unico(self):
        """AC279, AC280, AC281, AC283 (enmienda 66 a 68): inyección SISTEMÁTICA de fallos. Se cuentan los pasos de la
        limpieza en una corrida sana y, para cada posición y para cada clase (`EIO` transitorio, un `SIGINT` real y, en
        las llamadas de señal, `EPERM` y `ESRCH`), se hace fallar esa llamada una vez con un líder y descendientes
        reales en sesión propia: la limpieza del padre (con el líder ya recogido por el `poll` de `Popen.kill` y con el
        líder pendiente del `wait`, forzados a propósito; y sin poder diferir `SIGINT`, que avisa) y la del barrido
        directo, que es la de la sonda. Todo lo registrado está muerto, el líder muerto y recogido, sin cuelgue ni
        máscara bloqueada, y sale la excepción esperada: en el padre, que limpia con el plazo vencido en vuelo como el
        camino real, esa original (con el fallo inyectado en su `__context__`) o un `KeyboardInterrupt` de la limpieza.
        El recuento de posiciones está fijado: un paso nuevo obliga a decidir su control; y una inyección que no llega
        a dispararse es un fallo del control."""
        if os.name != 'posix' or threading.current_thread() is not threading.main_thread():
            self.skipTest('AC279: sin pthread_sigmask o fuera del hilo principal no se puede barrer (declarado)')
        malos = []
        for modo, rama in self.MODOS_DEL_BARRIDO:
            sana = self._corrida_del_barrido(modo, rama)
            with self.subTest(modo=modo, rama=rama, corrida='sana'):
                if modo != 'directo':   # la excepción en vuelo (el plazo vencido) sale intacta
                    self.assertIs(type(sana.excepcion), subprocess.TimeoutExpired)
                else:
                    self.assertIsNone(sana.excepcion)
                self.assertEqual((sana.vivos, sana.mascara_libre), ([], True))
                self.assertEqual(sana.rama, rama, 'la rama del líder no se forzó')
                self.assertEqual(len(sana.llamadas), self.POSICIONES_DEL_BARRIDO[modo], f'{sana.llamadas}')
                self.assertEqual('threading.current_thread' in sana.llamadas, modo != 'directo')
                # el aviso de AC276 solo está en el camino sin máscara, y entonces no se toca la máscara
                self.assertEqual('warnings.warn' in sana.llamadas, modo == 'padre sin máscara')
                self.assertEqual('pthread_sigmask' in sana.llamadas, modo == 'padre')
            for posicion in range(1, len(sana.llamadas) + 1):
                for clase in ('oserror', 'sigint', 'eperm', 'esrch'):
                    etiqueta = sana.llamadas[posicion - 1]
                    if len(malos) >= 2:   # con dos fallos ya está dicho: no se espera a los demás cuelgues
                        break
                    if clase in ('eperm', 'esrch') and etiqueta not in self.SENALES_DEL_BARRIDO:
                        continue
                    problemas = self._problemas_del_barrido(modo, rama, posicion, clase, etiqueta)
                    if problemas:
                        malos.append(f'{modo}/{rama} #{posicion} {etiqueta} {clase}: ' + '; '.join(problemas))
        with self.subTest(corrida='barrido'):
            self.assertEqual(malos, [])

    def test_el_aviso_de_no_poder_diferir_sigint_sale_una_vez_aunque_sea_un_error_y_apunta_a_quien_limpia(self):
        """AC276, AC280 (enmienda 65, 67): sin poder diferir `SIGINT` (el hilo no es el principal) se avisa UNA vez, desde
        la limpieza y apuntando a quien llama, y con `-W error` (el aviso es una excepción y la pasada se repite) no se
        repite el aviso, se relanza el error, y el líder queda muerto y recogido."""
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            lider, pids = self._escenario_de_procesos(carpeta)
            avisos, ajeno, original = [], object(), warnings.warn
            def contar_aviso(*args, **kwargs):
                avisos.append(args[0])
                kwargs['stacklevel'] += 1   # esta espía es un marco más
                return original(*args, **kwargs)
            try:
                with mock.patch('threading.current_thread', lambda: ajeno), \
                        mock.patch.object(warnings, 'warn', contar_aviso), warnings.catch_warnings(record=True) as vistos:
                    warnings.simplefilter('always')
                    linea = inspect.currentframe().f_lineno + 1
                    _recoger_lider(lider)
                self.assertEqual(len(avisos), 1)
                self.assertEqual((vistos[0].filename, vistos[0].lineno), (__file__, linea))
                self.assertFalse(self._sigue_vivo(lider.pid) or self._sigue_vivo(pids['a']))
            finally:
                self._matar_todo(lider, pids)
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            lider, pids = self._escenario_de_procesos(carpeta)
            avisos = []
            try:
                with mock.patch('threading.current_thread', lambda: ajeno), \
                        mock.patch.object(warnings, 'warn', contar_aviso), warnings.catch_warnings():
                    warnings.simplefilter('error')
                    with self.assertRaises(UserWarning):
                        _recoger_lider(lider)
                self.assertEqual(len(avisos), 1)
                with self.assertRaises(ChildProcessError, msg='el líder quedó sin recoger'):
                    os.waitpid(lider.pid, os.WNOHANG)
                self.assertFalse(self._sigue_vivo(pids['a']))
            finally:
                self._matar_todo(lider, pids)

    def test_el_barrido_da_el_mismo_recuento_con_cualquier_planificacion_y_denuncia_lo_que_no_dispara(self):
        """AC281 (enmienda 67, Codex 57b-1, 57c-1): los pasos de la limpieza del padre son los MISMOS con el líder
        recogido por el `poll` de `Popen.kill`, con el líder pendiente del `wait`, y con y sin una cesión de 2 ms tras el
        `killpg` (cuando el líder muere antes de que `Popen.kill` mire, que era lo que hacía salir 22 en vez de 24); y
        cada rama forzada se ve de verdad. Una inyección en una posición que no existe se denuncia."""
        if os.name != 'posix' or threading.current_thread() is not threading.main_thread():
            self.skipTest('AC281: sin pthread_sigmask o fuera del hilo principal no se puede barrer (declarado)')
        corridas = {'libre': self._corrida_del_barrido('padre'),
                    'con cesión': self._corrida_del_barrido('padre', cesion=0.002),
                    'recogido': self._corrida_del_barrido('padre', 'recogido'),
                    'pendiente': self._corrida_del_barrido('padre', 'pendiente')}
        for nombre, corrida in corridas.items():
            with self.subTest(corrida=nombre):
                self.assertEqual(corrida.llamadas, corridas['pendiente'].llamadas)
                self.assertEqual(len(corrida.llamadas), self.POSICIONES_DEL_BARRIDO['padre'])
                self.assertEqual((corrida.vivos, corrida.mascara_libre), ([], True))
        self.assertEqual(corridas['recogido'].rama, 'recogido')
        self.assertEqual(corridas['pendiente'].rama, 'pendiente')
        # una posición que no existe no inyecta nada: el control lo denuncia (no pasa en silencio)
        problemas = self._problemas_del_barrido('padre', 'pendiente', self.POSICIONES_DEL_BARRIDO['padre'] + 1,
                                                'oserror', 'inexistente')
        self.assertTrue(any('no se disparó' in problema for problema in problemas), problemas)

    def test_una_senal_fallida_solo_se_toma_por_muerte_si_se_comprueba(self):
        """AC283 (enmienda 68, Codex 58a-1): `_senalar` acepta un `ProcessLookupError` o un `PermissionError` (`ESRCH`,
        `EPERM`) como «ya murió» SOLO si `ps` dice que el pid ya no existe o es un zombi (el caso de macOS). Un proceso
        VIVO, o un `ps` que falla o que no vuelve en su plazo, deja subir el error (el `ps` bloqueado muerto y recogido)."""
        original = os.kill
        vivo = subprocess.Popen(['sleep', '6007'])
        recogido = subprocess.Popen(['sleep', '6007'])
        recogido.kill()
        recogido.wait(timeout=10)
        zombi = subprocess.Popen(['sh', '-c', 'exit 0'])
        lanzados = []   # los `ps` bloqueados que se lanzaron, para limpiar aunque el control falle

        def sin_error(pid, que):   # un error aquí es un fallo del control, no un error del test
            try:
                _senalar(pid, signal.SIGKILL)
            except OSError as error:
                self.fail(f'{que}: se tomó por vivo ({error!r})')

        def fallo(objetivo, codigo):   # solo el objetivo falla: `subprocess.run` mata a su `ps` con el `os.kill` de verdad
            def kill(pid, numero):
                if pid == objetivo:
                    raise OSError(codigo, 'fallo inyectado')
                return original(pid, numero)
            return mock.patch('os.kill', kill)
        try:
            self._esperar_zombi(zombi.pid)
            for codigo, clase in ((errno.EPERM, PermissionError), (errno.ESRCH, ProcessLookupError)):
                with self.subTest(errno=errno.errorcode[codigo]):
                    with fallo(recogido.pid, codigo):
                        sin_error(recogido.pid, 'un pid ya recogido no existe: es una muerte')
                    with fallo(zombi.pid, codigo):
                        sin_error(zombi.pid, 'un zombi (macOS) cuenta como muerto')
                    with fallo(vivo.pid, codigo), self.assertRaises(clase):
                        _senalar(vivo.pid, signal.SIGKILL)
            with tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                with self.subTest(ps='roto'), self._ps_sustituto(carpeta, 'exit 3\n'):   # no puede decirlo: no es «muerto»
                    for objetivo in (vivo.pid, recogido.pid):
                        with fallo(objetivo, errno.EPERM), self.assertRaises(PermissionError):
                            _senalar(objetivo, signal.SIGKILL)
            with tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                espia, lanzados, _ = self._espia_de_ps()

                def matar_los_ps():
                    for ps in lanzados:
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            original(ps.pid, signal.SIGKILL)
                with self.subTest(ps='bloqueado'), self._ps_sustituto(carpeta, 'exec sleep 600\n'), espia, \
                        fallo(vivo.pid, errno.EPERM):
                    error, colgado = self._con_plazo(lambda: _senalar(vivo.pid, signal.SIGKILL, plazo_ps=0.3),
                                                     matar_los_ps)
                self.assertFalse(colgado, '_senalar sigue esperando a un ps bloqueado: sin plazo propio')
                self.assertIsInstance(error, subprocess.TimeoutExpired)
                self.assertEqual(len(lanzados), 1)
                self.assertIsNotNone(lanzados[0].returncode, 'el ps bloqueado quedó sin recoger')
                self.assertFalse(self._sigue_vivo(lanzados[0].pid), 'el ps bloqueado quedó vivo')
            with tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                with self.subTest(ps='con error'), self._ps_sustituto(
                        carpeta, "echo 'ps: error' >&2\nexit 1\n"), fallo(vivo.pid, errno.EPERM), \
                        self.assertRaises(PermissionError):   # sale con 1, como cuando no hay pid, pero con un error
                    _senalar(vivo.pid, signal.SIGKILL)
        finally:
            for proceso in (vivo, zombi, recogido):
                with contextlib.suppress(ProcessLookupError, PermissionError):
                    original(proceso.pid, signal.SIGKILL)
                with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):
                    proceso.wait(timeout=10)
            for ps in lanzados:
                with contextlib.suppress(ProcessLookupError, PermissionError):
                    original(ps.pid, signal.SIGKILL)

    def test_un_descendiente_zombi_con_un_error_de_senal_no_se_reintenta_ni_se_denuncia(self):
        """AC283 (enmienda 68), el control del zombi de macOS: un descendiente que ya murió y nadie ha recogido (está en la
        tabla de `ps`) cuyas señales dan `EPERM` no hace fallar a `_matar_descendientes`, y solo se le señala una vez cada
        vez (congelar, matar): sin reintento. El descendiente vivo muere."""
        original = os.kill
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            (carpeta / 'lider.code').write_text(
                'import os, subprocess, sys, time\n'
                'AQUI = sys.argv[1]\n'
                'zombi = os.fork()\n'
                'if zombi == 0:\n    os._exit(0)\n'   # muere y este proceso no lo recoge: un zombi
                "open(AQUI + '/z.pid', 'w').write(str(zombi))\n"
                "vivo = subprocess.Popen(['sleep', '6007'])\n"
                "open(AQUI + '/v.pid', 'w').write(str(vivo.pid))\n"
                'time.sleep(600)\n', encoding='utf-8')
            pids = {}
            lider = subprocess.Popen([sys.executable, str(carpeta / 'lider.code'), str(carpeta)])
            try:
                for nombre in 'zv':
                    for _ in range(300):
                        ruta = carpeta / f'{nombre}.pid'
                        if ruta.exists() and ruta.read_text().strip().isdigit():
                            pids[nombre] = int(ruta.read_text())
                            break
                        threading.Event().wait(0.02)
                self.assertEqual(sorted(pids), ['v', 'z'], 'el escenario no arrancó')
                self._esperar_zombi(pids['z'])
                enviadas = []

                def kill(pid, numero):
                    enviadas.append((pid, numero))
                    if pid == pids['z']:
                        raise PermissionError(errno.EPERM, 'fallo inyectado: macOS da EPERM a un zombi')
                    return original(pid, numero)
                registrados = []
                with mock.patch('os.kill', kill), self._vigilante([lider], espera=20):
                    try:
                        registrados = _matar_descendientes(lider.pid)
                    except OSError as error:
                        self.fail(f'el zombi se tomó por vivo: {error!r}')
                self.assertEqual(sorted(registrados), sorted(pids.values()))
                self.assertEqual([numero for pid, numero in enviadas if pid == pids['z']],
                                 [signal.SIGSTOP, signal.SIGKILL], 'al zombi se le señaló más (o menos) de una vez cada vez')
                self.assertFalse(self._sigue_vivo(pids['v']), 'el descendiente vivo no murió')
            finally:
                for pid in [lider.pid] + list(pids.values()):
                    with contextlib.suppress(ProcessLookupError, PermissionError):
                        original(pid, signal.SIGKILL)
                with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):
                    lider.wait(timeout=10)

    def test_esperar_zombi_con_un_ps_bloqueado_falla_por_su_asercion_propia_y_no_deja_residuos(self):
        """AC284 (enmienda 68, Codex 58b-1, 58c-1): `_esperar_zombi` no depende del vigilante ni de un límite externo. Con un
        `ps` sustituto que duerme más que el plazo, falla con su propia `AssertionError` al primer plazo vencido (un solo
        `ps` lanzado, no uno por vuelta) y ese `ps` queda muerto y recogido."""
        with tempfile.TemporaryDirectory() as directorio:
            carpeta = Path(directorio).resolve()
            espia, lanzados, _ = self._espia_de_ps()

            def matar_los_ps():
                for ps in lanzados:
                    with contextlib.suppress(ProcessLookupError, PermissionError):
                        os.kill(ps.pid, signal.SIGKILL)
            try:
                with self._ps_sustituto(carpeta, 'exec sleep 600\n'), espia:
                    error, colgado = self._con_plazo(lambda: self._esperar_zombi(os.getpid(), vueltas=5, plazo=0.3),
                                                     matar_los_ps)
                self.assertFalse(colgado, '_esperar_zombi sigue esperando a un ps bloqueado: sin plazo propio')
                self.assertIsInstance(error, AssertionError)
                self.assertIn('no volvió', str(error))
                self.assertEqual(len(lanzados), 1, 'se lanzó más de un ps: el plazo vencido no corta')
                self.assertIsNotNone(lanzados[0].returncode, 'el ps bloqueado quedó sin recoger')
                self.assertFalse(self._sigue_vivo(lanzados[0].pid), 'el ps bloqueado quedó vivo')
            finally:
                matar_los_ps()

    @lento
    def test_un_fallo_unico_del_kill_del_ps_no_cuelga_ni_deja_residuos(self):
        """AC285 (enmienda 69, Codex 59a-1, 59b-1): el plazo de `ps` no acota la limpieza interna de `subprocess.run`
        (`kill` y luego `wait` SIN plazo): si ese `kill` fallaba una vez, la espera no volvía. Con un `ps` sustituto
        bloqueado y UN fallo `EIO`, `EPERM` o `ESRCH` en su `kill`, `_estado_de`, `_senalar` y la enumeración de
        `_matar_descendientes` terminan por el reintento (el fallo queda como `__context__`) en tiempo acotado, con cada
        `ps` MUERTO, recogido y con los tubos cerrados, sin vigilante ni rescate externo. Si el `kill` falla SIEMPRE, la
        aserción propia lo dice y no se espera sin plazo (el `ps` puede quedar vivo: límite declarado)."""
        original = os.kill
        casos = [(punto, codigo) for punto in ('_estado_de', '_senalar', 'la enumeración')
                 for codigo in (errno.EIO, errno.EPERM, errno.ESRCH, 'silenciado')] + [('_estado_de', 'siempre')]
        colgados = []   # con un cuelgue el resto de los casos solo harían esperar su plazo: se corta
        for punto, codigo in casos:
            if colgados:
                break
            with self.subTest(punto=punto, fallo=codigo if isinstance(codigo, str) else errno.errorcode[codigo]), \
                    tempfile.TemporaryDirectory() as directorio:
                carpeta = Path(directorio).resolve()
                siempre = codigo == 'siempre'
                espia, lanzados, fallos = self._espia_de_ps(errno.EIO if siempre else codigo, siempre)
                vivo = None
                if punto == '_senalar':
                    vivo = subprocess.Popen(['sleep', '6007'])
                raiz = subprocess.Popen(['sleep', '6007'])   # la raíz desechable de la enumeración

                def matar_los_ps():
                    for ps in lanzados:
                        with contextlib.suppress(ProcessLookupError, PermissionError):
                            original(ps.pid, signal.SIGKILL)

                def kill(pid, numero):   # el objetivo de `_senalar` falla con EPERM: obliga a consultar a `ps`
                    if vivo is not None and pid == vivo.pid:
                        raise PermissionError(errno.EPERM, 'fallo inyectado en la señal al objetivo')
                    return original(pid, numero)
                funciones = {'_estado_de': lambda: self._estado_de(os.getpid(), plazo=0.3),
                             '_senalar': lambda: _senalar(vivo.pid if vivo else 0, signal.SIGKILL, plazo_ps=0.3),
                             'la enumeración': lambda: _matar_descendientes(raiz.pid, plazo_ps=0.3)}
                try:
                    with self._ps_sustituto(carpeta, 'exec sleep 600\n'), espia, mock.patch('os.kill', kill):
                        error, colgado = self._con_plazo(funciones[punto], matar_los_ps, plazo=6)
                    colgados.extend([colgado] if colgado else [])
                    self.assertFalse(colgado, f'{punto} sigue esperando a un ps al que no se pudo matar a la primera')
                    esperado = {'_estado_de': AssertionError, '_senalar': subprocess.TimeoutExpired,
                                'la enumeración': RuntimeError}[punto]
                    self.assertIsInstance(error, esperado, repr(error))
                    self.assertTrue(fallos, 'el fallo no se inyectó: el ps no llegó a matarse')
                    if siempre:
                        self.assertIn('no murió ni se recogió', str(error))
                        self.assertIsInstance(error.__context__, subprocess.TimeoutExpired, 'perdió la excepción original')
                        self.assertFalse(error.__suppress_context__, 'ocultó la excepción original')
                    else:
                        self.assertEqual(len(lanzados), 4 if punto == 'la enumeración' else 1)
                        for ps in lanzados:
                            self.assertIsNotNone(ps.returncode, 'un ps quedó sin recoger')
                            self.assertTrue(ps.stdout.closed and ps.stderr.closed, 'un ps dejó sus tubos abiertos')
                            self.assertFalse(self._sigue_vivo(ps.pid), 'un ps quedó vivo')
                        if punto != 'la enumeración' and codigo != 'silenciado':
                            self.assertTrue(self._cuelga_de(error, 'fallo inyectado en el kill del ps'),
                                            'el fallo del kill no cuelga de la excepción')
                finally:
                    matar_los_ps()
                    for ps in lanzados:   # el del kill que falla siempre sigue ahí: se recoge aquí
                        with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):
                            ps.wait(timeout=10)
                    for proceso in (vivo, raiz):
                        if proceso is not None:
                            with contextlib.suppress(ProcessLookupError, PermissionError):
                                original(proceso.pid, signal.SIGKILL)
                            with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):
                                proceso.wait(timeout=10)

    @staticmethod
    def _consultar_ps_de_la_sonda():
        """La `_consultar_ps` que lleva incrustada la sonda (`_IMPORTAR_TODO`), compilada aparte con sus dos ayudantes: es
        el texto que el intérprete de la sonda ejecuta de verdad, no el del módulo."""
        espacio = {}
        exec('import sys, subprocess, os, signal', espacio)   # sin nombrar los módulos aquí (AC292)
        for nodo in ast.parse(_IMPORTAR_TODO).body:
            if isinstance(nodo, ast.FunctionDef) and nodo.name in ('_limpiar', '_relanzar', '_consultar_ps'):
                exec(ast.get_source_segment(_IMPORTAR_TODO, nodo), espacio)
        return espacio['_consultar_ps']

    def test_un_sigint_en_communicate_con_el_hijo_ya_recogido_deja_los_tubos_cerrados(self):
        """AC287 (enmienda 70, Codex 60a-2): con un `SIGINT` durante `communicate`, el manejador interno de `subprocess` espera
        al hijo y fija `returncode` antes de propagar la excepción; `_consultar_ps` no cerraba entonces `stdout` ni
        `stderr`. Con un `communicate` sustituto que hace lo mismo (mata al hijo, lo recoge y lanza `KeyboardInterrupt`),
        al salir `stdout` y `stderr` están CERRADOS y el hijo muerto y recogido, en el ayudante del módulo y en su copia
        incrustada en la sonda; y cada tubo se cierra aislado del otro y reintentable: con el `close` de `stdout` fallando
        una vez, se cierra en la segunda pasada; fallando siempre, `stderr` se cierra igual (el fallo persistente deja
        `stdout` abierto: límite declarado), y en los dos casos prevalece la interrupción, con el fallo como contexto."""
        casos = (('sin fallo', None), ('el close de stdout falla una vez', 'una vez'), ('el close de stdout falla siempre', 'siempre'))
        for copia, consultar in (('del módulo', _consultar_ps), ('incrustada en la sonda', self._consultar_ps_de_la_sonda())):
            for caso, cierre_falla in casos:
                with self.subTest(copia=copia, caso=caso), tempfile.TemporaryDirectory() as directorio:
                    carpeta = Path(directorio).resolve()
                    espia, lanzados, fallos = self._espia_de_ps(interrumpe=True, cierre_falla=cierre_falla)
                    try:
                        with self._ps_sustituto(carpeta, 'exec sleep 600\n'), espia:
                            try:
                                consultar(['-o', 'stat=', '-p', '1'], 5)
                                salio = None
                            except KeyboardInterrupt as error:
                                salio = error
                        self.assertIsInstance(salio, KeyboardInterrupt, 'la interrupción se perdió')
                        self.assertEqual(len(lanzados), 1)
                        ps = lanzados[0]
                        self.assertIsNotNone(ps.returncode, 'el hijo quedó sin recoger')
                        self.assertTrue(ps.stderr.closed, 'stderr quedó abierto')
                        self.assertEqual(ps.stdout.closed, cierre_falla != 'siempre', 'stdout: estado inesperado')
                        self.assertFalse(self._sigue_vivo(ps.pid), 'el hijo quedó vivo')
                        if cierre_falla:
                            self.assertTrue(fallos, 'el fallo del close no se inyectó')
                            self.assertTrue(self._cuelga_de(salio, 'fallo inyectado en el close'), 'perdió el fallo del cierre')
                    finally:
                        for ps in lanzados:
                            for tubo in (getattr(ps.stdout, '_tubo', ps.stdout), ps.stderr):
                                if tubo is not None:
                                    tubo.close()
                            with contextlib.suppress(ProcessLookupError, PermissionError):
                                os.kill(ps.pid, signal.SIGKILL)
                            with contextlib.suppress(ChildProcessError, subprocess.TimeoutExpired):
                                ps.wait(timeout=10)

    def test_ninguna_llamada_bloqueante_de_las_pruebas_carece_de_plazo(self):
        """AC284, AC286 (enmienda 68, 69): por AST, toda llamada bloqueante de este fichero y de la sonda que lleva
        incrustada (`_IMPORTAR_TODO`, con sus ayudantes), y toda espera entregada sin llamar, tiene plazo, salvo las de
        `LLAMADAS_SIN_PLAZO_ADMITIDAS` (cerrada, con su razón; y cada entrada sigue existiendo)."""
        fuente = Path(__file__).read_text(encoding='utf-8')
        self.assertEqual(llamadas_sin_plazo(fuente), collections.Counter(
            {clave: veces for clave, (veces, _) in LLAMADAS_SIN_PLAZO_ADMITIDAS.items()}))
        importados = {alias.name for nodo in ast.walk(ast.parse(fuente)) if isinstance(nodo, ast.Import)
                      for alias in nodo.names} | {nodo.module for nodo in ast.walk(ast.parse(fuente))
                                                  if isinstance(nodo, ast.ImportFrom)}
        self.assertNotIn('queue', importados, 'un Queue.get sin plazo no lo ve esta guarda: decídelo aquí')
        self.assertEqual(llamadas_sin_plazo(_IMPORTAR_TODO), collections.Counter(), 'la sonda lleva una espera sin plazo')
        for ayudante in (_limpiar, _relanzar, _consultar_ps, _senalar, _matar_descendientes):
            self.assertIn(inspect.getsource(ayudante), _IMPORTAR_TODO, 'la sonda no lleva incrustado el ayudante')

