                    if nombre == 'co_code':   # el único que aborta al construirlo o al leerlo
                        trozos = [(desde, min(desde + 8, len(lista))) for desde in range(0, len(lista), 8)]
                        valoraciones = [v for trozo in grupo.map(lambda t: en_proceso(nombre, *t), trozos) for v in trozo]
                    else:
                        valoraciones = [comprobado(codigo, nombres, nombre, nuevo, evaluar(codigo, nombres, base, aislado_base, nombre, nuevo)) for _, nuevo in lista]
                    for (familia, nuevo), (motivo, cambia, efectivo, *recalculado) in zip(lista, valoraciones):   # un aborto del hijo trae 3
                        evaluados.setdefault(nombre, {}).setdefault(familia, []).append(   # [valor PEDIDO (completo y tipado), motivo, valor EFECTIVO]
                            [descriptor_consts(codigo.co_consts, nuevo, nombres) if nombre == 'co_consts' else tipado(nuevo), motivo, efectivo])
                        r = resultados.setdefault(nombre, {}).setdefault(familia, {'validos': 0, 'cambian': 0, 'descartes': {}})
