    def test_los_atributos_de_los_modulos_de_la_tabla_son_una_lista_cerrada(self):
        """AC289 (enmienda 70): los atributos que este fichero y la sonda usan de los módulos de la tabla son exactamente los de
        una lista cerrada con su veredicto; los marcados `TABLA` están de verdad en `PLAZO_DE` o `SIEMPRE_BLOQUEAN`. Una API que
        bloquea y no está (`os.system`, `os.popen`, `os.wait3`, `subprocess.getoutput`, `signal.pause`, `select.poll`,
        `multiprocessing.Queue`...) falla en cuanto se use. Con su negativo."""
        for donde, fuente, cerrada in (('este fichero', Path(__file__).read_text(encoding='utf-8'), ATRIBUTOS_DE_MODULOS),
                                       ('la sonda', _IMPORTAR_TODO, ATRIBUTOS_DE_LA_SONDA)):
            with self.subTest(donde=donde):
                self.assertEqual(atributos_usados(fuente), set(cerrada))
        for atributo, veredicto in {**ATRIBUTOS_DE_MODULOS, **ATRIBUTOS_DE_LA_SONDA}.items():
            if veredicto == 'TABLA':
                self.assertTrue(atributo in PLAZO_DE or atributo in SIEMPRE_BLOQUEAN, atributo)
        nuevas = ("os.system('x')\nos.popen('x')\nos.wait3(0)\nos.wait4(1, 0)\nsubprocess.getoutput('x')\nsignal.pause()\n"
                  "signal.sigwait([])\nselect.poll()\nselect.epoll()\nmultiprocessing.Queue()\nmultiprocessing.Pool()\n")
        self.assertEqual(atributos_usados(nuevas) - set(ATRIBUTOS_DE_MODULOS), {
            'os.system', 'os.popen', 'os.wait3', 'os.wait4', 'subprocess.getoutput', 'signal.pause', 'signal.sigwait',
            'select.poll', 'select.epoll', 'multiprocessing.Queue', 'multiprocessing.Pool'})
        self.assertEqual(atributos_usados('x = unittest.mock.Mock\ny = ruta.os.system\n'), set())   # no son del módulo

    def test_el_ayudante_de_ps_y_su_copia_en_la_sonda_tienen_plazo(self):
        """AC288 (enmienda 70, Codex 60b-2): control estático sobre `inspect.getsource(_consultar_ps)` y sobre la copia que
        lleva incrustada la sonda: ninguna espera sin plazo y el `communicate` lleva `timeout=plazo_ps`, no `None`. Cambiar
        `communicate(timeout=plazo_ps)` por `communicate(timeout=None)` en cualquiera de las dos cae por aquí."""
        copia = next(ast.get_source_segment(_IMPORTAR_TODO, nodo) for nodo in ast.parse(_IMPORTAR_TODO).body
                     if isinstance(nodo, ast.FunctionDef) and nodo.name == '_consultar_ps')
        for donde, fuente in (('del módulo', inspect.getsource(_consultar_ps)), ('incrustada en la sonda', copia)):
            with self.subTest(copia=donde):
                fuente = textwrap.dedent(fuente)
                self.assertEqual(llamadas_sin_plazo(fuente), collections.Counter())
                esperas = [nodo for nodo in ast.walk(ast.parse(fuente)) if isinstance(nodo, ast.Call)
                           and isinstance(nodo.func, ast.Attribute) and nodo.func.attr in ('communicate', 'wait')]
                self.assertEqual(len(esperas), 2)
                for espera in esperas:
                    plazo = next(palabra.value for palabra in espera.keywords if palabra.arg == 'timeout')
                    self.assertTrue(isinstance(plazo, ast.Name) and plazo.id == 'plazo_ps', ast.unparse(espera))

    def test_ningun_except_de_la_limpieza_traga_un_error_sin_relanzar_ni_estar_justificado(self):
        """AC283 (enmienda 68), barrido de la clase por AST: los `except` de la limpieza (sonda, padre y ayudantes) cuyo
        cuerpo no contiene un `raise` son exactamente los de `EXCEPT_QUE_NO_RELANZAN_ADMITIDOS` (cerrada, con su razón):
        ninguno traga `ProcessLookupError` ni `PermissionError` por supuesto (`_senalar` y `tolerante` relanzan salvo que
        comprueben la muerte). Con su negativo."""
        fuente = Path(__file__).read_text(encoding='utf-8')
        self.assertEqual(excepts_que_no_relanzan(fuente), collections.Counter(
            {clave: veces for clave, (veces, _) in EXCEPT_QUE_NO_RELANZAN_ADMITIDOS.items()}))
        tragando = textwrap.dedent("""
            def _senalar(pid):
                try:
                    os.kill(pid, 9)
                except (ProcessLookupError, PermissionError):
                    pass
                try:
                    os.kill(pid, 9)
                except:
                    pass
                with contextlib.suppress(ProcessLookupError, PermissionError):
                    os.kill(pid, 9)
                try:
                    os.kill(pid, 9)
                except (ProcessLookupError, PermissionError):
                    pass
        """)
        comprobando = textwrap.dedent("""
            def _senalar(pid):
                try:
                    os.kill(pid, 9)
                except (ProcessLookupError, PermissionError):
                    if vive(pid):
                        raise
        """)
        self.assertEqual(excepts_que_no_relanzan(tragando), collections.Counter({
            ('_senalar', '(ProcessLookupError, PermissionError)'): 2, ('_senalar', '<desnudo>'): 1,
            ('_senalar', 'suppress'): 1}))   # el segundo del mismo tipo no pasa inadvertido
        self.assertEqual(excepts_que_no_relanzan(comprobando), collections.Counter())

