    def test_el_padre_supervisa_al_hijo(self):
        """AC240 (enmienda 54, Codex 44a-2, 44a-3, 44c-1, 44c-2): `en_hijo` acepta el resultado solo si el hijo salió
        con normalidad y lo vigila el PADRE, con su propio plazo, sin dejar hijo vivo ni descriptor. Cada fallo, con
        su control negativo: un hijo que escribe el paquete COMPLETO y muere por SIGKILL (se aceptaba), que sale con
        código 3 tras escribirlo, que se detiene con SIGSTOP (la suite se quedaba esperando; aquí el plazo del padre
        es de 1,5 s, sin vigilante externo), que cierra la tubería y sigue vivo, que deja un paquete truncado o que
        falla; y el camino sano. AC243 (enmienda 55): los fallos se piden al hijo (`simulacion`), que ya no hereda los
        parches de la prueba. La prueba no lee ningún reloj (AC244): su red es una alarma."""
        with alarma(300), tempfile.TemporaryDirectory() as tmp:
            ruta = Path(tmp) / 'pid'
            casos = (
                ('sano: código 0 y paquete completo', anotando_el_pid, (ruta, 123), None, 60.0, 123),
                ('SIGKILL tras escribir el paquete completo', anotando_el_pid, (ruta, 123), 'matar_tras_escribir', 60.0,
                 'no salió con normalidad .*-9'),
                ('código 3 tras escribir el paquete', anotando_el_pid, (ruta, 123), 'salir_con_3', 60.0,
                 'no salió con normalidad .*código 3'),
                ('detenido con SIGSTOP', detenerse, (ruta,), None, 1.5, 'no respondió en 1[,.]5 s'),
                ('tubería cerrada con el hijo vivo', anotando_el_pid, (ruta, 123), 'cerrar_y_seguir', 1.5,
                 'cerró la tubería y no terminó en 1[,.]5 s'),
                ('paquete truncado', anotando_el_pid, (ruta, 123), 'truncar', 60.0, 'ilegible o truncado'),
                ('fallo del hijo', dividir_por_cero, (), None, 60.0, '(?s)falló el proceso hijo.*ZeroDivisionError'))
            for caso, destino, argumentos, simulacion, plazo, esperado in casos:
                with self.subTest(caso=caso):
                    ruta.unlink(missing_ok=True)
                    try:
                        resultado = en_hijo(destino, *argumentos, plazo=plazo, simulacion=simulacion)
                    except AssertionError as fallo:
                        resultado = fallo
                    if isinstance(esperado, int):
                        self.assertEqual(resultado, esperado)
                    else:
                        self.assertIsInstance(resultado, AssertionError)
                        self.assertRegex(str(resultado), esperado)
                    if ruta.exists():   # el hijo que se mata o se detiene queda recogido
                        pid = int(ruta.read_text())
                        for _ in range(200):
                            try:
                                os.kill(pid, 0)
                            except ProcessLookupError:
                                break
                            select.select([], [], [], 0.05)
                        else:
                            self.fail(f'el hijo {pid} sigue vivo')

    def test_en_hijo_no_deja_recursos_ni_hijos(self):
        """AC242 (enmienda 55, Codex 45a-1, 45c-4), AC246 (enmienda 56, Codex 46a-1, 46c-2): `en_hijo` limpia cada
        recurso por separado y ninguna interrupción deja un hijo vivo ni un descriptor. Cinco fallos, con el recuento de
        descriptores y los hijos del servidor antes y después: un `fork` que falla con EAGAIN; una interrupción (Ctrl-C)
        inmediatamente después de que `start()` vuelva; otra DENTRO de `Popen._launch`, con el hijo ya creado y antes de
        que `Process` lo registre (el padre no conoce su PID: lo mata su cuerda de vida en milisegundos); otra ya en el
        plazo; y el camino sano. Con el servidor real: los hijos se cuentan con `pgrep -P`."""
        with alarma(300):
            self.assertEqual(en_hijo(suma, 1, 2), 3)   # el servidor ya arrancó: su tubería no cuenta como una fuga
            arrancar = multiprocessing.process.BaseProcess.start
            lanzar = multiprocessing.popen_forkserver.Popen._launch
            estado = {'arrancado': False}

            def arranca_e_interrumpe(proceso):
                arrancar(proceso)
                raise KeyboardInterrupt

            def arranca_y_anota(proceso):
                arrancar(proceso)
                estado['arrancado'] = True

            def lanza_e_interrumpe(popen, proceso):
                lanzar(popen, proceso)   # el hijo ya existe y su PID ya se leyó
                esperar(estado['ruta'].exists, 1200)   # ya anunció su PID y duerme: solo su cuerda puede matarlo
                raise KeyboardInterrupt

            def interrumpe_el_plazo():   # sin reloj: un tiempo fijo, y la interrupción en el plazo de `en_hijo`
                if estado['arrancado'] and sys._getframe(1).f_code.co_name == 'en_hijo':
                    raise KeyboardInterrupt
                return 0.0
            casos = (('camino sano', None, None),
                     ('fork con EAGAIN', mock.patch.object(multiprocessing.forkserver, 'connect_to_new_process',
                                                           side_effect=OSError(errno.EAGAIN, 'sin procesos')), OSError),
                     ('interrupción tras el start', mock.patch.object(multiprocessing.process.BaseProcess, 'start',
                                                                      arranca_e_interrumpe), KeyboardInterrupt),
                     ('interrupción dentro de Popen._launch', mock.patch.object(
                         multiprocessing.popen_forkserver.Popen, '_launch', lanza_e_interrumpe), KeyboardInterrupt),
                     ('interrupción en el plazo', mock.patch.object(sys.modules[__name__], '_ahora',
                                                                    interrumpe_el_plazo), KeyboardInterrupt))
            for caso, parche, excepcion in casos:
                with self.subTest(caso=caso):
                    estado['arrancado'] = False
                    antes, hijos = len(os.listdir('/dev/fd')), hijos_del_servidor()
                    with tempfile.TemporaryDirectory() as tmp, contextlib.ExitStack() as pila:
                        ruta = estado['ruta'] = Path(tmp) / 'pid'
                        if caso == 'interrupción en el plazo':   # el hijo ya vive cuando salta
                            pila.enter_context(mock.patch.object(multiprocessing.process.BaseProcess, 'start',
                                                                 arranca_y_anota))
                        if parche is not None:
                            pila.enter_context(parche)
                        if excepcion is None:
                            self.assertEqual(en_hijo(anotando_el_pid, ruta, 7), 7)
                        else:
                            with self.assertRaises(excepcion):
                                en_hijo(dormir, ruta, 30)
                    self.assertTrue(esperar(lambda: hijos_del_servidor() == hijos), 'queda un hijo vivo')
                    self.assertTrue(esperar(lambda: descriptores_estables(antes)), 'queda un descriptor abierto')

    def test_el_plazo_del_padre_cubre_el_arranque(self):
        """AC245 (enmienda 56, Codex 46a-2, 46c-1): el plazo corre desde ANTES de pedir el hijo y acota `start()`, que
        escribe la preparación y espera el PID del servidor sin plazo. Con el servidor REAL detenido (SIGSTOP) antes de
        pedir el hijo, y con la preparación saturada (16 MiB de argumentos contra un servidor que no lee),
        `en_hijo(plazo=1)` falla con un `AssertionError` claro en lugar de dejar la suite esperando; la alarma de 60 s
        es solo la red de la prueba. Después el servidor sigue (SIGCONT), no queda ningún hijo ni descriptor, y el
        camino sano funciona."""
        with alarma(300):
            for caso, argumentos in (('servidor detenido', (1, 2)), ('preparación saturada', ('x' * (16 << 20), 'y'))):
                with self.subTest(caso=caso):
                    self.assertEqual(en_hijo(suma, 1, 2), 3)   # un servidor vivo (un apretón abortado lo tumba)
                    servidor, antes = pid_del_servidor(), len(os.listdir('/dev/fd'))
                    os.kill(servidor, signal.SIGSTOP)
                    try:
                        with alarma(60), self.assertRaisesRegex(AssertionError, 'no arrancó en 1 s'):
                            en_hijo(suma, *argumentos, plazo=1.0)
                    finally:
                        os.kill(servidor, signal.SIGCONT)
                    self.assertTrue(esperar(lambda: descriptores_estables(antes)), 'queda un descriptor abierto')
            self.assertEqual(en_hijo(suma, 3, 4), 7)

    def test_el_hijo_muere_aunque_falle_el_servidor_o_el_padre(self):
        """AC246 (enmienda 56, Codex 46c-2): el hijo no depende de lo que el padre sepa o pueda de él. (1) Con el
        servidor REAL muerto a mitad de la medida (`multiprocessing` lee el EOF de su canal como `exitcode` 255,
        `is_alive()` falso, con el hijo vivo), `en_hijo` falla al vencer el plazo y el hijo muere por su PID anunciado
        (comprobado por PID); el servidor se recupera en la llamada siguiente. (2) Con el padre muerto a mitad de la
        medida (SIGKILL a un proceso que corre `en_hijo`), la cuerda de vida mata al hijo por sí sola."""
        with alarma(300), tempfile.TemporaryDirectory() as tmp:
            self.assertEqual(en_hijo(suma, 1, 2), 3)
            ruta = Path(tmp) / 'servidor.pid'
            with self.assertRaisesRegex(AssertionError, 'no respondió en 1[,.]5 s'):
                en_hijo(matar_al_servidor, ruta, pid_del_servidor(), plazo=1.5)
            pid = int(ruta.read_text())
            self.assertTrue(esperar(lambda: not esta_vivo(pid)), f'el hijo {pid} sigue vivo')
            self.assertEqual(en_hijo(suma, 5, 6), 11)   # el servidor, otro, sigue sirviendo
            ruta = Path(tmp) / 'padre.pid'
            codigo = f'import {__name__} as T\nT.en_hijo(T.dormir, {str(ruta)!r}, 60, plazo=300)\n'
            entorno = {**os.environ, 'PYTHONPATH': os.pathsep.join(sys.path)}
            padre = subprocess.Popen([sys.executable, '-c', codigo], env=entorno)
            try:
                self.assertTrue(esperar(ruta.exists, 1200), 'el hijo no arrancó')
                pid = int(ruta.read_text())
                padre.kill()
                padre.wait(timeout=30)
                self.assertTrue(esperar(lambda: not esta_vivo(pid)), f'el hijo {pid} sobrevive a su padre muerto')
            finally:
                padre.kill()
                padre.wait(timeout=30)

    def test_una_senal_durante_el_temporizador_deja_el_manejador_y_la_alarma(self):
        """AC252 (enmienda 57, Codex 47a-2): la restauración de `SIGALRM` resiste una interrupción. Un `SIGINT` REAL
        tras cada llamada de C de la instalación y de la restauración de `_con_temporizador` (donde un `SIGINT` se
        atiende), con una alarma previa de 5 s y su manejador, deja el manejador y lo que quedaba de la alarma como
        estaban; antes, la sustitución del manejador estaba fuera del `try` y un `SIGINT` justo después la dejaba
        puesta. Y una `alarma` anidada ya no desarma la exterior (antes la dejaba a 0), y la exterior sigue cortando si
        vence antes. Corre en un hijo: el temporizador y las señales son suyos."""
