    def test_el_cuerpo_migrado_se_comporta_como_una_prueba_normal(self):
        """AC248 (enmienda 56, Codex 46b-2, 46c-4): `ejecutar_cuerpo_en_hijo` corre la prueba con `unittest` en el hijo
        y el padre la hace suya. `setUp` que falla tras `mkdtemp` (la limpieza registrada corre UNA vez; antes,
        ninguna), una limpieza que falla (el padre falla; antes comunicaba éxito), una prueba omitida (el padre la
        omite), un fallo esperado (pasa), un éxito inesperado (falla), el camino sano y un hijo matado a mitad (el padre
        falla y el directorio del fixture, que crea y borra el padre, desaparece: antes quedaba el `mkdtemp` del
        hijo)."""
        modulo = __name__
        ejecutar_cuerpo_en_hijo(modulo, 'Sana', 'runTest')
        ejecutar_cuerpo_en_hijo(modulo, 'FalloEsperado', 'runTest')
        with tempfile.TemporaryDirectory() as directorio:
            with self.assertRaisesRegex(AssertionError, 'OSError'):
                ejecutar_cuerpo_en_hijo(modulo, 'FalloEnSetUp', 'runTest', directorio)
            self.assertEqual((Path(directorio) / 'marcas.txt').read_text().splitlines(), ['limpieza'])
        with self.assertRaisesRegex(AssertionError, 'la limpieza falla'):
            ejecutar_cuerpo_en_hijo(modulo, 'LimpiezaQueFalla', 'runTest')
        with self.assertRaisesRegex(AssertionError, 'inesperado'):
            ejecutar_cuerpo_en_hijo(modulo, 'ExitoInesperado', 'runTest')
        with self.assertRaises(unittest.SkipTest):
            ejecutar_cuerpo_en_hijo(modulo, 'Omitida', 'runTest')
        nombres, contenidos = [], []

        class Registro(tempfile.TemporaryDirectory):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                nombres.append(self.name)

            def cleanup(self):
                contenidos.append(sorted(os.listdir(self.name)) if os.path.isdir(self.name) else None)
                super().cleanup()
        with mock.patch.object(tempfile, 'TemporaryDirectory', Registro):
            with self.assertRaisesRegex(AssertionError, 'no salió con normalidad'):
                ejecutar_cuerpo_en_hijo(modulo, 'Mortal', 'runTest')
        self.assertEqual(len(nombres), 1)
        self.assertEqual(len(contenidos[0]), 1, contenidos)   # el `mkdtemp` del hijo vivía dentro del del padre
        self.assertTrue(contenidos[0][0].startswith('tmp'), contenidos)
        self.assertFalse(os.path.exists(nombres[0]))

