    def test_las_comillas_no_parten_un_dato_civil(self):
        """AC151 (enmienda 35, reproducción de Codex): la fecha y la sociedad se buscan a través de las comillas, con
        las posiciones del texto original: «Pagado el 8/«10».» y «Pagado «08»/«10»/«2025».» llevan una fecha aunque cada
        tramo esté probado (antes, nada; sin comillas, ya), porque el dato entero no cae en un único tramo, y «Nim«bo»
        S.L.» o «Nimbo» S.L., una sociedad. El dato entero dentro de un único tramo probado, no."""
        vacio = ({}, {})

        def prueba(t, d):
            return d == 'ATS_A.pdf'
        nimbo = S.indice_sociedades({'Company:zz-nimbo-sl': {'Nimbo S.L.'}})
        casos = [('Pagado el 8/«10».', {}, ['fecha']), ('Pagado «08»/«10»/«2025».', {}, ['fecha']),
                 ('Pagado el «8»/10.', {}, ['fecha']), ('Pagado «el 8/10».', {}, []),
                 ('Pagado «el 8/10/2025».', {}, []),
                 ('Pagó a Nim«bo» S.L.', nimbo, ['sociedad']), ('Pagó a «Nimbo» S.L.', nimbo, ['sociedad']),
                 ('Pagó a «Nimbo S.L.».', nimbo, [])]
        # Cualquier comilla: las de apertura y cierre de Unicode, las rectas, las graves, las bajas y las de ancho
        # completo; la sociedad sin forma jurídica del índice, por la lectura que las une.
        solo_nombre = S.indice_sociedades({'Company:zz-nimbo-sl': {'Nimbo'}})
        casos += [(f'Pagado el 8/{a}10{b}.', {}, ['fecha']) for a, b in ('‘’', '“”', '‹›', '„“', '``', '〝〞', '＂＂')]
        casos += [(f'Pagó a Nim{a}bo{b}.', solo_nombre, ['sociedad']) for a, b in ('«»', '``', "''", '‘’')]
        for texto, sociedades, esperado in casos:
            with self.subTest(texto=texto):
                self.assertEqual(S.problemas_dato_civil(texto, 'contenido', vacio, sociedades, doc='ATS_A.pdf',
                                                        prueba=prueba), esperado)
        self.assertEqual(S.problemas_dato_civil('Pagado el 8/«10».', 'contenido', vacio, {}), ['fecha'])

