    def test_una_fila_civil_de_prosa_no_nombra_a_un_seudonimo(self):
        """AC65 (enmienda 16): una fila de prosa de una entidad civil (resúmenes, roles, familiares, reglas, registro)
        que nombra a un seudónimo del roster, por su id o por su slug entre separadores, es hallazgo con la huella del
        seudónimo. La fila del propio seudónimo (una retirada) no lo es, ni el slug dentro de otra palabra."""
        slug = SEUDO.split(':', 1)[1]
        ficheros = {
            'pipeline/data/context/summaries_qa061.yaml': f"""\
                summaries:
                - entity_id: {CIVIL}
                  name: Zz Civil
                  resumen: Prosa.
                  reason: 'no había conflación: {SEUDO} ya estaba escindido'
                - entity_id: {SEUDO}
                  name: Zz Test
                  remove: true
                  reason: 'retirada de {SEUDO}'
                - entity_id: Person:yy-otro-civil
                  name: Yy
                  resumen: Prosa.
                  reason: 'la palabra x{slug}x no es el slug'
                """,
            'pipeline/data/context/roles_qa061.yaml': f"""\
                entities:
                - {{type: Person, name: Zz Civil, entity_id: {CIVIL}, role: Rol., reason: 'el slug {slug}, citado'}}
                relations: []
                """,
            'pipeline/data/context/familiares_revisados.yaml': f"""\
                revisados:
                - {{entity_id: {SEUDO}, decision: anonimizar, fecha: '2026-09-29', reason: 'sobre {SEUDO}'}}
                """,
            f'{S.RELATIONS_REL}/relations.yaml': f"""\
                deny:
                  - {{source_id: {CIVIL}, target_id: Person:yy-otro-civil, type: PAID, reason: 'no es {SEUDO}'}}
                """,
            S.REGISTRO_REL: f"""\
                rectificaciones:
                - {{id: R-1, entidad: {CIVIL}, dato: 'rol corregido; ver {SEUDO}', decision: rectificado}}
                """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = [h for h in S.auditar(repo, publicos=frozenset()) if h.clase == 'prosa']
            code, salida = ejecutar_check(repo)
        motivo = f'fila civil que nombra a un seudónimo judicial (huella {S.sha16(SEUDO)})'
        self.assertEqual([(h.fichero.rsplit('/', 1)[-1], h.linea, h.motivo) for h in hallazgos],
                         [('roles_qa061.yaml', 2, motivo), ('summaries_qa061.yaml', 2, motivo),
                          ('registro.yaml', 2, motivo), ('relations.yaml', 2, motivo)])
        self.assertEqual(code, 1)
        self.assertNotIn(slug, salida)

