        for modo in ('drop', 'keep_only'):
            reglas = f"alias_deny:\n  - {{id: Person:yy-ciudadano-test, {modo}: ['{alias}'], reason: r}}\n"
            with self.subTest(modo), tempfile.TemporaryDirectory() as tmp:
                repo = repo_sintetico(Path(tmp) / 'repo', {f'{S.RELATIONS_REL}/relations.yaml': reglas})
                hallazgos = S.auditar(repo, publicos=frozenset())
                code, salida = ejecutar_check(repo)
                self.assertEqual([(h.linea, h.clase, h.motivo) for h in hallazgos],
                                 [(2, 'alias_deny', motivo), (2, 'prosa', civil), (2, 'prosa', identificador)])
                self.assertEqual(code, 1)
                self.assertNotIn('zz (seud', salida.lower())

