    def test_todas_las_capas_publicas_y_su_inventario(self):
        """AC79 (enmienda 21): el check lee cada fila de cada capa pública del inventario, no solo contexto, reglas y
        registro: la nota de un cargo del BOE de un civil que lo identifica con un seudónimo es hallazgo. Y el
        inventario clasifica cada campo de texto de cada YAML versionado de pipeline/data: un fichero, una sección o un
        campo nuevos se denuncian (el árbol real, ninguno)."""
        ficheros = {'pipeline/data/boe/boe.yaml': f"""\
            trayectorias:
            - entity_id: {CIVIL}
              cargos:
              - cargo: Asesor
                nota: 'Identificado como el seudónimo «Zz Test».'
            """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            self.assertEqual([(h.fichero, h.linea, h.clase, h.motivo) for h in S.auditar(repo, publicos=frozenset())],
                             [('pipeline/data/boe/boe.yaml', 2, 'prosa',
                               f'fila civil que nombra a un seudónimo judicial (huella {S.sha16(SEUDO)})')])
            self.assertEqual(S.campos_sin_clasificar(repo), [])
            boe = repo / 'pipeline/data/boe/boe.yaml'
            boe.write_text(boe.read_text(encoding='utf-8') + '    apodo: x\notra: []\n', encoding='utf-8')
            (repo / 'pipeline/data/nueva').mkdir()
            (repo / 'pipeline/data/nueva/capa.yaml').write_text('filas: []\n', encoding='utf-8')
            # AC92: posición y huella de la clave, nunca la clave.
            self.assertEqual(S.campos_sin_clasificar(repo), sorted([
                ('pipeline/data/boe/boe.yaml', 0, S.sha16('otra')),
                ('pipeline/data/boe/boe.yaml', 2, S.sha16('trayectorias[].cargos[].apodo')),
                ('pipeline/data/nueva/capa.yaml', 0, S.sha16('*'))]))
        self.assertEqual(S.campos_sin_clasificar(REAL_REPO), [])

