    def test_el_roster_pasa_el_cierre_comun(self):
        """AC84 (enmienda 22): cada fila del roster pasa el cierre común como fila de su seudónimo, con el texto
        normalizado: un id civil con otra caja o con un U+034F dentro, un documento fuera del árbol y la mención de otro
        seudónimo son hallazgo (el id, también de AC68); el id y el nombre de un homónimo, y su propio nombre numerado,
        no. Los dos modos del check terminan sin los valores."""
        roster = """\
            pseudonyms:
            - id: Person:zz-seudonimo-test
              note: 'Escindido de PERSON:zz-civil-apellido.'
            - id: Person:zz-otro-seudonimo-test
              curacion: 'Identificado en reservado.pdf p.3.'
            - id: Person:yy-tercer-seudonimo-test
              curacion: 'Distinto del seudónimo «Zz Test» del mismo auto.'
            - id: Person:yy
              note: seudónimo sintético
            - id: Person:yy-ats-1-2025
              name: Yy (ATS 1/2025)
              curacion: 'Homónimo de Person:yy, el seudónimo «Yy» de otro auto.'
            - id: Person:xx
              note: "Escindido de Person:zz\\u034f-civil-apellido."
            """
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', {S.PSEUDONYMS_REL: roster})
            hallazgos = S.auditar(repo, publicos=frozenset())
            nota = yaml.safe_load(textwrap.dedent(roster))['pseudonyms'][5]['note']
            snap = self.snapshot_vacio(Path(tmp) / 'snap')
            salidas = [ejecutar_check(repo, *argv) for argv in ((), ('--snapshot', snap))]
        ac78 = 'texto de una fila de seudónimo nombra a un civil o a un documento (huella {})'
        civil = 'una fila nombra a una entidad civil (huella {})'
        self.assertEqual([(h.linea, h.clase, h.motivo) for h in hallazgos], [
            (2, 'prosa', ac78.format(S.sha16('PERSON:zz-civil-apellido'))),
            (2, 'roster', civil.format(S.sha16('PERSON:zz-civil-apellido'))),
            (4, 'prosa', ac78.format(S.sha16('reservado.pdf'))),
            (6, 'prosa', ac78.format(S.sha16(SEUDO))),
            (13, 'prosa', f'texto con caracteres invisibles o alfabetos mezclados (huella {S.sha16(nota)})'),
            (13, 'prosa', ac78.format(S.sha16('Person:zz-civil-apellido'))),
            (13, 'roster', civil.format(S.sha16('Person:zz-civil-apellido')))])
        self.assertEqual([code for code, _ in salidas], [1, 1])
        for _, salida in salidas:
            for valor in ('zz-civil-apellido', 'reservado', 'Zz Test'):
                self.assertNotIn(valor, salida)

    def test_los_ignorables_y_las_url_decodificadas_en_el_arbol(self):
        """AC85 (enmienda 22): el id de un seudónimo con un U+034F dentro, en el resumen de un civil, lo nombra y además
        es sospechoso; una URL con una letra cirílica codificada (%D0%B0) es sospechosa."""
        cgj, url = SOLO.replace('zz', 'zz\\u034f'), 'https://example.org/z%D0%B0-test'
        ficheros = {S.PSEUDONYMS_REL: PSEUDONYMS + f'- id: {SOLO}\n  note: seudónimo sintético\n',
                    'pipeline/data/context/summaries_qa061.yaml': f"""\
            summaries:
            - entity_id: {CIVIL}
              name: Zz Civil
              resumen: "No es {cgj}."
              sources: ['{url}']
            """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = S.auditar(repo, publicos=frozenset())
            resumen = yaml.safe_load(textwrap.dedent(ficheros['pipeline/data/context/summaries_qa061.yaml']))[
                'summaries'][0]['resumen']
        sospechoso = 'texto con caracteres invisibles o alfabetos mezclados (huella {})'
        self.assertEqual([(h.linea, h.clase, h.motivo) for h in hallazgos],
                         [(2, 'prosa', f'fila civil que nombra a un seudónimo judicial (huella {S.sha16(SOLO)})')]
                         + [(2, 'prosa', m) for m in sorted(sospechoso.format(S.sha16(x)) for x in (resumen, url))])


    def test_los_nombres_y_alias_de_una_fila_civil_tambien(self):
        """AC86 (enmienda 23): el detector lee también los nombres y alias de una fila civil: el `name` de una entidad
        del contexto y un `move_aliases` de un split entre civiles que identifican a un seudónimo son hallazgo, con la
        huella del seudónimo, y (AC167, enmienda 36) son un nombre y un alias que identifican, con su huella. Un civil
        que lleva el nombre de pila del seudónimo sin la palabra, no; y el split de un seudónimo del roster (su
        `namesake`, una variante AC83), tampoco. El CI termina sin los nombres."""
        ficheros = {
            'pipeline/data/context/figures.yaml': f"""\
                entities:
                - {{type: Person, name: Yy Civil Apellido (seudónimo Zz Test), entity_id: {CIVIL}, role: Testigo.}}
                - {{type: Person, name: Zz Test Garcia, entity_id: Person:yy-civil-test, role: Testigo.}}
                """,
            f'{S.RELATIONS_REL}/relations.yaml': """\
                splits:
                  - canonical: {type: Person, name: Yy Civil Uno}
                    namesake: {type: Person, name: Yy Civil Dos}
                    by_doc: publico.pdf
                    move_aliases: ["el seudónimo Zz Test"]
                  - canonical: {type: Person, name: Yy Civil Uno}
                    namesake: {type: Person, name: Zz Seudonimo Test}
                    by_doc: publico.pdf
                """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = S.auditar(repo, publicos=frozenset())
            code, salida = ejecutar_check(repo)
        civil = f'fila civil que nombra a un seudónimo judicial (huella {S.sha16(SEUDO)})'
        identificador = S.MOTIVOS['alias-identificador'] + ' (huella {})'
        self.assertEqual(sorted((h.fichero, h.linea, h.clase, h.motivo) for h in hallazgos),
                         [('pipeline/data/context/figures.yaml', 2, 'prosa', civil),
                          ('pipeline/data/context/figures.yaml', 2, 'prosa',
                           identificador.format(S.sha16('Yy Civil Apellido (seudónimo Zz Test)'))),
                          (f'{S.RELATIONS_REL}/relations.yaml', 2, 'prosa', civil),
                          (f'{S.RELATIONS_REL}/relations.yaml', 2, 'prosa',
                           identificador.format(S.sha16('el seudónimo Zz Test')))])
        self.assertEqual(code, 1)
        for valor in ('zz test', 'civil apellido', 'yy civil'):
            self.assertNotIn(valor, salida.lower())

    def test_la_cita_que_identifica_al_seudonimo_con_su_extremo_civil(self):
        """AC87 (enmienda 23): la exención del extremo civil en la cita de una regla de seudónimo es solo para la
        coaparición. La cita (`quote_contains`) de un `fix` MET_WITH que dice «seudónimo» identifica al seudónimo con el
        civil: cuentan el nombre del civil y la mención del seudónimo; la que lleva un id, el nombre del civil; y las
        dos, además, son AC90 sin prueba (AC94, enmienda 25: la marca no exime). La de coaparición ya no pasa sin prueba
        (AC90, enmienda 24): su huella. AC150 (enmienda 35): «seudónimo» entre el civil y el seudónimo lo identifica,
        con la huella de la cita. El CI termina sin los nombres."""
        civil = 'Zz Civil Apellido'
        ficheros = {
            'data/publico.pdf': '',
            'pipeline/data/context/figures.yaml': f"""\
                entities:
                - {{type: Person, name: {civil}, entity_id: {CIVIL}, role: Testigo.}}
                """,
            f'{S.RELATIONS_REL}/relations.yaml': f"""\
                fix:
                  - {{source_id: {SEUDO}, target_id: {CIVIL}, type: MET_WITH, doc: publico.pdf,
                     corrected_type: ASSOCIATED_WITH, quote_contains: '{civil} utiliza el seudónimo «Zz Test»'}}
                  - {{source_id: {SEUDO}, target_id: {CIVIL}, type: MET_WITH, doc: publico.pdf,
                     corrected_type: ASSOCIATED_WITH, quote_contains: '{civil} ({CIVIL}) se reunió con él'}}
                  - {{source_id: {SEUDO}, target_id: {CIVIL}, type: MET_WITH, doc: publico.pdf,
                     corrected_type: ASSOCIATED_WITH, quote_contains: 'Se reunió con {civil}'}}
                """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = S.auditar(repo)
            code, salida = ejecutar_check(repo)
        self.assertEqual(sorted((h.linea, h.clase, h.motivo) for h in hallazgos),
                         sorted([(2, 'prosa', self.AC78.format(S.sha16(civil))),
                                 (2, 'prosa', self.AC78.format(S.sha16(SEUDO))),
                                 (2, 'prosa', self.AC78.format(S.sha16(f'{civil} utiliza el seudónimo «Zz Test»'))),
                                 (2, 'prosa', COAPARICION.format(S.sha16(f'{civil} utiliza el seudónimo «Zz Test»'))),
                                 (4, 'prosa', self.AC78.format(S.sha16(civil))),
                                 (4, 'prosa', COAPARICION.format(S.sha16(f'{civil} ({CIVIL}) se reunió con él'))),
                                 (6, 'prosa', COAPARICION.format(S.sha16(f'Se reunió con {civil}')))]))
        self.assertEqual(code, 1)
        for valor in ('civil apellido', 'zz test'):
            self.assertNotIn(valor, salida.lower())

    def test_cada_hoja_del_tipo_de_su_ruta(self):
        """AC157 (enmienda 35, reproducciones de Codex): toda hoja de un YAML del inventario es texto, número, booleano
        o nulo, y número o booleano solo donde el inventario lo declara. Un `!!set`, un `!!binary` o una fecha YAML sin
        comillas no los audita ningún recorrido: ErrorDeForma «valor no auditable» (antes, la ruta se daba por conocida
        y el contenido no se miraba); un número donde va texto, «un campo que no es un texto»; un texto o un booleano
        donde va un número, «un campo que no es un número». En el árbol, el roster y la lista (que leen también el
        loader, el apply y el snapshot), con la huella de la ruta y sin el valor; sus controles entre comillas, no."""
        figuras = 'pipeline/data/context/figures.yaml'
        fila = '- {{type: Person, name: Yy Civil Test, entity_id: Person:yy-civil-test, role: {}}}\n'
        ruta = S.sha16('role')
        casos = {'2001-02-03': 'valor no auditable', '!!binary UVozNUNFTlRJTkVMQQ==': 'valor no auditable',
                 '!!set {QZ36CENTINELA: null}': 'valor no auditable', '7012309': 'un campo que no es un texto'}
        with tempfile.TemporaryDirectory() as tmp:
            for n, (valor, motivo) in enumerate(casos.items()):
                with self.subTest(valor=valor):
                    repo = repo_sintetico(Path(tmp) / f'f{n}', {figuras: 'entities:\n' + fila.format(valor)})
                    with self.assertRaises(S.ErrorDeForma) as fin:
                        S.auditar(repo, publicos=frozenset())
                    self.assertEqual(fin.exception.motivos,
                                     [f'forma inválida (spec 070): {figuras}: `entities`[0]: {motivo} (huella {ruta})'])
                    code, salida = ejecutar_check(repo)
                    self.assertEqual(code, 2, salida)
                    for centinela in ('qz36', 'centinela', '7012309', '2001'):
                        self.assertNotIn(centinela, salida.lower())
                    control = repo_sintetico(Path(tmp) / f'c{n}', {figuras: 'entities:\n' + fila.format(f"'{n}'")})
                    self.assertEqual(S.auditar(control, publicos=frozenset()), [])
            contratos = 'pipeline/data/contratacion/zz.yaml'
            repo = repo_sintetico(Path(tmp) / 'contratos', {contratos: (
                "adjudicatarias:\n- {adjudicataria: 'Company:yy-x', n_contratos: QZ37CENTINELA, total_eur: true}\n")})
            with self.assertRaises(S.ErrorDeForma) as fin:
                S.auditar(repo, publicos=frozenset())
            self.assertEqual(fin.exception.motivos, [
                f'forma inválida (spec 070): {contratos}: `adjudicatarias`[0]: un campo que no es un número '
                f'(huella {S.sha16(r)})' for r in ('n_contratos', 'total_eur')])
            bien = repo_sintetico(Path(tmp) / 'contratos-bien', {contratos: (
                "adjudicatarias:\n- {adjudicataria: 'Company:yy-x', n_contratos: 3, total_eur: 1200.5}\n")})
            self.assertEqual(S.auditar(bien, publicos=frozenset()), [])
            roster = Path(tmp) / 'pseudonyms.yaml'
            roster.write_text(f'pseudonyms:\n- id: {SEUDO}\n  curacion: !!set {{QZ38CENTINELA: null}}\n',
                              encoding='utf-8')
            with self.assertRaises(S.ErrorDeForma) as fin:
                S.ids_seudonimos(roster)
            self.assertEqual(fin.exception.motivos, [
                f'pseudonyms.yaml: roster inválido (spec 070): `pseudonyms`[0]: valor no auditable '
                f'(huella {S.sha16("curacion")})'])
            lista = Path(tmp) / S.PERMITIDOS_NOMBRE
            entrada = S.entrada_cita('una cita', SEUDO, ['a.pdf'], 'decision-2026-10-07', MOTIVO_CITA)
            lista.write_text(S.volcar_permitidos({'aristas': [], 'alias': [], 'citas': [entrada]}).replace(
                "origen: decision-2026-10-07", 'origen: 2026-10-07'), encoding='utf-8')
            with self.assertRaises(S.ErrorDeForma) as fin:
                S.cargar_permitidos(lista)
            self.assertEqual(fin.exception.motivos, [
                f'forma inválida (spec 070): {S.PERMITIDOS_REL}: `citas`[0]: valor no auditable '
                f'(huella {S.sha16("origen")})'])

    def test_una_letra_latina_confusable_es_sospechosa(self):
        """AC88 (enmienda 23): el rol de un civil con una letra latina confusable («\u0131» sin punto, la alfa latina
        «\u0251») es sospechoso, con la huella del texto; uno con «\u0142» o con tildes y eñes, no. El CI termina sin
        el texto."""
        roles = ['Asesor de K\u0131ldo.', 'Asesor de Kold\u0251.', 'Corresponsal en \u0141\u00f3d\u017a y en A Coruña.']
        ficheros = {'pipeline/data/context/figures.yaml': 'entities:\n' + ''.join(
            f'- {{type: Person, name: Yy Civil {n}, entity_id: "Person:yy-civil-{n}", role: "{rol}"}}\n'
            for n, rol in enumerate(roles))}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = S.auditar(repo, publicos=frozenset())
            code, salida = ejecutar_check(repo)
        sospechoso = 'texto con caracteres invisibles o alfabetos mezclados (huella {})'
        self.assertEqual([(h.linea, h.clase, h.motivo) for h in hallazgos],
                         [(2, 'prosa', sospechoso.format(S.sha16(roles[0]))),
                          (3, 'prosa', sospechoso.format(S.sha16(roles[1])))])
        self.assertEqual(code, 1)
        self.assertNotIn('asesor', salida.lower())

    def test_un_id_con_forma_de_seudonimo_fuera_del_roster(self):
        """AC89 (enmienda 23), fail closed: un entity_id con «seudonimo» (o «pseudonimo») en el slug que el roster no
        declara es hallazgo `roster-ausente`, con su huella: el de una entidad del contexto, el que se deriva del
        `namesake` de un split, la entidad de una fila del registro y uno nombrado en un texto. Declarado en el roster,
        el mismo id pasa (el otro sigue fuera). El CI termina sin los ids."""
        texto = 'Person:yy-pseudonimo-fuera'
        ficheros = {
            'pipeline/data/context/figures.yaml': f"""\
                entities:
                - {{type: Person, name: Zz Test, entity_id: {SEUDO}}}
                """,
            'pipeline/data/context/summaries_qa061.yaml': f"""\
                summaries:
                - entity_id: Person:yy-civil-test
                  name: Yy Civil
                  remove: true
                  reason: 'retirada la mención de {texto}'
                """,
            f'{S.RELATIONS_REL}/relations.yaml': """\
                splits:
                  - canonical: {type: Person, name: Yy Civil Uno}
                    namesake: {type: Person, name: Zz Seudonimo Test}
                    by_doc: publico.pdf
                """,
            S.REGISTRO_REL: f"""\
                rectificaciones:
                - id: R-1
                  entidad: {SEUDO}
                  dato: '({SEUDO}) -[MET_WITH]-> (Person:[tercero]): arista retirada'
                """}
        fuera = 'id con forma de seudónimo fuera del roster (huella {})'
        with tempfile.TemporaryDirectory() as tmp:
            roster = f'pseudonyms:\n- id: {SEUDO2}\n  note: seudónimo sintético\n'
            sin = repo_sintetico(Path(tmp) / 'sin', {**ficheros, S.PSEUDONYMS_REL: roster}, lista=permitidos())
            con = repo_sintetico(Path(tmp) / 'con', ficheros)
            hallazgos = {nombre: S.auditar(repo, publicos=frozenset()) for nombre, repo in (('sin', sin), ('con', con))}
            code, salida = ejecutar_check(sin)
        self.assertEqual(sorted((h.fichero, h.linea, h.clase, h.motivo) for h in hallazgos['sin']), [
            ('pipeline/data/context/figures.yaml', 2, 'roster-ausente', fuera.format(S.sha16(SEUDO))),
            ('pipeline/data/context/summaries_qa061.yaml', 2, 'roster-ausente', fuera.format(S.sha16(texto))),
            (S.REGISTRO_REL, 2, 'roster-ausente', fuera.format(S.sha16(SEUDO))),
            (f'{S.RELATIONS_REL}/relations.yaml', 2, 'roster-ausente', fuera.format(S.sha16(SEUDO)))])
        self.assertEqual([(h.fichero, h.linea, h.clase, h.motivo) for h in hallazgos['con']],
                         [('pipeline/data/context/summaries_qa061.yaml', 2, 'roster-ausente',
                           fuera.format(S.sha16(texto)))])
        self.assertEqual(code, 1)
        for valor in ('zz-seudonimo', 'pseudonimo-fuera'):
            self.assertNotIn(valor, salida)


    def test_los_nombres_de_un_grupo_de_merges(self):
        """Remate 23b (AC86 en merges): el `canonical` de un grupo de merges es un nombre y cada `duplicates`, un alias
        del canónico en el grafo; sus ids, los que deriva `load_merges`. En un grupo civil, el canónico o un duplicado
        (cadena o mapa) que identifica a un seudónimo es hallazgo con la huella del seudónimo, y su id derivado, con
        forma de seudónimo fuera del roster, también (AC89); un grupo corriente pasa. El que funde al seudónimo en un
        civil es fila de seudónimo: el nombre civil del canónico no es una variante (AC83). AC167 (enmienda 36): y ese
        nombre civil, con la huella del nombre, identifica. El CI, sin los nombres."""
        marcado = 'Yy Civil (seudónimo Zz Test)'
        ficheros = {'pipeline/data/context/merges.yaml': f"""\
            merges:
            - canonical: {{type: Person, name: Yy Civil Uno}}
              duplicates: ['{marcado}']
            - canonical: {{type: Person, name: Yy Civil Dos}}
              duplicates: [{{name: '{marcado}', type: Person}}]
            - canonical: {{type: Person, name: '{marcado}'}}
              duplicates: [Yy Civil Tres]
            - canonical: {{type: Person, name: Yy Civil Cuatro}}
              duplicates: [Yy C. Cuatro, {{name: Yy Cuatro, type: Person}}]
            - canonical: {{type: Person, name: Yy Civil Cinco}}
              duplicates: [Zz Seudonimo Test]
            """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = S.auditar(repo, publicos=frozenset())
            code, salida = ejecutar_check(repo)
        civil = f'fila civil que nombra a un seudónimo judicial (huella {S.sha16(SEUDO)})'
        fuera = 'id con forma de seudónimo fuera del roster (huella {})'.format(S.sha16(S.entity_id('Person', marcado)))
        nombre = f'nombre de un seudónimo fuera de sus variantes (huella {S.sha16("Yy Civil Cinco")})'
        identificador = f'{S.MOTIVOS["alias-identificador"]} (huella {S.sha16(marcado)})'
        self.assertEqual(sorted((h.linea, h.clase, h.motivo) for h in hallazgos),
                         sorted([*((linea, 'prosa', civil) for linea in (2, 4, 6)),
                                 *((linea, 'prosa', identificador) for linea in (2, 4, 6)),
                                 *((linea, 'roster-ausente', fuera) for linea in (2, 4, 6)), (10, 'prosa', nombre)]))
        self.assertEqual(code, 1)
        for valor in ('yy civil', 'zz test', 'zz seudonimo'):
            self.assertNotIn(valor, salida.lower())

    def test_las_citas_de_un_split_de_seudonimo_solo_nombran_a_su_namesake(self):
        """AC87/AC90 en los splits (enmienda 24, punto 3): en un split cuyo canónico es un seudónimo, `by_quote*` puede
        nombrar a su propio namesake civil (nombre entero, dos palabras seguidas o un alias que se lleva), ya público en
        la regla; la cita que nombra a otro civil (del contexto, o el lado civil de un split cuyo canónico es civil) es
        hallazgo con la huella del nombre, y la que dice «seudónimo» o lleva un id, con la huella de la cita. El CI, sin
        los nombres."""
        civil, namesake, canonico = 'Zz Civil Apellido', 'Yy Namesake Civil', 'Yy Canonico Civil'
        palabra, con_id = 'el seudónimo «Zz Test»', f'{namesake} (Person:yy-namesake-civil)'
        ficheros = {
            'pipeline/data/context/figures.yaml': f"""\
                entities:
                - {{type: Person, name: {civil}, entity_id: {CIVIL}, role: Testigo.}}
                """,
            f'{S.RELATIONS_REL}/relations.yaml': f"""\
                splits:
                  - canonical: {{type: Person, name: Zz Seudonimo Test}}
                    namesake: {{type: Person, name: {namesake}}}
                    move_aliases: ['Yy N. Civil Segundo']
                    by_quote: ['se reunió con {namesake}', 'el señor Namesake Civil', 'Civil Segundo', '{civil} estaba',
                               '{palabra}']
                    by_quote_exclude: ['{con_id}']
                  - canonical: {{type: Person, name: {canonico}}}
                    namesake: {{type: Person, name: Zz Seudonimo Test}}
                    by_quote: ['se reunió con {canonico}']
                """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            hallazgos = S.auditar(repo, publicos=frozenset())
            code, salida = ejecutar_check(repo)
        rel = f'{S.RELATIONS_REL}/relations.yaml'
        self.assertEqual(sorted((h.fichero, h.linea, h.clase, h.motivo) for h in hallazgos),
                         sorted([*((rel, 2, 'prosa', self.AC78.format(S.sha16(x))) for x in (civil, palabra, con_id)),
                                 (rel, 8, 'prosa', self.AC78.format(S.sha16(canonico)))]))
        self.assertEqual(code, 1)
        for valor in ('civil apellido', 'canonico civil', 'namesake', 'zz test'):
            self.assertNotIn(valor, salida.lower())

    def test_el_nombre_ficticio_en_una_regla_y_citas_por_su_huella(self):
        """AC90 (enmienda 24): «<seudónimo> es el nombre ficticio de <civil>» en la cita de una regla no lleva la
        palabra ni un id, pero nombra al extremo civil: hallazgo con la huella de la cita. Una entrada de `citas:` de la
        lista con esa huella (el seudónimo y el documento de la regla) la admite; con otra huella o con otro documento,
        no. El CI, sin la cita."""
        civil = 'Zz Civil Apellido'
        cita = f'Zz Test es el nombre ficticio de {civil}'
        ficheros = {
            'data/publico.pdf': '', 'data/otro.pdf': '',
            'pipeline/data/context/figures.yaml': f"""\
                entities:
                - {{type: Person, name: {civil}, entity_id: {CIVIL}, role: Testigo.}}
                """,
            f'{S.RELATIONS_REL}/relations.yaml': f"""\
                fix:
                  - {{source_id: {SEUDO}, target_id: {CIVIL}, type: MET_WITH, doc: publico.pdf,
                     corrected_type: ASSOCIATED_WITH, quote_contains: '{cita}'}}
                """}
        casos = {'sin entrada': ([], True), 'su huella': ([cita_permitida(cita, ['publico.pdf'])], False),
                 'otra huella': ([cita_permitida(cita, ['publico.pdf'], huella='0' * 64)], True),
                 'otro documento': ([cita_permitida(cita, ['otro.pdf'])], True)}
        for caso, (citas, cae) in casos.items():
            with self.subTest(caso), tempfile.TemporaryDirectory() as tmp:
                repo = repo_sintetico(Path(tmp) / 'repo', ficheros, lista={**permitidos((SEUDO, SOC, 'PAID')),
                                                                            'citas': citas})
                hallazgos = S.auditar(repo)
                code, salida = ejecutar_check(repo)
                self.assertEqual([(h.linea, h.clase, h.motivo) for h in hallazgos],
                                 [(2, 'prosa', COAPARICION.format(S.sha16(cita)))] if cae else [])
                self.assertEqual(code, 1 if cae else 0)
                self.assertNotIn('ficticio', salida)

    def test_los_extremos_escritos_por_nombre(self):
        """AC91 (enmienda 24): el nombre con que una regla escribe un extremo se juzga contra ESE extremo, aunque haya
        id: el de un seudónimo es una variante de su nombre de pila (un nombre civil junto a un `source_id` de
        seudónimo cae; «Zz (seudónimo TS) Test» pasa); el de un civil no nombra a un seudónimo; y con id en el mismo
        lado, el texto concuerda con él (deriva el id o es uno de sus nombres en el contexto). El CI, sin los
        nombres."""
