    def test_el_inventario_no_vuelca_claves(self):
        """AC92 (enmienda 24): una clave sin clasificar sale del inventario por su posición y su huella; ni el fallo de
        un test que lo compara la reproduce (la salida de unittest se publica en el CI)."""
        clave = 'CLAVE_CENTINELA_092'
        ficheros = {'pipeline/data/boe/boe.yaml': f"""\
            trayectorias:
            - entity_id: {CIVIL}
              {clave}: x
            """}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros)
            self.assertEqual(S.campos_sin_clasificar(repo),
                             [('pipeline/data/boe/boe.yaml', 2, S.sha16(f'trayectorias[].{clave}'))])

            class Inventario(unittest.TestCase):
                def runTest(self):
                    self.assertEqual(S.campos_sin_clasificar(repo), [])
            salida = io.StringIO()
            resultado = unittest.TextTestRunner(stream=salida, verbosity=2).run(Inventario())
        self.assertEqual(len(resultado.failures), 1)
        self.assertNotIn('CENTINELA', salida.getvalue())

    def test_un_grupo_de_merges_con_seudonimo(self):
        """AC93 (enmienda 24): en un grupo de merges con un seudónimo, cada duplicado es una variante de su nombre de
        pila (fundir en él un nombre civil es hallazgo con su huella); un stub con forma de seudónimo que se funde exige
        su fila en el roster (AC89)."""
        stub = 'Test Zz (seudónimo)'
        ficheros = {'pipeline/data/context/merges.yaml': f"""\
            merges:
            - canonical: {{type: Person, name: Zz Seudonimo Test}}
              duplicates: ['{stub}', Zz Civil Apellido]
            """}
        nombre = f'nombre de un seudónimo fuera de sus variantes (huella {S.sha16("Zz Civil Apellido")})'
        fuera = f'id con forma de seudónimo fuera del roster (huella {S.sha16(S.entity_id("Person", stub))})'
        con_stub = PSEUDONYMS + f'- id: {S.entity_id("Person", stub)}\n  note: stub sintético\n'
        with tempfile.TemporaryDirectory() as tmp:
            sin = S.auditar(repo_sintetico(Path(tmp) / 'sin', ficheros), publicos=frozenset())
            con = S.auditar(repo_sintetico(Path(tmp) / 'con', {**ficheros, S.PSEUDONYMS_REL: con_stub}),
                            publicos=frozenset())
        self.assertEqual(sorted((h.linea, h.clase, h.motivo) for h in sin),
                         [(2, 'prosa', nombre), (2, 'roster-ausente', fuera)])
        self.assertEqual([(h.linea, h.clase, h.motivo) for h in con], [(2, 'prosa', nombre)])


    def test_las_citas_de_una_sociedad_por_su_nombre_completo(self):
        """AC94/AC95 (enmienda 25, reproducciones de Codex): en la cita de una regla de un par permitido seudónimo ↔
        sociedad, la palabra «seudónimo» o el id propio de la sociedad no eximen de la prueba de coaparición (AC90) y
        AC87 cuenta la sociedad por su nombre completo («ese seudónimo» no nombra al seudónimo: sin su mención); la
        razón social sin bigramas («Centinela SA») y el alias de una palabra («Nimbo») nombran a la sociedad; «S.L.»
        sola, no. El CI, sin los nombres."""
        citas = ['Centinela SA es la empresa de ese seudónimo', f'{CENTINELA} es la empresa de Zz Test',
                 'Centinela SA es la empresa de Zz Test', 'Nimbo pagó a Zz Test', 'pagó una S.L. de Madrid a Zz Test']
        ficheros = {
            'data/publico.pdf': '',
            'pipeline/data/context/figures.yaml': 'entities:\n' + CENTINELA_FIGURA + '\n',
            f'{S.RELATIONS_REL}/relations.yaml': 'fix:\n' + ''.join(
                f"  - {{source_id: {SEUDO}, target_id: {CENTINELA}, type: ASSOCIATED_WITH, doc: publico.pdf, "
                f"swap_direction: true, quote_contains: '{cita}'}}\n" for cita in citas)}
        lista = permitidos((SEUDO, SOC, 'PAID'), (SEUDO, CENTINELA, 'ASSOCIATED_WITH'))
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros, lista=lista)
            hallazgos = S.auditar(repo)
            code, salida = ejecutar_check(repo)
        nombre = self.AC78.format(S.sha16('Centinela SA'))
        self.assertEqual(sorted((h.linea, h.motivo) for h in hallazgos), sorted([
            (2, nombre), (2, COAPARICION.format(S.sha16(citas[0]))),
            (3, nombre), (3, COAPARICION.format(S.sha16(citas[1]))),
            (4, COAPARICION.format(S.sha16(citas[2]))), (5, COAPARICION.format(S.sha16(citas[3])))]))
        self.assertEqual(code, 1)
        for valor in ('centinela', 'nimbo', 'zz test'):
            self.assertNotIn(valor, salida.lower())

