    def test_la_cita_con_elipsis_solo_por_citas(self):
        """AC97/AC98 (enmienda 26) en el árbol, con las entradas del snapshot: la cita de una regla de un par permitido
        seudónimo ↔ `Company:nimbo` con una elipsis marcada («Nimbo ... es la empresa de Zz Test») o que acaba a media
        palabra de su documento («Zz Test cobró de Nimbo») es hallazgo AC90 con su huella: el árbol no tiene los chunks
        y la vía (b) es la única, como en el snapshot para toda cita con elipsis. La entrada de `citas:` de la cita
        recompuesta, con su plantilla cerrada, la admite; la de otro seudónimo, no. El CI, sin los nombres."""
        elidida, cortada = 'Nimbo ... es la empresa de Zz Test', 'Zz Test cobró de Nimbo'
        ficheros = {
            'data/publico.pdf': '',
            'pipeline/data/context/figures.yaml': 'entities:\n' + NIMBO_FIGURA + '\n',
            f'{S.RELATIONS_REL}/relations.yaml': 'fix:\n' + ''.join(
                f"  - {{source_id: {SEUDO}, target_id: {NIMBO}, type: ASSOCIATED_WITH, doc: publico.pdf, "
                f"swap_direction: true, quote_contains: '{cita}'}}\n" for cita in (elidida, cortada))}
        base = permitidos((SEUDO, SOC, 'PAID'), (SEUDO, NIMBO, 'ASSOCIATED_WITH'))
        entrada = entrada_spec(elidida, SEUDO, ['publico.pdf'], MOTIVO_ELIPSIS)
        for citas, esperado in (([], [(2, elidida), (3, cortada)]), ([entrada], [(3, cortada)]),
                                ([{**entrada, 'seudonimo': SEUDO2}], [(2, elidida), (3, cortada)])):
            with self.subTest(citas=[c['seudonimo'] for c in citas]), tempfile.TemporaryDirectory() as tmp:
                repo = repo_sintetico(Path(tmp) / 'repo', ficheros, lista={**base, 'citas': citas})
                hallazgos = S.auditar(repo)
                code, salida = ejecutar_check(repo)
                self.assertEqual([(h.linea, h.motivo) for h in hallazgos],
                                 [(linea, COAPARICION.format(S.sha16(c))) for linea, c in esperado])
                self.assertEqual(code, 1)
                for valor in ('nimbo', 'empresa', 'zz test'):
                    self.assertNotIn(valor, salida.lower())

    CONTRATOS = 'pipeline/data/contracts/contracts.yaml'

    @staticmethod
    def contrato(cita, doc=None):
        """Un contrato sintético entre el seudónimo y `Company:nimbo` (sus extremos por nombre, como el loader), con su
        cita y, si acaso, su documento."""
        return ('contracts:\n- {contract: C-1, awarding_body: Zz Seudonimo Test, body_type: Person, awardee: Nimbo, '
                f"awardee_type: Company, {f'doc: {doc}, ' if doc else ''}quote: '{cita}'}}\n")

    def test_la_cita_de_una_capa_con_los_documentos_de_su_fila(self):
        """AC101 (enmienda 27, reproducción de Codex): `auditar` contrasta la cita de una fila de capa con sus
        documentos (`documentos` de su sección en `CAPAS`). El contrato del seudónimo con `Company:nimbo` cuya cita con
        elipsis tiene una entrada de `citas:` de `auto.pdf` es hallazgo AC90 con `doc: otro.pdf` y sin documento (no se
        puede contrastar: fail closed), y pasa con `doc: auto.pdf`. El CI, sin los nombres."""
        cita = 'Nimbo ... es la empresa de Zz Test'
        base = {'data/auto.pdf': '', 'data/otro.pdf': '',
                'pipeline/data/context/figures.yaml': 'entities:\n' + NIMBO_FIGURA + '\n'}
        lista = {**permitidos((SEUDO, SOC, 'PAID')), 'citas': [entrada_spec(cita, SEUDO, ['auto.pdf'], MOTIVO_ELIPSIS)]}
        hallazgo = [(self.CONTRATOS, 2, COAPARICION.format(S.sha16(cita)))]
        for doc, esperado in (('otro.pdf', hallazgo), (None, hallazgo), ('auto.pdf', [])):
            with self.subTest(doc=doc), tempfile.TemporaryDirectory() as tmp:
                repo = repo_sintetico(Path(tmp) / 'repo', {**base, self.CONTRATOS: self.contrato(cita, doc)},
                                      lista=lista)
                self.assertEqual([(h.fichero, h.linea, h.motivo) for h in S.auditar(repo)], esperado)
                code, salida = ejecutar_check(repo)
                self.assertEqual(code, 1 if esperado else 0, salida)
                for valor in ('nimbo', 'empresa', 'zz test'):
                    self.assertNotIn(valor, salida.lower())

