    def test_un_roster_o_un_yaml_que_no_se_leen_paran_con_exit_2(self):
        """AC114/AC115 (enmienda 30, reproducciones de Codex): un roster que no se puede leer (`pseudonyms: null`, una
        fila sin id) para con exit 2 y su motivo, sin valores, en el árbol, en el export y en el loader (antes: árbol
        0 y la política apagada); una sección del registro escrita como mapa, en el árbol y en el inventario. Quitar el
        guion de la fila de una sección cualquiera del inventario nunca da verde."""
        with tempfile.TemporaryDirectory() as tmp:
            snap = Path(tmp) / 'snap'
            snap.mkdir()
            for fichero in ('nodes.jsonl', 'relationships.jsonl'):
                (snap / fichero).write_text('', encoding='utf-8')
            casos = (('nulo', {S.PSEUDONYMS_REL: 'pseudonyms: null\n'}, ((), ('--snapshot', snap))),
                     ('sin-id', {S.PSEUDONYMS_REL: f'pseudonyms:\n- id: {SOLO}\n- note: sin id\n'},
                      ((), ('--snapshot', snap))),
                     ('registro',
                      {S.REGISTRO_REL: f"rectificaciones:\n  entidad: {SOLO}\n  dato: '{SOLO} dirige {SOC}'\n"},
                      ((),)))
            for caso, ficheros, llamadas in casos:
                repo = repo_sintetico(Path(tmp) / caso, ficheros)
                for argv in llamadas:
                    with self.subTest(caso, argv=argv):
                        code, salida = ejecutar_check(repo, *argv)
                        self.assertEqual(code, 2, salida)
                        self.assertIn('FORMA  ', salida)
                        self.assertNotIn('zzsolo', salida.lower())
                with self.subTest(caso, camino='auditar'), self.assertRaises(S.ErrorDeForma):
                    S.auditar(repo, publicos=frozenset())
                if caso == 'registro':
                    with self.assertRaises(S.ErrorDeForma):
                        S.campos_sin_clasificar(repo)
                    continue
                with mock.patch.object(relations_loader.seudonimos, 'PSEUDONYMS_PATH', repo / S.PSEUDONYMS_REL), \
                        contextlib.redirect_stderr(io.StringIO()), self.subTest(caso, camino='loader'), \
                        self.assertRaises(S.ErrorDeForma):
                    relations_loader._prepare_politica(repo / S.RELATIONS_REL)
            for patron, secciones in S.CAPAS.items():
                if patron in (S.PSEUDONYMS_REL, S.PERMITIDOS_REL):   # su validación: AC114 y AC80
                    continue
                path = Path(tmp) / 'guion' / patron.replace('*.y*ml', 'prueba.yaml').replace('*', 'prueba')
                path.parent.mkdir(parents=True, exist_ok=True)
                for seccion in (x for x in secciones if x is not None):
                    if patron == f'{S.RELATIONS_REL}/*.y*ml':   # una que el loader aplica (AC142-AC145: si no, para)
                        fila = REGLAS_VALIDAS[seccion]
                    elif patron == f'{S.CONTEXT_REL}/*.y*ml':   # una que el loader carga entera (AC192: si no, para)
                        fila = {'entities': {'type': 'Person', 'name': 'valor'},
                                'relations': {'source': 'valor', 'target': 'valor', 'type': 'MEMBER_OF'},
                                'summaries': {'entity_id': 'Person:valor', 'resumen': 'valor'},
                                'merges': {'canonical': {'type': 'Person', 'name': 'valor'},
                                           'duplicates': ['otro valor']}}.get(seccion, {'entity_id': 'valor'})
                    else:   # una fila con una clave del inventario (`a.b` es un mapa anidado; `a[]`, una lista)
                        fila = {}
                        ruta = next(k for k in secciones[seccion].campos if '*' not in k)
                        destino, partes = fila, ruta.split('.')
                        for parte in partes[:-1]:
                            destino = destino.setdefault(parte, {})
                        hoja = partes[-1]
                        destino[hoja.removesuffix('[]')] = ['valor'] if hoja.endswith('[]') else 'valor'
                    plana = yaml.safe_dump(fila, default_flow_style=True, allow_unicode=True).strip()
                    path.write_text(f'{seccion}:\n- {plana}\n', encoding='utf-8')
                    S._documento(path)   # con su guion, se lee
                    path.write_text(f'{seccion}:\n  {plana}\n', encoding='utf-8')
                    with self.subTest(patron=patron, seccion=seccion), self.assertRaises(S.ErrorDeForma):
                        S._documento(path)

