    def test_las_reproducciones_de_la_enmienda_31_en_el_arbol(self):
        """AC121/AC123/AC124/AC126/AC129–AC132 (enmienda 31, reproducciones de Codex) en el árbol, con la entrada de
        `citas:` de un tramo para otro documento: la nota del roster con «Centinela S.L.» (sin índice) y la curación con
        «VIII-X-MMXXV» llevan un dato civil; la nota de una regla ««Declaró.» desde 2019» con la entrada del texto
        entero también (solo eximen los tramos); la del estado con su tramo probado para otro documento, también; el
        civil que coincide con un alias inválido de un seudónimo cuenta en su nota y en su fila de roles; «Antonio
        Pedro» en un selector y en un localizador cuenta como «Pedro Antonio»; la cita que nombra «ZX SA» es AC90; y el
        alias de un civil «Nimb0–5tratus» nombra al seudónimo Nimbostratus. El CI, sin los textos."""
        pedro, civil, zx = 'Person:pedro-antonio', 'Person:zz-pedro-antonio-garcia', 'Company:zz-zx-sa'
        tramo, nota_estado = 'Administrador desde 2019.', 'Según el auto: «Administrador desde 2019.»'
        dos_tramos = '«Declaró.» Administrador desde 2019.'
        rel, acus = f'{S.RELATIONS_REL}/relations.yaml', 'pipeline/data/accusations/accusations.yaml'
        ficheros = {
            'data/publico.pdf': '', 'data/otro.pdf': '',
            S.PSEUDONYMS_REL: (f'pseudonyms:\n- id: {SOLO}\n  note: Administrador de Centinela S.L.\n'
                               '  curacion: Administrador desde VIII-X-MMXXV.\n'
                               f'- id: {pedro}\n  note: Lo dijo Pedro Antonio Garcia.\n- id: Person:nimbostratus\n'),
            'pipeline/data/context/figures.yaml': (
                f'entities:\n- {{type: Person, name: Pedro Antonio Garcia, entity_id: {civil}, role: Testigo.}}\n'
                f'- {{type: Company, name: ZX SA, entity_id: {zx}, role: Sociedad.}}\n'),
            'pipeline/data/context/roles_qa061.yaml': (
                f'entities:\n- {{type: Person, name: Pedro Antonio, entity_id: {pedro}, '
                'aliases: [Pedro Antonio Garcia]}\nrelations: []\n'),
            rel: (f'fix:\n  - {{source_id: {SOLO}, target_id: Crime:zz-delito-test, type: ACCUSED_OF, '
                  "doc: publico.pdf, quote_contains: 'Declaró Antonio Pedro ante el juez.', set: {source_page: 3}}\n"
                  f'  - {{source_id: {SOLO}, target_id: {zx}, type: ASSOCIATED_WITH, corrected_type: WORKS_FOR, '
                  "doc: publico.pdf, quote_contains: 'ZX SA pertenece a Zzsolo.'}\n"
                  f'  - {{source_id: {SOLO}, target_id: Crime:zz-otro-delito-test, type: ACCUSED_OF, doc: publico.pdf, '
                  f"set: {{note: '{dos_tramos}'}}}}\n"
                  'splits:\n  - canonical: {type: Person, name: Zzsolo}\n'
                  '    namesake: {type: Person, name: Yy Namesake Civil}\n'
                  "    by_quote: ['con Antonio Pedro estaba']\n"
                  "alias_deny:\n  - {id: Person:yy-civil-test, drop: ['Nimb0\u20135tratus']}\n"
                  "  - {id: Person:yy-civil-test, keep_only: ['Nimb0\u20145tratus']}\n"),
            acus: (f'accusations:\n- person: Zzsolo\n  entity_id: {SOLO}\n'
                   f"  estado: {{status: investigado, fuente: {{doc: otro.pdf}}, nota: '{nota_estado}'}}\n")}
        motivo = 'cita literal del documento judicial público; coaparición verificada en el export 20261007-qa067b'
        citas = [S.entrada_cita(tramo, SOLO, ['publico.pdf'], 'decision-2026-10-08', motivo),
                 S.entrada_cita(dos_tramos, SOLO, ['publico.pdf'], 'decision-2026-10-08', motivo)]
        lista = {**permitidos((SOLO, zx, 'WORKS_FOR')), 'citas': citas}
        with tempfile.TemporaryDirectory() as tmp:
            repo = repo_sintetico(Path(tmp) / 'repo', ficheros, lista=lista)
            hallazgos = S.auditar(repo)
            code, salida = ejecutar_check(repo)
        civil_ = f'{S.MOTIVOS["dato-civil"]} (huella {{}})'
        ac78 = 'texto de una fila de seudónimo nombra a un civil o a un documento (huella {})'
        nombra = 'una entrada nombra a un seudónimo judicial (huella {})'
        esperado = sorted([
            (acus, 2, 'prosa', civil_.format(S.sha16(nota_estado))),
            ('pipeline/data/context/roles_qa061.yaml', 2, 'prosa', ac78.format(S.sha16('Pedro Antonio Garcia'))),
            ('pipeline/data/context/roles_qa061.yaml', 2, 'alias',
             f'{S.MOTIVOS["alias-capa"]} (huella {S.sha16("Pedro Antonio Garcia")})'),
            (S.PSEUDONYMS_REL, 2, 'prosa', civil_.format(S.sha16('Administrador de Centinela S.L.'))),
            (S.PSEUDONYMS_REL, 2, 'prosa', civil_.format(S.sha16('Administrador desde VIII-X-MMXXV.'))),
            (S.PSEUDONYMS_REL, 5, 'prosa', ac78.format(S.sha16('Pedro Antonio Garcia'))),
            (S.PSEUDONYMS_REL, 5, 'roster',
             f'una fila nombra a una persona civil (huella {S.sha16("Pedro Antonio Garcia")})'),
            (rel, 2, 'prosa', f'{S.MOTIVOS["pila"]} (huella {S.sha16("Declaró Antonio Pedro ante el juez.")})'),
            (rel, 3, 'prosa', COAPARICION.format(S.sha16('ZX SA pertenece a Zzsolo.'))),
            (rel, 4, 'prosa', civil_.format(S.sha16(dos_tramos))),
            (rel, 6, 'prosa', ac78.format(S.sha16('pedro antonio'))),
            (rel, 10, 'alias_deny', nombra.format(S.sha16('Nimb0\u20135tratus'))),
            (rel, 11, 'alias_deny', nombra.format(S.sha16('Nimb0\u20145tratus')))])
        self.assertEqual(sorted((h.fichero, h.linea, h.clase, h.motivo) for h in hallazgos), esperado)
        self.assertEqual(code, 1)
        for valor in ('centinela', 'pedro', 'zx sa', '2019', 'nimb0'):
            self.assertNotIn(valor, salida.lower())

    def test_una_clave_fuera_del_inventario_para_con_exit_2(self):
        """AC127 (enmienda 31, reproducción de Codex): una clave que el inventario no clasifica, sea cual sea su valor
        (nulo, número, contenedor vacío, texto) y aunque tenga forma de id de entidad, para el árbol y el export con
        exit 2 y su huella, nunca la clave: en una fila del roster (`'Company:zz-nimbo': null`, antes 0 hallazgos) y en
        una de cualquier capa. El inventario la lista, también sin texto."""
        rel = f'{S.RELATIONS_REL}/relations.yaml'
        casos = {'roster null': {S.PSEUDONYMS_REL: f"pseudonyms:\n- id: {SOLO}\n  'Company:zz-nimbo': null\n"},
                 'roster número': {S.PSEUDONYMS_REL: f'pseudonyms:\n- id: {SOLO}\n  zz: 12345\n'},
                 'regla': {rel: (f'fix:\n  - {{source_id: {SOLO}, target_id: Crime:zz-delito-test, type: ACCUSED_OF, '
                                 "corrected_type: CONVICTED_OF, 'Company:zz-nimbo': null, zz: 12345, vacia: [], "
                                 "mapa: {}}\n")}}
        with tempfile.TemporaryDirectory() as tmp:
            snap = self.snapshot_vacio(Path(tmp) / 'snap')
            for caso, ficheros in casos.items():
                repo = repo_sintetico(Path(tmp) / caso.replace(' ', '-'), ficheros)
                with self.subTest(caso), self.assertRaises(S.ErrorDeForma) as fin:
                    S.auditar(repo, publicos=frozenset())
                inventario = [m for m in fin.exception.motivos if 'clave fuera del inventario (huella ' in m]
                self.assertEqual(len(inventario), 1 if caso.startswith('roster') else 4)
                self.assertEqual(fin.exception.motivos, inventario if caso.startswith('roster') else [  # AC145
                    *inventario, f'forma inválida (spec 070): {rel}: `fix`[0]: una clave que no es de una regla fix'])
                for argv in ((), ('--snapshot', snap)) if caso.startswith('roster') else ((),):
                    with self.subTest(caso, argv=argv):
                        code, salida = ejecutar_check(repo, *argv)
                        self.assertEqual(code, 2, salida)
                        self.assertNotIn('nimbo', salida.lower())
                        self.assertNotIn('12345', salida)
                if caso == 'regla':
                    self.assertEqual(S.campos_sin_clasificar(repo), sorted(
                        (rel, 2, S.sha16(f'fix[].{ruta}')) for ruta in ('Company:zz-nimbo', 'zz', 'vacia', 'mapa')))

