    def test_las_claves_con_separadores_y_las_correcciones_vacias_paran(self):
        """AC142 (enmienda 32, reproducción de Codex): una clave literal con un separador reservado («set.note»,
        «quote_contains.doc», «drop[]»), sea cual sea su valor, no se confunde con la ruta anidada: el árbol para con
        exit 2 y su huella, y el inventario la lista (antes, «set.note» pasaba y el loader descartaba la corrección);
        una corrección que no hace nada o con un `set` que no es un mapa, también. El `set: {note: …}` anidado, sin
        cambios."""
        rel = f'{S.RELATIONS_REL}/relations.yaml'
        base = f'source_id: {SOLO}, target_id: Crime:zz-delito-test, type: ACCUSED_OF'
        casos = {f'set.note {v}': (f"fix:\n  - {{{base}, 'set.note': {v}}}\n", 'clave fuera del inventario')
                 for v in ('null', '12345', '[]', '{}', 'texto')}
        casos['quote_contains.doc'] = (f"fix:\n  - {{{base}, corrected_type: WORKS_FOR, "
                                       "'quote_contains.doc': x.pdf}\n", 'clave fuera del inventario')
        casos['drop[]'] = ("alias_deny:\n  - {id: Person:yy-civil-test, 'drop[]': [x]}\n", 'clave fuera del inventario')
        casos['sin efecto'] = (f'fix:\n  - {{{base}}}\n', 'regla fix sin efecto')
        casos['set lista'] = (f'fix:\n  - {{{base}, corrected_type: WORKS_FOR, set: [note]}}\n',
                              'corrección con un `set` que no es un mapa con propiedades')
        with tempfile.TemporaryDirectory() as tmp:
            for caso, (texto, motivo) in casos.items():
                repo = repo_sintetico(Path(tmp) / caso.replace(' ', '-').replace('[]', 'l'), {rel: texto})
                with self.subTest(caso), self.assertRaises(S.ErrorDeForma) as fin:
                    S.auditar(repo, publicos=frozenset())
                self.assertTrue(any(motivo in m for m in fin.exception.motivos), fin.exception.motivos)
                code, salida = ejecutar_check(repo)
                self.assertEqual(code, 2, salida)
                if motivo == 'clave fuera del inventario':
                    self.assertTrue(S.campos_sin_clasificar(repo))
            bien = repo_sintetico(Path(tmp) / 'anidado',
                                  {rel: f"fix:\n  - {{{base}, set: {{note: 'Nota neutra.'}}}}\n"})
            self.assertEqual(S.campos_sin_clasificar(bien), [])
            self.assertEqual(ejecutar_check(bien)[0], 0)

    def test_una_regla_fix_sin_efecto_para_el_arbol(self):
        """AC143 (residual de la enmienda 32): una regla `fix` sin un `corrected_type` distinto de su `type`, sin
        `swap_direction` verdadero y sin un `set` que el loader aplique es «regla fix sin efecto»: el árbol para con
        exit 2 y su posición (antes, 0 hallazgos, y el loader la descartaba con un aviso). AC144 (enmienda 33): un `set`
        que el loader no aplica (una capa que no degrada, uno que no es un mapa) para por sí mismo, con su motivo,
        aunque la regla también retipe. AC155 (enmienda 35): un `swap_direction` de texto («True», «False») tampoco
        carga. Con un `set` aplicable, un swap verdadero o un retype, vale aunque el tipo no cambie."""
        rel = f'{S.RELATIONS_REL}/relations.yaml'
        base = f'source_id: {SOLO}, target_id: Crime:zz-delito-test, type: ACCUSED_OF'
        sin_efecto = {'sin nada': '', 'el mismo tipo': ', corrected_type: ACCUSED_OF',
                      'swap falso': ', swap_direction: false',
                      'el mismo tipo y swap falso': ', corrected_type: ACCUSED_OF, swap_direction: false'}
        capa = 'corrección con un `set` cuya capa no degrada una arista judicial'
        cadena = 'una corrección cuyo `swap_direction` no es un booleano'
        malos = {'swap «False»': (", swap_direction: 'False'", [cadena]),
                 'swap «True»': (", corrected_type: CONVICTED_OF, swap_direction: 'True'", [cadena]),
                 'solo un set que el loader no aplica': (', set: {source_kind: judicial}', [capa]),
                 'retype con un set que el loader no aplica': (', corrected_type: CONVICTED_OF, '
                                                               'set: {source_kind: judicial}', [capa]),
                 'set que no es un mapa': (', set: [note]', [
                     f'clave fuera del inventario (huella {S.sha16("set[]")})',
                     'corrección con un `set` que no es un mapa con propiedades'])}
        validos = {'set con el mismo tipo': ", corrected_type: ACCUSED_OF, set: {note: 'Nota neutra.'}",
                   'swap verdadero': ', swap_direction: true', 'retype': ', corrected_type: CONVICTED_OF'}
        with tempfile.TemporaryDirectory() as tmp:
            for caso, extra in {**{c: (e, ['regla fix sin efecto']) for c, e in sin_efecto.items()},
                                **malos}.items():
                texto, motivos = extra
                repo = repo_sintetico(Path(tmp) / caso.replace(' ', '-').replace('«', '').replace('»', ''),
                                      {rel: f'fix:\n  - {{{base}{texto}}}\n'})
                with self.subTest(caso), self.assertRaises(S.ErrorDeForma) as fin:
                    S.auditar(repo, publicos=frozenset())
                self.assertEqual(fin.exception.motivos,
                                 [f'forma inválida (spec 070): {rel}: `fix`[0]: {m}' for m in motivos])
                self.assertEqual(ejecutar_check(repo)[0], 2)
            for caso, extra in validos.items():
                repo = repo_sintetico(Path(tmp) / caso.replace(' ', '-').replace('«', '').replace('»', ''),
                                      {rel: f'fix:\n  - {{{base}{extra}}}\n'})
                with self.subTest(caso):
                    S.auditar(repo, publicos=frozenset())
                    self.assertNotEqual(ejecutar_check(repo)[0], 2)

