            self.assertEqual(S.verificar_snapshot(snap, IDS, data), [unido])
            # El organismo fixture sin entity_id de la puerta (`_qa063b_dev.sh fixture-up`), si sobrevive.
            self.snapshot(snap, nodes + [{'ref': 'f', 'labels': ['Organization'], 'props': {'name': S.FIXTURE_SIN_ID}}],
                          rels)
            esperado, cuentas = ['el nodo fixture sin entity_id sigue en el grafo', unido], {}
