    def test_el_texto_y_la_procedencia_de_una_arista_de_seudonimo(self):
        """AC78/AC79 (enmienda 21, decisiones): en el export, la cita de una arista de seudónimo puede nombrar a su otro
        extremo si es literal en un chunk de su documento (AC90, enmienda 24) y su procedencia (`source_doc`) puede ser
        un documento que el árbol no versiona si es un nodo Document del export; su nota no nombra al civil, ni un PDF
        fuera del árbol público, y una procedencia sin nodo Document es hallazgo. La nota de una arista entre civiles
        que identifica al seudónimo, también (AC79). Sin `publicos`, ni el PDF ni la procedencia se comprueban."""
        civil, otro = 'Zz Civil Apellido', 'Person:yy-otro-civil'
        nodos = self.nodes() + [
            {'ref': 'd', 'labels': ['Document'], 'props': {'doc_id': 'NO_VERSIONADO.pdf', 'title': civil}},
            # AC90 (enmienda 24): la coaparición pasa porque el tribunal la publicó, literal en un chunk del documento.
            {'ref': 'k', 'labels': ['Chunk'], 'props': {'doc_id': 'NO_VERSIONADO.pdf',
                                                         'text': f'Dice el auto que {civil}  se reunió con él.'}},
            {'ref': 'q', 'labels': ['Person'], 'props': {'entity_id': otro, 'name': 'Yy Otro Civil'}}]
        nodos[3]['props']['name'] = civil   # `p`, el civil
        lista = permitidos((SEUDO, SOC, 'PAID'), alias=[(SEUDO, ['don Zz Test'])])
        rels = [self.pagada(),
                {'ref': 'r2', 'start': 's', 'end': 'p', 'type': 'MET_WITH', 'props': {
                    'source_kind': 'judicial', 'source_doc': 'NO_VERSIONADO.pdf',
                    'source_quote': f'{civil} se reunió con él'}},
                {'ref': 'r3', 'start': 's', 'end': 'p', 'type': 'ASSOCIATED_WITH',
                 'props': {'note': f'Socio de {civil}.'}},
                {'ref': 'r4', 'start': 's', 'end': 'q', 'type': 'ASSOCIATED_WITH',
                 'props': {'note': 'Según PRIVADO_CENTINELA.pdf p.1'}},
                {'ref': 'r5', 'start': 's', 'end': 'q', 'type': 'WORKS_FOR',
                 'props': {'source_kind': 'judicial', 'source_doc': 'SIN_NODO_CENTINELA.pdf'}},
                {'ref': 'r6', 'start': 'p', 'end': 'q', 'type': 'WORKS_FOR',
                 'props': {'note': 'Identificado como el seudónimo «Zz Test».'}}]
        ac78 = 'texto de una arista de seudónimo nombra a un civil o a un documento (arista {}, huella {})'
        nota = f'texto de una arista civil que nombra a un seudónimo judicial (arista r6, huella {S.sha16(SEUDO)})'
        with tempfile.TemporaryDirectory() as tmp:
            snap = Path(tmp) / 'snap'
            snap.mkdir()
            self.snapshot(snap, nodos, rels)
            sin_cita = [SIN_CITA.format(r) for r in ('r3', 'r4', 'r5')]   # AC148: aristas mixtas sin cita
            self.assertEqual(S.verificar_snapshot(snap, IDS, lista), [ac78.format('r3', S.sha16(civil)), *sin_cita,
                                                                      nota])
            self.assertEqual(S.verificar_snapshot(snap, IDS, lista, publicos=frozenset()), [
                ac78.format('r3', S.sha16(civil)), sin_cita[0], ac78.format('r4', S.sha16('PRIVADO_CENTINELA.pdf')),
                sin_cita[1], 'procedencia (`source_doc`) de una arista de seudónimo sin nodo Document en el export '
                f'(arista r5, huella {S.sha16("SIN_NODO_CENTINELA.pdf")})', sin_cita[2], nota])
            code, salida = ejecutar_check(repo_sintetico(Path(tmp) / 'repo', lista=lista), '--snapshot', snap)
        self.assertEqual(code, 1)
        for privado in ('CENTINELA', 'Zz Civil', 'NO_VERSIONADO'):
            self.assertNotIn(privado, salida)

