    def test_el_nombre_y_los_alias_de_un_nodo_civil(self):
        """AC86 (enmienda 23): el `name`, el `canonical_name`, el `name_original` y los `aliases` de un nodo de persona
        o sociedad fuera del roster se leen como en el árbol: cada uno que identifica al seudónimo es hallazgo, con la
        referencia y la huella del seudónimo, y (AC167, enmienda 36) es un nombre que identifica, con la del nombre. Un
        civil con el nombre de pila del seudónimo sin la palabra, no. El CI termina sin los nombres."""
        marcado = 'Yy Civil (seudónimo Zz Test)'
        casos = [('Person', 'name', marcado), ('Person', 'canonical_name', marcado),
                 ('Person', 'name_original', marcado), ('Person', 'aliases', [marcado]),
                 ('Company', 'name', 'Yy Sociedad (seudónimo Zz Test)'), ('Person', 'name', 'Zz Test Garcia')]
        nodos = self.nodes() + [{'ref': f'n{i}', 'labels': [etiqueta],
                                 'props': {'entity_id': f'{etiqueta}:yy-civil-{i}', clave: valor}}
                                for i, (etiqueta, clave, valor) in enumerate(casos)]
        lista = permitidos((SEUDO, SOC, 'PAID'), alias=[(SEUDO, ['don Zz Test'])])
        rels = [self.pagada()]
        civil = 'prosa de un nodo civil que nombra a un seudónimo judicial (nodo n{}, huella {})'
        identificador = S.MOTIVOS['alias-identificador'] + ' (nodo n{}, huella {})'
        nombres = [marcado] * 4 + ['Yy Sociedad (seudónimo Zz Test)']
        with tempfile.TemporaryDirectory() as tmp:
            snap = Path(tmp) / 'snap'
            snap.mkdir()
            self.snapshot(snap, nodos, rels)
            self.assertEqual(S.verificar_snapshot(snap, IDS, lista),
                             [m for i in range(5) for m in (civil.format(i, S.sha16(SEUDO)),
                                                           identificador.format(i, S.sha16(nombres[i])))])
            code, salida = ejecutar_check(repo_sintetico(Path(tmp) / 'repo', lista=lista), '--snapshot', snap)
        self.assertEqual(code, 1)
        for valor in ('yy civil', 'yy sociedad', 'zz test'):
            self.assertNotIn(valor, salida.lower())

