    def test_las_reproducciones_de_la_enmienda_27_en_el_cli(self):
        """AC100–AC102 y la reproducción 1 (enmienda 27, reproducciones de Codex) en el CLI `--snapshot`: par permitido
        seudónimo ↔ `Company:nimbo`, documento público y una sola entrada de `citas:`, la de «Nimbo ... es la empresa
        controlada por Zz Test, afirmación desmentida por el tribunal.» (`auto.pdf`). Son hallazgo AC90, con la huella
        de cada cita y nunca su texto: las particiones con guion («culpable que Nimbo pagó a Zz Test» sobre «Era in-\\n
        culpable…», «Zz Test cobró de Nimbo» sobre «…Nimbo-\\n stratus»), las marcas de elipsis que la cita cruda
        escondía («[. . .]», «. . .», tres U+2024, «(...)», U+22EF) y «…» pegado, la cita recortada de la revisada (otra
        huella: la entrada admite solo su texto exacto) y la revisada en una arista sin documento (AC101). Pasan la
        partición unida en la cita, «S.L.U.» literal y la revisada en su documento."""
        chunks = ['Era in-\n culpable que Nimbo pagó a Zz Test.', 'Zz Test cobró de Nimbo-\n stratus.',
                  'Nimbo es la empresa de Zz Test, afirmación que el tribunal rechaza.',
                  'Consta que Nimbo, S.L.U. pagó a Zz Test.']
        revisada = 'Nimbo ... es la empresa controlada por Zz Test, afirmación desmentida por el tribunal.'
        recortada = 'Nimbo ... es la empresa controlada por Zz Test'
        caen = ['culpable que Nimbo pagó a Zz Test', 'Zz Test cobró de Nimbo',
                *(f'Nimbo es la empresa de Zz Test {marca}'
                  for marca in ('[. . .]', '. . .', '\u2024\u2024\u2024', '(...)', '\u22ef')),
                'Nimbo es la empresa\u2026 de Zz Test', recortada]
        pasan = ['Era inculpable que Nimbo pagó a Zz Test', 'Nimbo S.L.U. pagó a Zz Test', revisada]
        nodos = self.nodes() + [{'ref': 'n', 'labels': ['Company'], 'props': {'entity_id': NIMBO, 'name': 'Nimbo'}},
                                {'ref': 'd', 'labels': ['Document'], 'props': {'doc_id': 'auto.pdf'}}]
        nodos += [{'ref': f'k{i}', 'labels': ['Chunk'], 'props': {'doc_id': 'auto.pdf', 'text': chunk}}
                  for i, chunk in enumerate(chunks)]

        def arista(i, cita, doc='auto.pdf'):
            return {'ref': f'r{i}', 'start': 's', 'end': 'n', 'type': 'ASSOCIATED_WITH',
                    'props': {'source_kind': 'judicial', 'source_quote': cita, **({'source_doc': doc} if doc else {})}}
        citas = [*caen, *pasan]
        rels = [arista(i, cita) for i, cita in enumerate(citas)] + [arista(len(citas), revisada, doc=None)]
        lista = {**permitidos((SEUDO, NIMBO, 'ASSOCIATED_WITH'), alias=[(SEUDO, ['don Zz Test'])]),
                 'citas': [entrada_spec(revisada, SEUDO, ['auto.pdf'], MOTIVO_ELIPSIS)]}
        coaparicion = 'cita que nombra a su extremo civil sin prueba de coaparición (arista r{}, huella {})'
        esperado = [coaparicion.format(i, S.sha16(cita)) for i, cita in enumerate(caen)]
        esperado.append(coaparicion.format(len(citas), S.sha16(revisada)))
        with tempfile.TemporaryDirectory() as tmp:
            snap = Path(tmp) / 'snap'
            snap.mkdir()
            self.snapshot(snap, nodos, rels)
            self.assertEqual(S.verificar_snapshot(snap, IDS, lista), esperado)
            code, salida = ejecutar_check(repo_sintetico(Path(tmp) / 'repo', {'data/auto.pdf': ''}, lista=lista),
                                          '--snapshot', snap)
        self.assertEqual(code, 1, salida)
        self.assertEqual([linea for linea in salida.splitlines() if linea.startswith('SNAPSHOT')],
                         [f'SNAPSHOT  {problema}' for problema in esperado])
        for valor in ('nimbo', 'culpable', 'empresa', 'zz test'):
            self.assertNotIn(valor, salida.lower())

    def test_las_reproducciones_de_la_enmienda_28_en_el_export(self):
        """AC104/AC105 (enmienda 28) en el CLI `--snapshot`, con `citas: []`: la arista judicial del seudónimo con
        `Company:nimbo` cuya cita parte el nombre («Nim-\\nbo ... es la empresa de Zz Test», sobre el chunk «Nimbo no es
        la empresa…») es hallazgo AC90; el alias de un nodo civil escrito con homógrafos griegos y cirílicos de ZZ TEST
        con la marca del roster nombra al seudónimo y es sospechoso; las aristas civiles cuya cita nombra al seudónimo
        partido, o con su nombre entero en cirílico (también sospechosa), lo nombran. Control: «Nim - bo» no nombra a
        Nimbo. AC167 (enmienda 36): el alias del nodo civil es además un alias que identifica. Con las huellas, nunca
        los textos."""
        partida, control = 'Nim-\nbo ... es la empresa de Zz Test', 'Nim - bo es la empresa de Zz Test'
        alias = '\u0396\u0396 \u03a4\u0395\u0405\u03a4 (seudónimo TS)'
        citas = ('según el auto, el seudónimo «Zz Te-\nst» cobró',
                 'según el auto, el seudónimo Zz \u0422\u0415\u0405\u0422 cobró')
        nodos = self.nodes() + [{'ref': 'n', 'labels': ['Company'], 'props': {'entity_id': NIMBO, 'name': 'Nimbo'}},
                                {'ref': 'd', 'labels': ['Document'], 'props': {'doc_id': 'auto.pdf'}},
                                {'ref': 'k', 'labels': ['Chunk'],
                                 'props': {'doc_id': 'auto.pdf', 'text': 'Nimbo no es la empresa de Zz Test.'}}]
        nodos[3]['props'].update(name='Zz Civil Apellido', aliases=[alias])   # `p`, un civil

        def arista(ref, start, end, tipo, cita):
            return {'ref': ref, 'start': start, 'end': end, 'type': tipo,
                    'props': {'source_kind': 'judicial', 'source_doc': 'auto.pdf', 'source_quote': cita}}
