        nodos[0]['props']['summary'] = resumen

        def arista(ref, start, end, tipo, cita):
            return {'ref': ref, 'start': start, 'end': end, 'type': tipo,
                    'props': {'source_kind': 'judicial', 'source_doc': 'auto.pdf', 'source_quote': cita}}
        rels = [arista(f'r{i + 1}', 's', 'n', 'ASSOCIATED_WITH', cita)
                for i, cita in enumerate((rayada, cero, *controles))]
        rels.append(arista('r5', 'p', 'o', 'WORKS_FOR', 'según el art. 31-bis, Yy Civil cobró'))
        lista = permitidos((SEUDO, NIMBO, 'ASSOCIATED_WITH'), alias=[(SEUDO, ['don Zz Test'])])
        coaparicion = 'cita que nombra a su extremo civil sin prueba de coaparición (arista {}, huella {})'
        esperado = [f'texto de un nodo de seudónimo nombra a un civil o a un documento (nodo s, huella '
                    f'{S.sha16("Nimbo Stratus")})',
                    coaparicion.format('r1', S.sha16(rayada)), coaparicion.format('r2', S.sha16(cero)),
                    NO_NOMBRA.format('r4')]   # AC148: el control que no nombra a la sociedad
        with tempfile.TemporaryDirectory() as tmp:
            snap = Path(tmp) / 'snap'
            snap.mkdir()
            self.snapshot(snap, nodos, rels)
            self.assertEqual(S.verificar_snapshot(snap, IDS, lista), esperado)
            code, salida = ejecutar_check(repo_sintetico(Path(tmp) / 'repo', {'data/auto.pdf': ''}, lista=lista),
                                          '--snapshot', snap)
        self.assertEqual(code, 1, salida)
        self.assertEqual([linea for linea in salida.splitlines() if linea.startswith('SNAPSHOT')],
                         [f'SNAPSHOT  {problema}' for problema in esperado])
        for valor in ('nimb', 'empresa', 'culpable', 'stratus', 'zz test'):
            self.assertNotIn(valor, salida.lower())

