    def test_el_mensaje_lleva_la_huella_y_el_code_point_nunca_el_valor_y_sale_una_vez_por_valor(self):
        valor = 'Os\u2506CENTINELA_VALOR\u0131ar'
        nodos = self.seudonimos() + [{'ref': 'c', 'labels': ['Court'], 'props': {
            'entity_id': 'Court:zz-sala', 'name': valor, 'canonical_name': valor, 'aliases': [valor, valor]}}]
