    def test_el_mensaje_enumera_como_mucho_8_code_points(self):
        valor = 'Os' + ''.join(chr(0x2500 + i) for i in range(12)) + 'ar'
        nodos = self.seudonimos() + [{'ref': 'c', 'labels': ['Court'], 'props': {'entity_id': 'Court:zz-sala', 'name': valor}}]
        problemas = [p for p in self.verificar(nodos) if p.startswith(self.MOTIVO + ' ')]
        self.assertEqual(len(problemas), 1)
        self.assertEqual(len(re.findall(r'U\+25[0-9A-F]{2}', problemas[0])), 8)
        self.assertIn('y 4 más', problemas[0])
        self.assertEqual(S.caracteres_no_permitidos(valor, S._ALFABETO_NOMBRES), sorted(f'U+{0x2500 + i:04X}' for i in range(12)))

    def test_otro_alfabeto_lee_latin_como_una_palabra_del_nombre_unicode(self):
        """El bug de `'LATIN' not in nombre` (subcadena): la «LATINATE» glagolítica (U+2C2E, U+2C5E) pasaba por una letra latina. Como palabra, solo
        las dos cambian; las letras latinas de verdad (también las supraescritas y las de ancho completo) siguen siéndolo."""
        for c in ('\u2c2e', '\u2c5e'):
            self.assertTrue(S._otro_alfabeto(c), f'U+{ord(c):04X}')
            self.assertTrue(S.texto_sospechoso(f'Os{c}ar'), f'U+{ord(c):04X}')
        for c in ('a', 'Ñ', 'ñ', '\u0131', '\u0142', '\u2071', '\u207f', '\uff21'):
            self.assertFalse(S._otro_alfabeto(c), f'U+{ord(c):04X}')
        self.assertEqual([cp for cp in range(0x110000) if unicodedata.category(chr(cp)).startswith('L') and unicodedata.name(chr(cp), None)
                          and 'LATIN' in unicodedata.name(chr(cp)) and 'LATIN' not in unicodedata.name(chr(cp)).split()], [0x2C2E, 0x2C5E])

